:root{
  --ink:#050912;
  --ink-2:#08101f;
  --panel:rgba(7,14,27,.74);
  --panel-solid:#0a1324;
  --line:rgba(255,255,255,.13);
  --line-soft:rgba(255,255,255,.07);
  --paper:#f7f2e5;
  --muted:rgba(235,240,250,.56);
  --gold:#f7c950;
  --gold-2:#e9a62b;
  --gold-3:#a96a14;
  --cyan:#78e4ff;
  --green:#66e4a4;
  --red:#ff6358;
  --display:'Barlow Condensed',Impact,sans-serif;
  --body:'Manrope',system-ui,sans-serif;
  --safe-top:env(safe-area-inset-top,0px);
  --safe-bottom:env(safe-area-inset-bottom,0px);
}

*{box-sizing:border-box;margin:0;padding:0}
html,body{height:100%;background:var(--ink);overflow:hidden}
body{
  font-family:var(--body);color:var(--paper);-webkit-font-smoothing:antialiased;
  text-rendering:optimizeLegibility;user-select:none;-webkit-user-select:none;
  touch-action:manipulation;
}
button{font:inherit;color:inherit;background:none;border:0;cursor:pointer;-webkit-tap-highlight-color:transparent}
button:focus-visible{outline:2px solid var(--gold);outline-offset:3px}
kbd{
  display:inline-flex;align-items:center;justify-content:center;min-width:22px;height:22px;
  padding:0 5px;border:1px solid rgba(255,255,255,.22);border-bottom-color:rgba(255,255,255,.35);
  border-radius:4px;background:rgba(255,255,255,.06);font-family:var(--body);font-size:9px;
  font-weight:700;letter-spacing:.04em;color:#fff;vertical-align:1px;
}
#app{position:fixed;inset:0;overflow:hidden;isolation:isolate;background:#040711}
#stage{position:absolute;inset:0;width:100%;height:100%;display:block}
.atmosphere{position:absolute;inset:0;pointer-events:none;z-index:2}
.vignette{
  position:absolute;inset:0;background:
    radial-gradient(ellipse at 50% 44%, transparent 38%, rgba(0,3,10,.25) 76%, rgba(0,2,7,.68) 100%),
    linear-gradient(to bottom, rgba(1,4,12,.25), transparent 20%, transparent 74%, rgba(1,4,10,.54));
}
.grain{
  position:absolute;inset:-60%;opacity:.055;pointer-events:none;
  background-image:url("data:image/svg+xml,%3Csvg viewBox='0 0 220 220' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='.9' numOctaves='4' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='.7'/%3E%3C/svg%3E");
  animation:grainShift .45s steps(2) infinite;mix-blend-mode:overlay;
}
@keyframes grainShift{0%{transform:translate(0,0)}25%{transform:translate(2%,-1%)}50%{transform:translate(-1%,2%)}75%{transform:translate(1%,1%)}100%{transform:translate(-2%,-1%)}}

/* ---------- screens ---------- */
.screen{
  position:absolute;inset:0;z-index:4;opacity:0;visibility:hidden;
  transition:opacity .42s ease,visibility .42s;
  pointer-events:none;
}
.screen.is-active{opacity:1;visibility:visible}
.screen.is-active button,.screen.is-active a,.screen.is-active .interactive{pointer-events:auto}
.screen.is-leaving{opacity:0;transition:opacity .3s ease}
.glass{
  background:linear-gradient(145deg,rgba(15,25,45,.82),rgba(5,11,22,.78));
  border:1px solid var(--line);
  box-shadow:0 30px 80px rgba(0,0,0,.38),inset 0 1px 0 rgba(255,255,255,.07);
  backdrop-filter:blur(20px) saturate(1.25);
  -webkit-backdrop-filter:blur(20px) saturate(1.25);
}

/* ---------- typography helpers ---------- */
.section-kicker{
  font-size:10px;font-weight:800;letter-spacing:.26em;color:var(--gold);
  text-transform:uppercase;display:flex;align-items:center;gap:9px;
}
.section-kicker::before{content:'';width:18px;height:1px;background:currentColor;opacity:.75}
.panel-title{font-family:var(--display);font-weight:700;font-size:clamp(42px,5vw,64px);line-height:.95;letter-spacing:-.025em;text-transform:uppercase}
.panel-title em{font-style:italic;color:var(--gold);font-weight:600}
.panel-sub{color:var(--muted);font-size:13px;line-height:1.6;margin-top:12px}

/* ---------- topbar ---------- */
.topbar{
  position:absolute;top:0;left:0;right:0;z-index:10;height:82px;
  padding:calc(20px + var(--safe-top)) clamp(22px,3.6vw,58px) 0;
  display:flex;align-items:flex-start;justify-content:space-between;gap:24px;
}
.brand{display:flex;align-items:center;gap:13px;text-decoration:none;color:inherit}
.rings{display:block;width:50px;filter:drop-shadow(0 2px 12px rgba(255,206,96,.22))}
.rings svg{display:block;width:100%;overflow:visible}
.brand-copy{display:flex;flex-direction:column;line-height:1}
.brand-copy b{font-family:var(--display);font-size:24px;font-weight:800;letter-spacing:.12em}
.brand-copy small{font-size:7px;letter-spacing:.38em;color:var(--muted);margin-top:4px;font-weight:700}
.topbar-center{
  position:absolute;left:50%;top:31px;transform:translateX(-50%);
  font-size:8px;letter-spacing:.25em;font-weight:700;color:rgba(255,255,255,.55);
  display:flex;align-items:center;gap:9px;white-space:nowrap;
}
.live-dot{width:6px;height:6px;border-radius:50%;background:var(--red);box-shadow:0 0 10px var(--red);animation:pulse 1.8s infinite}
@keyframes pulse{0%,100%{opacity:1;transform:scale(1)}50%{opacity:.35;transform:scale(.75)}}
.slash{opacity:.3}
.topbar-actions{display:flex;gap:8px;align-items:center}
.icon-btn{
  width:40px;height:40px;border-radius:50%;border:1px solid rgba(255,255,255,.14);
  background:rgba(8,14,26,.4);backdrop-filter:blur(12px);display:grid;place-items:center;
  transition:.2s ease;color:rgba(255,255,255,.8);
}
.icon-btn:hover{background:rgba(247,201,80,.12);border-color:rgba(247,201,80,.5);color:var(--gold);transform:translateY(-1px)}
.icon-btn svg{width:18px;height:18px}
#soundBtn .ico-muted{display:none}
#soundBtn.is-muted .ico-sound{display:none}
#soundBtn.is-muted .ico-muted{display:block}

/* ---------- main menu ---------- */
#menu{
  background:
    linear-gradient(90deg,rgba(3,7,16,.92) 0%,rgba(3,7,16,.68) 31%,rgba(3,7,16,.12) 58%,rgba(3,7,16,.55) 100%),
    linear-gradient(to bottom,rgba(2,5,12,.38),transparent 24%,transparent 72%,rgba(2,5,12,.82));
}
.menu-content{
  position:absolute;inset:0;padding:100px clamp(24px,5.5vw,92px) 80px;
  display:grid;grid-template-columns:minmax(0,1fr) clamp(310px,29vw,430px);
  align-items:center;gap:clamp(30px,6vw,120px);
}
.hero-copy{max-width:700px;padding-top:1vh;transform:translateY(12px);opacity:0}
#menu.is-active .hero-copy{animation:riseIn .85s .08s cubic-bezier(.2,.8,.2,1) forwards}
@keyframes riseIn{to{transform:translateY(0);opacity:1}}
.eyebrow{
  display:flex;align-items:center;gap:11px;font-size:9px;font-weight:800;
  letter-spacing:.29em;color:rgba(245,241,229,.68);text-transform:uppercase;margin-bottom:20px;
}
.eyebrow span{
  color:var(--ink);background:var(--gold);padding:4px 7px 3px;border-radius:2px;
  font-weight:800;letter-spacing:.14em;font-size:9px;
}
.eyebrow i{width:28px;height:1px;background:rgba(255,255,255,.28);margin-left:3px}
.mega-title{position:relative;line-height:.72;margin-left:-4px}
.mega-title .word{
  display:block;font-family:var(--display);font-size:clamp(112px,13.6vw,214px);font-weight:900;
  letter-spacing:-.035em;line-height:.72;
  background:linear-gradient(175deg,#fffdf6 8%,#eadfc8 37%,#f7c950 68%,#b67619 100%);
  -webkit-background-clip:text;background-clip:text;color:transparent;
  filter:drop-shadow(0 12px 28px rgba(0,0,0,.42));
}
.mega-title .word::after{
  content:'';position:absolute;left:4px;right:38%;top:52%;height:1px;
  background:linear-gradient(90deg,transparent,rgba(255,255,255,.6),transparent);
  mix-blend-mode:overlay;
}
.subword{display:flex;align-items:center;gap:14px;margin-top:12px;margin-left:7px}
.subword b{font-family:var(--display);font-size:clamp(30px,3.2vw,48px);font-weight:500;letter-spacing:.19em;color:rgba(255,255,255,.85)}
.subword i{font-family:var(--display);font-size:clamp(23px,2.3vw,34px);font-style:italic;color:var(--gold);font-weight:400}
.tagline{
  font-size:clamp(12px,1.05vw,14px);line-height:1.8;color:rgba(235,240,250,.6);
  margin:25px 0 30px;letter-spacing:.015em;
}
.cta-row{display:flex;align-items:stretch;gap:12px;flex-wrap:wrap}
.btn{
  position:relative;overflow:hidden;display:inline-flex;align-items:center;justify-content:center;gap:16px;
  border-radius:3px;text-transform:uppercase;text-decoration:none;transition:transform .2s ease,box-shadow .2s ease,background .2s ease;
  letter-spacing:.08em;isolation:isolate;
}
.btn:hover{transform:translateY(-2px)}
.btn:active{transform:translateY(0) scale(.99)}
.btn-gold{
  color:#171203;
  background:linear-gradient(120deg,#ffe19a 0%,#f7c950 38%,#e6a52d 78%,#f7ce64 100%);
  box-shadow:0 14px 34px rgba(218,155,36,.2),inset 0 1px 0 rgba(255,255,255,.72),inset 0 -2px 0 rgba(92,48,0,.2);
  border:1px solid rgba(255,230,165,.7);
}
.btn-gold::after{
  content:'';position:absolute;inset:0;z-index:-1;
  background:linear-gradient(100deg,transparent 20%,rgba(255,255,255,.75) 47%,transparent 56%);
  transform:translateX(-130%);transition:transform .7s cubic-bezier(.2,.7,.2,1);
}
.btn-gold:hover::after{transform:translateX(130%)}
.btn-gold:hover{box-shadow:0 18px 40px rgba(218,155,36,.28),inset 0 1px 0 rgba(255,255,255,.8)}
.btn-ghost{
  color:rgba(247,242,229,.86);background:rgba(255,255,255,.035);
  border:1px solid rgba(255,255,255,.18);backdrop-filter:blur(12px);
}
.btn-ghost:hover{background:rgba(255,255,255,.07);border-color:rgba(247,201,80,.45)}
.btn-quiet{color:rgba(255,255,255,.48);font-size:10px}
.btn-quiet:hover{color:var(--paper)}
.btn-xl{min-height:68px;padding:10px 22px 9px 24px;min-width:310px}
.btn-lg{min-height:58px;padding:10px 22px;min-width:218px}
.btn-label{display:flex;flex-direction:column;align-items:flex-start;gap:2px;font-family:var(--display);font-weight:700;font-size:20px;line-height:1;letter-spacing:.06em;text-align:left}
.btn-label small{font-family:var(--body);font-size:7px;font-weight:800;letter-spacing:.22em;opacity:.62;margin-bottom:2px}
.btn-gold .btn-label small{opacity:.55}
.btn svg{width:20px;height:20px;flex:0 0 auto;transition:transform .2s}
.btn:hover svg{transform:translateX(3px)}
.campaign-facts{display:flex;gap:clamp(18px,3vw,38px);margin-top:32px;padding-top:18px;border-top:1px solid rgba(255,255,255,.1);max-width:500px}
.campaign-facts>div{display:flex;flex-direction:column;gap:2px}
.campaign-facts b{font-family:var(--display);font-size:22px;font-weight:600;letter-spacing:.03em;line-height:1;color:rgba(255,255,255,.9)}
.campaign-facts span{font-size:7px;font-weight:800;letter-spacing:.22em;color:rgba(255,255,255,.34)}
.campaign-facts .pb-fact b{color:var(--gold)}
.campaign-facts .pb-fact{margin-left:auto;text-align:right}

/* programme card */
.programme-card{
  align-self:center;border-radius:4px;padding:0;overflow:hidden;
  transform:translateX(18px);opacity:0;
}
#menu.is-active .programme-card{animation:slideIn .8s .28s cubic-bezier(.2,.8,.2,1) forwards}
@keyframes slideIn{to{transform:translateX(0);opacity:1}}
.programme-head{
  display:flex;justify-content:space-between;align-items:center;padding:18px 20px 16px;
  border-bottom:1px solid var(--line-soft);font-size:8px;font-weight:800;letter-spacing:.22em;color:rgba(255,255,255,.52);
}
.programme-status{color:var(--green);display:flex;align-items:center;gap:6px}
.programme-status::before{content:'';width:5px;height:5px;border-radius:50%;background:var(--green);box-shadow:0 0 8px var(--green)}
.programme-row{
  width:100%;display:grid;grid-template-columns:30px 38px 1fr auto 14px;align-items:center;gap:10px;
  padding:17px 18px;border-bottom:1px solid var(--line-soft);text-align:left;transition:.25s ease;
  position:relative;overflow:hidden;
}
.programme-row::before{content:'';position:absolute;left:0;top:0;bottom:0;width:2px;background:var(--gold);transform:scaleY(0);transition:.25s;transform-origin:bottom}
.programme-row:hover{background:rgba(247,201,80,.06);padding-left:22px}
.programme-row:hover::before{transform:scaleY(1)}
.prog-num{font-family:var(--display);font-size:12px;font-weight:500;color:rgba(255,255,255,.3);letter-spacing:.05em}
.prog-icon{width:32px;height:32px;border:1px solid rgba(255,255,255,.12);border-radius:50%;display:grid;place-items:center;color:var(--gold)}
.prog-icon svg{width:21px;height:21px}
.prog-copy{display:flex;flex-direction:column;gap:3px;min-width:0}
.prog-copy b{font-family:var(--display);font-size:17px;letter-spacing:.055em;font-weight:600;white-space:nowrap}
.prog-copy small{font-size:8px;letter-spacing:.03em;color:rgba(255,255,255,.34);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.prog-best{font-size:8px;font-weight:700;letter-spacing:.09em;color:rgba(255,255,255,.32);white-space:nowrap}
.prog-arrow{font-size:12px;color:rgba(255,255,255,.25);transition:.2s}
.programme-row:hover .prog-arrow{color:var(--gold);transform:translate(1px,-1px)}
.programme-foot{display:flex;justify-content:space-between;padding:13px 19px;font-size:7px;letter-spacing:.18em;font-weight:800;color:rgba(255,255,255,.28);background:rgba(0,0,0,.16)}

/* footer */
.menu-footer{
  position:absolute;left:0;right:0;bottom:0;height:46px;padding:0 clamp(22px,3.6vw,58px) var(--safe-bottom);
  display:flex;align-items:center;justify-content:space-between;gap:20px;
  border-top:1px solid rgba(255,255,255,.08);background:rgba(2,6,14,.32);backdrop-filter:blur(10px);
}
.ticker{display:flex;align-items:center;gap:14px;overflow:hidden;min-width:0;flex:1}
.ticker-label{color:var(--red);font-size:7px;font-weight:800;letter-spacing:.2em;display:flex;align-items:center;gap:6px;flex:0 0 auto}
.ticker-label::before{content:'';width:5px;height:5px;background:var(--red);border-radius:50%;box-shadow:0 0 8px var(--red)}
.ticker-track{display:flex;gap:38px;white-space:nowrap;animation:ticker 24s linear infinite;opacity:.38;font-size:7px;letter-spacing:.24em;font-weight:700}
.ticker-track span::before{content:'◆';color:var(--gold);font-size:4px;margin-right:38px;vertical-align:2px}
@keyframes ticker{to{transform:translateX(-50%)}}
.footer-meta{display:flex;gap:22px;font-size:7px;letter-spacing:.2em;font-weight:700;color:rgba(255,255,255,.26);flex:0 0 auto}

/* ---------- generic modal ---------- */
.modal-screen{z-index:30;background:rgba(2,5,12,.28)}
.backdrop{position:absolute;inset:0;background:rgba(2,5,12,.7);backdrop-filter:blur(14px);-webkit-backdrop-filter:blur(14px);pointer-events:auto}
.modal-panel{
  position:absolute;left:50%;top:50%;transform:translate(-50%,-50%) translateY(18px);
  width:min(1000px,calc(100vw - 40px));border-radius:5px;padding:42px;
  opacity:0;transition:.42s cubic-bezier(.2,.8,.2,1);
}
.screen.is-active .modal-panel{opacity:1;transform:translate(-50%,-50%) translateY(0)}
.close-btn{
  position:absolute;right:18px;top:18px;width:36px;height:36px;border-radius:50%;
  border:1px solid rgba(255,255,255,.14);font-size:22px;line-height:1;color:rgba(255,255,255,.55);
  display:grid;place-items:center;transition:.2s;z-index:2;
}
.close-btn:hover{background:rgba(255,255,255,.08);color:#fff;transform:rotate(90deg)}

/* practice */
.practice-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:12px;margin-top:32px}
.practice-card{
  position:relative;text-align:left;padding:24px 22px 20px;border:1px solid rgba(255,255,255,.12);
  border-radius:3px;background:
    linear-gradient(160deg,rgba(255,255,255,.06),rgba(255,255,255,.015)),
    radial-gradient(circle at 80% 0%,rgba(247,201,80,.1),transparent 50%);
  min-height:236px;display:flex;flex-direction:column;align-items:flex-start;transition:.25s;overflow:hidden;
}
.practice-card::after{content:'';position:absolute;inset:auto -20% -52% 20%;height:120%;background:radial-gradient(closest-side,rgba(247,201,80,.14),transparent);opacity:0;transition:.35s}
.practice-card:hover{transform:translateY(-4px);border-color:rgba(247,201,80,.42);background:linear-gradient(160deg,rgba(247,201,80,.09),rgba(255,255,255,.02))}
.practice-card:hover::after{opacity:1}
.practice-index{font-size:8px;font-weight:800;letter-spacing:.17em;color:rgba(255,255,255,.3);border:1px solid rgba(255,255,255,.12);padding:4px 7px;border-radius:2px}
.practice-glyph{font-family:var(--display);font-size:46px;color:var(--gold);line-height:1;margin:22px 0 10px;font-weight:300;transform:skewX(-6deg)}
.practice-card b{font-family:var(--display);font-size:25px;letter-spacing:.05em;font-weight:600;margin-bottom:5px}
.practice-card small{font-size:10px;line-height:1.5;color:rgba(255,255,255,.42);max-width:180px}
.practice-go{margin-top:auto;padding-top:18px;font-size:8px;font-weight:800;letter-spacing:.17em;color:rgba(255,255,255,.55);display:flex;gap:6px;align-items:center}
.practice-go i{font-style:normal;color:var(--gold);font-size:12px}
.practice-card:hover .practice-go{color:var(--gold)}

/* guide */
.guide-panel{width:min(960px,calc(100vw - 40px))}
.guide-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:28px;margin-top:32px;border-top:1px solid var(--line-soft);padding-top:28px}
.guide-grid article{position:relative}
.guide-num{font-family:var(--display);font-size:11px;color:var(--gold);letter-spacing:.15em;font-weight:600}
.guide-grid h3{font-family:var(--display);font-size:22px;letter-spacing:.06em;font-weight:600;margin:9px 0 9px}
.guide-grid p{font-size:11px;line-height:1.7;color:rgba(255,255,255,.53)}
.guide-grid p kbd{background:rgba(247,201,80,.09);border-color:rgba(247,201,80,.24);color:var(--gold);height:19px;min-width:19px;font-size:8px}
.guide-foot{display:flex;gap:26px;flex-wrap:wrap;margin-top:32px;border-top:1px solid var(--line-soft);padding-top:17px;font-size:8px;font-weight:700;letter-spacing:.13em;color:rgba(255,255,255,.3)}

/* pause */
.pause-panel{width:min(440px,calc(100vw - 40px));text-align:left}
.pause-actions{display:flex;flex-direction:column;gap:9px;margin-top:28px}
.pause-actions .btn{width:100%;min-height:52px}
.pause-hints{display:flex;justify-content:space-between;margin-top:22px;font-size:8px;letter-spacing:.12em;color:rgba(255,255,255,.3)}

/* ---------- event intro ---------- */
.intro-screen{z-index:20;background:linear-gradient(90deg,rgba(2,5,12,.92) 0%,rgba(2,6,15,.75) 43%,rgba(3,8,18,.18) 72%,rgba(2,5,12,.55) 100%)}
.intro-screen::before{
  content:'';position:absolute;inset:0;
  background:linear-gradient(to bottom,rgba(2,5,12,.45),transparent 25%,transparent 65%,rgba(2,5,12,.82));
}
.intro-wash{position:absolute;inset:0;background:linear-gradient(105deg,transparent 40%,rgba(247,201,80,.04) 48%,transparent 56%);transform:translateX(-100%);animation:introWash 1.1s .2s ease forwards}
@keyframes introWash{to{transform:translateX(100%)}}
.intro-inner{position:absolute;inset:0;display:flex;align-items:center;gap:clamp(20px,4vw,80px);padding:0 clamp(24px,6vw,104px);transform:translateY(10px);opacity:0}
#eventIntro.is-active .intro-inner{animation:riseIn .7s .05s ease forwards}
.intro-number{
  font-family:var(--display);font-size:clamp(160px,24vw,340px);line-height:.7;font-weight:900;
  color:transparent;-webkit-text-stroke:1px rgba(255,255,255,.18);letter-spacing:-.06em;
  transform:translateX(-20px);
}
.intro-copy{max-width:630px;position:relative;z-index:2}
.intro-copy h2{font-family:var(--display);font-size:clamp(72px,10vw,152px);line-height:.76;font-weight:800;letter-spacing:-.025em;text-transform:uppercase;margin:22px 0 22px}
.intro-copy h2 em{font-style:italic;font-weight:600;color:var(--gold);display:inline-block}
.intro-copy p{font-size:12px;line-height:1.85;color:rgba(255,255,255,.57);max-width:480px}
.intro-controls{display:flex;gap:20px;margin:24px 0 28px;flex-wrap:wrap}
.intro-control{display:flex;align-items:center;gap:9px;font-size:8px;font-weight:800;letter-spacing:.12em;color:rgba(255,255,255,.4)}
.intro-control span{display:flex;gap:3px}
.intro-ready{min-height:58px}
.intro-side{position:absolute;right:clamp(24px,5vw,80px);bottom:18vh;display:flex;flex-direction:column;gap:1px;width:220px;background:rgba(2,6,14,.28);backdrop-filter:blur(10px);border-top:1px solid rgba(255,255,255,.1)}
.intro-stat{padding:15px 18px;border-bottom:1px solid rgba(255,255,255,.07);display:grid;grid-template-columns:1fr auto;gap:2px 10px}
.intro-stat small{grid-column:1/-1;font-size:6px;font-weight:800;letter-spacing:.18em;color:rgba(255,255,255,.28);margin-bottom:4px}
.intro-stat b{font-family:var(--display);font-size:19px;font-weight:600;letter-spacing:.035em}
.intro-stat span{font-size:7px;font-weight:700;letter-spacing:.14em;color:var(--gold);align-self:end;padding-bottom:3px}

/* ---------- HUD ---------- */
.hud{z-index:12}
.hud.is-active{pointer-events:none}
.hud.is-active button{pointer-events:auto}
.hud-top{
  position:absolute;top:0;left:0;right:0;height:104px;padding:calc(18px + var(--safe-top)) clamp(16px,2.6vw,40px);
  display:flex;align-items:flex-start;justify-content:space-between;gap:20px;
  background:linear-gradient(to bottom,rgba(2,5,12,.58),transparent);
}
.hud-event{display:flex;align-items:flex-start;gap:12px;min-width:190px}
.hud-event-num{font-family:var(--display);font-size:11px;color:var(--gold);border:1px solid rgba(247,201,80,.35);padding:4px 6px 3px;border-radius:2px;font-weight:600}
.hud-event>span:last-child{display:flex;flex-direction:column;gap:2px}
.hud-event b{font-family:var(--display);font-size:20px;font-weight:600;letter-spacing:.07em;line-height:1}
.hud-event small{font-size:6px;font-weight:800;letter-spacing:.2em;color:rgba(255,255,255,.38);margin-top:3px}
.hud-clock-wrap{text-align:center;min-width:150px}
.hud-clock-label{font-size:7px;font-weight:800;letter-spacing:.22em;color:rgba(255,255,255,.38)}
.hud-clock{font-family:var(--display);font-size:clamp(38px,4vw,54px);font-weight:500;letter-spacing:.015em;line-height:1;font-variant-numeric:tabular-nums;margin-top:5px;text-shadow:0 2px 20px rgba(0,0,0,.5)}
.hud-clock span{font-size:.42em;color:rgba(255,255,255,.42);margin-left:4px;font-weight:400;letter-spacing:.08em}
.hud-place-wrap{display:flex;align-items:flex-start;gap:15px;min-width:150px;justify-content:flex-end}
.hud-icon-btn{width:34px;height:34px;border-radius:50%;border:1px solid rgba(255,255,255,.14);display:grid;place-items:center;background:rgba(4,9,19,.32);transition:.2s}
.hud-icon-btn:hover{background:rgba(255,255,255,.08)}
.hud-icon-btn svg{width:14px;height:14px}
.hud-place{text-align:right;display:flex;flex-direction:column;gap:1px}
.hud-place small{font-size:6px;font-weight:800;letter-spacing:.2em;color:rgba(255,255,255,.35)}
.hud-place b{font-family:var(--display);font-size:30px;font-weight:600;line-height:1;color:var(--gold)}

.mini-board{
  position:absolute;left:clamp(16px,2.6vw,40px);top:122px;width:222px;border-radius:3px;
  padding:0;overflow:hidden;transition:.35s;opacity:0;transform:translateX(-10px);
}
.mini-board.is-on{opacity:1;transform:none}
.mini-board-head{display:flex;justify-content:space-between;padding:10px 12px 8px;font-size:6px;font-weight:800;letter-spacing:.16em;color:rgba(255,255,255,.34);border-bottom:1px solid rgba(255,255,255,.07)}
.mini-board-head span:last-child{color:var(--gold);opacity:.85}
.mini-row{display:grid;grid-template-columns:16px 1fr auto;gap:7px;align-items:center;padding:5px 11px;font-size:8px;border-bottom:1px solid rgba(255,255,255,.035)}
.mini-row:last-child{border-bottom:0}
.mini-row .pos{font-family:var(--display);font-weight:500;color:rgba(255,255,255,.32);font-size:9px}
.mini-row .who{display:flex;align-items:center;gap:5px;min-width:0}
.mini-row .flag{font-size:6px;font-weight:800;letter-spacing:.06em;color:rgba(255,255,255,.3);border:1px solid rgba(255,255,255,.1);padding:1px 3px;border-radius:1px}
.mini-row .name{font-family:var(--display);font-size:10px;letter-spacing:.035em;font-weight:500;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.mini-row .score{font-family:var(--display);font-size:10px;font-variant-numeric:tabular-nums;color:rgba(255,255,255,.48)}
.mini-row.is-player{background:rgba(247,201,80,.11);box-shadow:inset 2px 0 0 var(--gold)}
.mini-row.is-player .name,.mini-row.is-player .score{color:var(--gold)}
.mini-row.is-player .pos{color:var(--gold)}
.mini-row.is-leader .pos{color:#fff}

.hud-prompt{
  position:absolute;left:50%;bottom:calc(28px + var(--safe-bottom));transform:translateX(-50%) translateY(8px);
  display:flex;align-items:center;gap:12px;padding:9px 16px 9px 10px;border-radius:3px;
  background:rgba(5,11,22,.72);border:1px solid rgba(255,255,255,.13);backdrop-filter:blur(14px);
  opacity:0;transition:.3s;white-space:nowrap;
}
.hud-prompt.is-on{opacity:1;transform:translateX(-50%)}
.prompt-key{
  width:34px;height:34px;border-radius:2px;background:var(--gold);color:#151003;display:grid;place-items:center;
  font-family:var(--display);font-weight:800;font-size:17px;box-shadow:0 0 24px rgba(247,201,80,.25);
}
.prompt-copy{display:flex;flex-direction:column;gap:2px}
.prompt-copy b{font-size:9px;letter-spacing:.12em;font-weight:800}
.prompt-copy small{font-size:7px;letter-spacing:.04em;color:rgba(255,255,255,.4)}
.hud-prompt.pulse .prompt-key{animation:keyPulse .6s ease infinite alternate}
@keyframes keyPulse{to{box-shadow:0 0 40px rgba(247,201,80,.65);transform:scale(1.06)}}

.hud-bottom{
  position:absolute;left:0;right:0;bottom:calc(24px + var(--safe-bottom));padding:0 clamp(16px,2.6vw,40px);
  display:flex;align-items:flex-end;justify-content:space-between;gap:24px;
}
.meter-cluster{width:clamp(190px,22vw,290px);transition:.3s}
.meter-head{display:flex;align-items:flex-end;gap:5px;margin-bottom:7px}
.meter-head span{font-size:6px;font-weight:800;letter-spacing:.18em;color:rgba(255,255,255,.36);margin-right:auto}
.meter-head b{font-family:var(--display);font-size:27px;font-weight:500;line-height:.6;font-variant-numeric:tabular-nums}
.meter-head small{font-size:6px;font-weight:700;letter-spacing:.1em;color:rgba(255,255,255,.3);padding-bottom:1px}
.meter-track{position:relative;height:7px;background:rgba(255,255,255,.09);border-radius:1px;overflow:hidden}
.meter-fill{position:absolute;left:0;top:0;bottom:0;width:0%;background:linear-gradient(90deg,#7ce2ff,var(--gold) 68%,#ff7a4f);box-shadow:0 0 16px rgba(247,201,80,.45);transition:width .12s linear}
.meter-ticks{position:absolute;inset:0;background:repeating-linear-gradient(90deg,transparent 0 9.7%,rgba(2,6,14,.55) 9.7% 10%)}
.meter-foot{display:flex;justify-content:space-between;margin-top:5px;font-size:5px;font-weight:800;letter-spacing:.16em;color:rgba(255,255,255,.22)}
.meter-cluster.is-hidden{opacity:0;transform:translateY(10px);pointer-events:none}

.touch-controls{display:none;align-items:center;gap:16px;margin:0 auto;transition:.3s}
.tap-btn{
  width:74px;height:74px;border-radius:50%;border:1px solid rgba(247,201,80,.4);
  background:radial-gradient(circle at 40% 32%,rgba(247,201,80,.18),rgba(5,11,22,.72));
  box-shadow:inset 0 1px 0 rgba(255,255,255,.15),0 8px 30px rgba(0,0,0,.3);
  display:flex;flex-direction:column;align-items:center;justify-content:center;gap:1px;
  transition:transform .08s,background .15s,box-shadow .15s;touch-action:none;
}
.tap-btn span{font-family:var(--display);font-size:27px;font-weight:600;line-height:1;color:#fff}
.tap-btn small{font-size:5px;font-weight:800;letter-spacing:.16em;color:rgba(255,255,255,.33)}
.tap-btn.is-next{border-color:var(--gold);box-shadow:0 0 32px rgba(247,201,80,.27),inset 0 1px 0 rgba(255,255,255,.2);animation:tapGlow 1s infinite alternate}
@keyframes tapGlow{to{box-shadow:0 0 50px rgba(247,201,80,.52),inset 0 1px 0 rgba(255,255,255,.25)}}
.tap-btn.is-hit{transform:scale(.9);background:radial-gradient(circle at 40% 32%,rgba(255,236,178,.65),rgba(247,201,80,.16))}
.cadence-orbit{display:flex;flex-direction:column;gap:5px;align-items:center;width:14px}
.cadence-orbit i{width:4px;height:4px;border-radius:50%;background:rgba(255,255,255,.16);transition:.2s}
.cadence-orbit i.on{background:var(--gold);box-shadow:0 0 8px var(--gold)}
.cadence-orbit i:nth-child(2){width:6px;height:6px}
.action-controls{display:none;align-items:center;justify-content:center;margin:0 auto}
.action-btn{
  position:relative;width:96px;height:96px;border-radius:50%;border:1px solid rgba(247,201,80,.7);
  background:radial-gradient(circle at 42% 34%,rgba(255,230,163,.58),rgba(224,158,32,.28) 46%,rgba(20,15,4,.82) 100%);
  box-shadow:0 0 0 7px rgba(247,201,80,.07),0 0 40px rgba(247,201,80,.18),inset 0 2px 0 rgba(255,255,255,.36);
  display:flex;flex-direction:column;align-items:center;justify-content:center;gap:2px;
  transition:transform .08s,box-shadow .15s;touch-action:none;
}
.action-btn::before{content:'';position:absolute;inset:9px;border:1px solid rgba(255,255,255,.11);border-radius:50%}
.action-btn span{font-family:var(--display);font-size:25px;font-weight:700;letter-spacing:.05em;color:#fff;line-height:1;text-shadow:0 2px 12px rgba(0,0,0,.4)}
.action-btn small{font-size:5px;font-weight:800;letter-spacing:.14em;color:rgba(255,255,255,.52)}
.action-btn:active{transform:scale(.93)}
.action-btn.is-hot{animation:actionHot .55s infinite alternate}
@keyframes actionHot{to{box-shadow:0 0 0 7px rgba(247,201,80,.14),0 0 60px rgba(247,201,80,.55),inset 0 2px 0 rgba(255,255,255,.36)}}

.javelin-cluster{display:none;position:relative;width:190px;height:150px;margin:0 auto}
.javelin-cluster.is-on{display:block}
.angle-dial{position:absolute;left:50%;bottom:-4px;transform:translateX(-50%);width:180px;height:150px}
.angle-dial svg{width:100%;height:100%;overflow:visible}
.dial-track{fill:none;stroke:rgba(255,255,255,.17);stroke-width:3;stroke-linecap:round}
.dial-green{fill:none;stroke:rgba(247,201,80,.18);stroke-width:11;stroke-linecap:round}
.dial-knob{fill:var(--gold);stroke:#fff;stroke-width:1.4;filter:drop-shadow(0 0 7px rgba(247,201,80,.9))}
.angle-read{position:absolute;left:50%;bottom:16px;transform:translateX(-50%);text-align:center}
.angle-read b{display:block;font-family:var(--display);font-size:28px;line-height:1;font-weight:500}
.angle-read small{font-size:5px;font-weight:800;letter-spacing:.15em;color:rgba(255,255,255,.33)}

.key-hints{
  position:absolute;bottom:calc(26px + var(--safe-bottom));left:50%;transform:translateX(-50%);
  display:flex;gap:20px;font-size:7px;letter-spacing:.1em;font-weight:700;color:rgba(255,255,255,.3);
  white-space:nowrap;
}
.key-hints span{display:flex;align-items:center;gap:4px}
.key-hints.is-hidden{display:none}

/* ---------- countdown ---------- */
.countdown{z-index:18;display:grid;place-items:center;background:radial-gradient(ellipse at center,rgba(2,6,14,.18),rgba(2,6,14,.5))}
.countdown-stage{text-align:center;transform:scale(.96);opacity:0;transition:.3s}
.countdown-stage.is-on{opacity:1;transform:scale(1)}
.countdown-word{
  font-family:var(--display);font-size:clamp(62px,10vw,148px);font-weight:800;letter-spacing:.05em;line-height:.9;
  text-transform:uppercase;text-shadow:0 8px 46px rgba(0,0,0,.65);
}
.countdown-word.go{color:var(--gold);font-size:clamp(100px,16vw,240px);text-shadow:0 0 80px rgba(247,201,80,.38)}
.countdown-word.set{color:#fff}
.countdown-word.false{color:var(--red);text-shadow:0 0 50px rgba(255,80,64,.35)}
.countdown-sub{margin-top:12px;font-size:8px;font-weight:800;letter-spacing:.32em;color:rgba(255,255,255,.45)}
.countdown-lights{display:flex;gap:10px;justify-content:center;margin-bottom:22px}
.countdown-lights i{width:10px;height:10px;border-radius:50%;background:rgba(255,255,255,.12);border:1px solid rgba(255,255,255,.16);transition:.25s}
.countdown-lights i.on{background:var(--red);border-color:var(--red);box-shadow:0 0 18px var(--red)}
.countdown.is-hot{animation:shake .4s .02s}
@keyframes shake{0%,100%{transform:translate(0,0)}20%{transform:translate(-5px,2px)}40%{transform:translate(4px,-3px)}60%{transform:translate(-3px,-2px)}80%{transform:translate(2px,2px)}}

/* ---------- results ---------- */
.results-screen{z-index:22;background:linear-gradient(90deg,rgba(2,5,12,.92),rgba(3,8,18,.7) 50%,rgba(2,5,12,.55))}
.results-backdrop{position:absolute;inset:0;background:linear-gradient(to bottom,rgba(2,5,12,.28),transparent 28%,transparent 60%,rgba(2,5,12,.82))}
.results-panel{
  position:absolute;left:50%;top:50%;transform:translate(-50%,-50%) translateY(20px.);
  width:min(1120px,calc(100vw - 64px));max-height:calc(100dvh - 70px);overflow:auto;
  padding:clamp(26px,3.4vw,48px);border-radius:4px;
  background:linear-gradient(145deg,rgba(13,22,40,.89),rgba(4,9,19,.88));
  border:1px solid rgba(255,255,255,.14);backdrop-filter:blur(28px) saturate(1.2);
  box-shadow:0 40px 120px rgba(0,0,0,.54),inset 0 1px 0 rgba(255,255,255,.08);
  opacity:0;transform:translate(-50%,-47%);transition:.48s cubic-bezier(.16,.9,.3,1);
}
.results-screen.is-active .results-panel{opacity:1;transform:translate(-50%,-50%)}
.results-top{display:flex;justify-content:space-between;gap:30px;align-items:flex-end;border-bottom:1px solid var(--line-soft);padding-bottom:27px}
.results-event h2{font-family:var(--display);font-size:clamp(40px,5vw,66px);line-height:.88;letter-spacing:-.01em;font-weight:700;margin:9px 0 0;text-transform:uppercase}
.results-mark{display:flex;align-items:baseline;gap:8px;margin-top:4px}
.results-mark span{font-family:var(--display);font-size:clamp(50px,6vw,78px);font-weight:500;line-height:1;color:var(--gold);font-variant-numeric:tabular-nums;text-shadow:0 0 50px rgba(247,201,80,.16)}
.results-mark small{font-size:7px;font-weight:800;letter-spacing:.2em;color:rgba(255,255,255,.36)}
.results-verdict{display:flex;align-items:center;gap:13px;padding:12px 18px 12px 13px;border:1px solid rgba(247,201,80,.23);background:rgba(247,201,80,.055);border-radius:3px;min-width:205px}
.verdict-medal{
  width:39px;height:39px;border-radius:50%;display:grid;place-items:center;font-family:var(--display);
  font-size:24px;font-weight:600;color:#241703;background:linear-gradient(145deg,#ffe8a8,#ddb03a 65%,#a26b12);
  box-shadow:0 4px 18px rgba(218,155,36,.28),inset 0 1px 0 rgba(255,255,255,.6);
}
.verdict-medal.silver{background:linear-gradient(145deg,#f1f4f7,#b8c0ca 65%,#7e8897)}
.verdict-medal.bronze{background:linear-gradient(145deg,#e7b28b,#b76c3d 65%,#7c3e1d);color:#251006}
.verdict-medal.plain{background:rgba(255,255,255,.1);color:rgba(255,255,255,.55);box-shadow:none;border:1px solid rgba(255,255,255,.12)}
.results-verdict>div:last-child{display:flex;flex-direction:column;gap:2px}
.results-verdict small{font-size:6px;font-weight:800;letter-spacing:.17em;color:rgba(255,255,255,.35)}
.results-verdict b{font-family:var(--display);font-size:18px;font-weight:600;letter-spacing:.04em}
.results-verdict span{font-size:7px;font-weight:800;letter-spacing:.1em;color:var(--gold)}
.results-grid{display:grid;grid-template-columns:1.55fr .8fr;gap:38px;padding:27px 0 30px}
.result-board-head,.result-row{display:grid;grid-template-columns:26px 1fr auto 52px;gap:10px;align-items:center}
.result-board-head{padding:0 9px 9px;font-size:6px;font-weight:800;letter-spacing:.16em;color:rgba(255,255,255,.28);border-bottom:1px solid rgba(255,255,255,.08)}
.result-board-head span:last-child{text-align:right}
.result-row{padding:7px 9px;border-bottom:1px solid rgba(255,255,255,.045);font-size:9px}
.result-row:last-child{border-bottom:0}
.result-row .pos{font-family:var(--display);font-size:12px;color:rgba(255,255,255,.36);font-weight:500}
.result-row .athlete{display:flex;align-items:center;gap:7px;min-width:0}
.result-row .code{font-size:6px;font-weight:800;letter-spacing:.06em;color:rgba(255,255,255,.3);border:1px solid rgba(255,255,255,.1);padding:1px 3px;border-radius:1px;flex:0 0 auto}
.result-row .name{font-size:9px;font-weight:600;letter-spacing:.03em;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.result-row .mark{font-family:var(--display);font-size:13px;font-variant-numeric:tabular-nums;color:rgba(255,255,255,.67);text-align:right}
.result-row .pts{font-family:var(--display);font-size:11px;text-align:right;color:rgba(255,255,255,.38)}
.result-row.is-player{background:rgba(247,201,80,.09);box-shadow:inset 2px 0 0 var(--gold)}
.result-row.is-player .name,.result-row.is-player .mark{color:var(--gold)}
.result-row.is-player .pts{color:var(--gold)}
.result-row.is-player .pos{color:var(--gold)}
.result-side{border-left:1px solid var(--line-soft);padding-left:28px;display:flex;flex-direction:column;gap:20px}
.result-note{font-size:11px;line-height:1.75;color:rgba(255,255,255,.5)}
.result-note b{color:var(--paper)}
.series-mini{display:flex;flex-direction:column;gap:7px;margin-top:auto}
.series-mini-head{font-size:6px;font-weight:800;letter-spacing:.18em;color:rgba(255,255,255,.26);margin-bottom:2px}
.series-mini-row{display:flex;align-items:center;gap:8px;font-size:8px;color:rgba(255,255,255,.42)}
.series-mini-row i{width:5px;height:5px;border-radius:50%;border:1px solid rgba(255,255,255,.22);flex:0 0 auto}
.series-mini-row.done i{background:var(--gold);border-color:var(--gold);box-shadow:0 0 7px rgba(247,201,80,.5)}
.series-mini-row.current{color:var(--gold)}
.series-mini-row b{margin-left:auto;font-family:var(--display);font-size:10px;font-weight:500;color:rgba(255,255,255,.5)}
.results-actions{display:flex;justify-content:space-between;align-items:center;gap:14px;border-top:1px solid var(--line-soft);padding-top:23px}
.results-actions .btn{min-height:51px}
.results-actions .btn-gold{min-width:240px}

/* ---------- ceremony ---------- */
.ceremony-screen{z-index:24;background:linear-gradient(90deg,rgba(2,5,12,.92),rgba(3,8,18,.55) 48%,rgba(2,5,12,.28))}
.ceremony-overlay{position:absolute;inset:0;background:linear-gradient(to bottom,rgba(2,5,12,.4),transparent 30%,transparent 68%,rgba(2,5,12,.75))}
.ceremony-top{position:absolute;left:clamp(24px,6vw,92px);top:15vh;max-width:600px;opacity:0;transform:translateY(18px)}
.ceremony-screen.is-active .ceremony-top{animation:riseIn .8s .1s ease forwards}
.ceremony-title{font-family:var(--display);font-size:clamp(88px,11vw,156px);line-height:.72;letter-spacing:-.025em;font-weight:800;text-transform:uppercase;margin:17px 0 18px;text-shadow:0 10px 50px rgba(0,0,0,.5)}
.ceremony-title em{font-style:italic;font-weight:600;color:var(--gold);position:relative}
.ceremony-screen p{font-size:12px;color:rgba(255,255,255,.52);letter-spacing:.02em}
.final-board{
  position:absolute;right:clamp(20px,4vw,60px);top:16vh;width:min(390px,40vw);border-radius:3px;
  padding:0;opacity:0;transform:translateX(18px);
}
.ceremony-screen.is-active .final-board{animation:slideIn .7s .25s ease forwards}
.final-board-head{display:flex;justify-content:space-between;padding:14px 17px 12px;font-size:7px;font-weight:800;letter-spacing:.18em;color:rgba(255,255,255,.4);border-bottom:1px solid var(--line-soft)}
.final-row{display:grid;grid-template-columns:28px 1fr auto 38px;gap:7px;padding:7px 13px;align-items:center;border-bottom:1px solid rgba(255,255,255,.04);font-size:8px}
.final-row:last-child{border-bottom:0}
.final-row .place{font-family:var(--display);font-size:13px;color:rgba(255,255,255,.37)}
.final-row .who{display:flex;align-items:center;gap:6px;min-width:0}
.final-row .who .code{font-size:5px;font-weight:800;color:rgba(255,255,255,.28);border:1px solid rgba(255,255,255,.1);padding:1px 2px}
.final-row .who .name{font-weight:600;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.final-row .total{font-family:var(--display);font-size:12px;color:rgba(255,255,255,.55);text-align:right}
.final-row .medal-mini{font-size:11px;text-align:right}
.final-row.is-player{background:rgba(247,201,80,.09);box-shadow:inset 2px 0 0 var(--gold)}
.final-row.is-player .name,.final-row.is-player .total{color:var(--gold)}
.ceremony-actions{position:absolute;left:clamp(24px,6vw,92px);bottom:10vh;display:flex;gap:10px;opacity:0}
.ceremony-screen.is-active .ceremony-actions{animation:riseIn .7s .55s ease forwards}
.ceremony-actions .btn{min-height:54px}

/* ---------- flash / toast / transition ---------- */
.flash{position:fixed;inset:0;z-index:80;background:#fff9df;opacity:0;pointer-events:none;mix-blend-mode:screen}
.flash.fire{animation:flashFire .32s ease-out}
@keyframes flashFire{0%{opacity:.82}28%{opacity:.26}100%{opacity:0}}
.toast{
  position:fixed;left:50%;top:16%;transform:translate(-50%,-8px);z-index:70;padding:9px 16px;border-radius:2px;
  background:rgba(5,11,22,.85);border:1px solid rgba(255,255,255,.13);backdrop-filter:blur(14px);
  font-size:8px;font-weight:800;letter-spacing:.17em;text-transform:uppercase;color:var(--paper);
  opacity:0;pointer-events:none;transition:.25s;white-space:nowrap;
}
.toast.is-on{opacity:1;transform:translate(-50%,0)}
.toast.gold{color:var(--gold);border-color:rgba(247,201,80,.3)}
.toast.red{color:var(--red);border-color:rgba(255,99,88,.35)}
.transition{position:fixed;inset:0;z-index:75;pointer-events:none;visibility:hidden;overflow:hidden}
.transition.is-on{visibility:visible}
.transition::before,.transition::after{content:'';position:absolute;inset:0;background:#f6c850;transform:translateX(-101%);transition:transform .6s cubic-bezier(.77,0,.18,1)}
.transition::after{background:#060b16;transition-delay:.07s}
.transition.is-on::before,.transition.is-on::after{transform:translateX(0)}
.transition.is-out::before,.transition.is-out::after{transform:translateX(101%)}
.transition-mark{position:absolute;left:50%;top:50%;transform:translate(-50%,-50%);font-family:var(--display);font-size:30px;letter-spacing:.3em;font-weight:800;color:var(--gold);z-index:2;opacity:0;transition:.2s}
.transition.is-on .transition-mark{opacity:1;transition-delay:.42s}

/* ============================================================
   RESPONSIVE
   ============================================================ */
@media (max-width:1100px){
  .menu-content{grid-template-columns:minmax(0,1fr) 330px;gap:30px}
  .prog-copy small{display:none}
  .programme-row{padding:14px 15px}
  .intro-side{display:none}
}

@media (max-width:820px),(orientation:portrait){
  .topbar{height:68px;padding-top:calc(16px + var(--safe-top))}
  .topbar-center{display:none}
  .brand-copy b{font-size:21px}
  .brand-copy small{font-size:6px}
  .rings{width:42px}
  .icon-btn{width:36px;height:36px}
  .menu-content{
    display:flex;flex-direction:column;justify-content:center;align-items:stretch;
    padding:84px 22px 66px;gap:24px;overflow-y:auto;
  }
  .hero-copy{max-width:none;padding-top:0}
  .mega-title .word{font-size:clamp(92px,25vw,160px)}
  .subword{gap:10px;margin-top:9px}
  .subword b{font-size:clamp(24px,7vw,38px)}
  .subword i{font-size:clamp(18px,5vw,27px)}
  .tagline{font-size:11px;margin:18px 0 22px}
  .cta-row{flex-direction:column;gap:9px}
  .btn-xl,.btn-lg{width:100%;min-width:0;min-height:56px}
  .campaign-facts{display:none}
  .programme-card{width:100%;align-self:stretch;margin-top:6px;background:rgba(5,11,22,.66)}
  .programme-head{padding:12px 14px 10px;font-size:7px}
  .programme-row{grid-template-columns:22px 28px 1fr 12px;padding:10px 12px;gap:8px}
  .programme-row:hover{padding-left:12px}
  .prog-icon{width:26px;height:26px}
  .prog-icon svg{width:17px;height:17px}
  .prog-copy b{font-size:14px}
  .prog-copy small,.prog-best{display:none}
  .programme-foot{display:none}
  .menu-footer{height:38px;padding-left:22px;padding-right:22px}
  .footer-meta{display:none}
  .ticker-track{font-size:6px;gap:24px}
  .ticker-track span::before{margin-right:24px}
  .intro-inner{padding:0 22px;gap:0}
  .intro-number{position:absolute;right:16px;top:11vh;opacity:.5;font-size:38vw;z-index:0}
  .intro-copy{max-width:100%}
  .intro-copy h2{font-size:clamp(64px,17vw,112px);margin:18px 0}
  .intro-copy p{font-size:11px;max-width:94%}
  .intro-controls{gap:12px;margin:20px 0 24px}
  .intro-ready{width:100%}
  .intro-side{display:none}
  .hud-top{height:78px;padding-top:calc(12px + var(--safe-top));align-items:flex-start}
  .hud-event{min-width:0;gap:8px}
  .hud-event b{font-size:16px}
  .hud-event small{font-size:5px;letter-spacing:.14em}
  .hud-clock-wrap{min-width:100px;position:absolute;left:50%;transform:translateX(-50%)}
  .hud-clock{font-size:32px}
  .hud-clock-label{font-size:5px}
  .hud-place-wrap{min-width:auto;gap:9px}
  .hud-place b{font-size:23px}
  .hud-place small{font-size:5px}
  .mini-board{display:none}
  .hud-bottom{bottom:calc(15px + var(--safe-bottom));padding:0 18px;gap:10px}
  .meter-cluster{position:absolute;left:18px;bottom:0;width:calc(100% - 36px);opacity:.9}
  .meter-head b{font-size:22px}
  .meter-head{margin-bottom:5px}
  .hud-prompt{bottom:calc(158px + var(--safe-bottom));padding:7px 12px 7px 8px;gap:9px;max-width:calc(100vw - 32px)}
  .prompt-key{width:28px;height:28px;font-size:14px}
  .prompt-copy b{font-size:8px}
  .prompt-copy small{font-size:6px}
  .touch-controls{display:flex;position:relative;left:50%;transform:translateX(-50%);padding-bottom:68px;gap:18px}
  .action-controls{display:flex;padding-bottom:36px}
  .javelin-cluster{display:none;margin-bottom:25px}
  .javelin-cluster.is-on{display:block}
  .javelin-cluster:not(.is-on){display:none}
  .key-hints{display:none}
  .screen.is-active .touch-controls,.screen.is-active .action-controls{pointer-events:auto}
  .results-screen{overflow-y:auto}
  .results-panel{position:absolute;top:50%;left:50%;width:calc(100vw - 24px);max-height:calc(100dvh - 32px);padding:22px 18px}
  .results-top{gap:14px;padding-bottom:18px}
  .results-event h2{font-size:34px}
  .results-mark span{font-size:48px}
  .results-verdict{min-width:0;padding:9px 11px 9px 9px}
  .verdict-medal{width:31px;height:31px;font-size:19px}
  .results-verdict b{font-size:14px}
  .results-verdict span{font-size:6px}
  .results-grid{grid-template-columns:1fr;gap:18px;padding:18px 0}
  .result-side{border-left:0;padding-left:0;border-top:1px solid var(--line-soft);padding-top:14px;gap:12px}
  .result-note{font-size:10px}
  .series-mini{display:none}
  .results-actions{flex-direction:column-reverse}
  .results-actions .btn{width:100%}
