function legPoints(hip, phase, lean, out) {
  const thighA = 0.92 * Math.sin(phase) + 0.08 + lean * 0.12;
  const bend = 0.2 + 1.5 * Math.max(0, Math.sin(phase + 0.18));
  const calfA = thighA - bend;
  const thighLen = 27;
  const calfLen = 26;
  const knee = {
    x: hip.x + Math.sin(thighA) * thighLen,
    y: hip.y + Math.cos(thighA) * thighLen
  };
  const ankle = {
    x: knee.x + Math.sin(calfA) * calfLen,
    y: knee.y + Math.cos(calfA) * calfLen
  };
  const footA = clamp(calfA + 1.35, 0.22, 1.5);
  const toe = {
    x: ankle.x + Math.sin(footA) * 11,
    y: ankle.y + Math.cos(footA) * 11
  };
  out.hip = hip; out.knee = knee; out.ankle = ankle; out.toe = toe;
  out.thighA = thighA; out.calfA = calfA; out.footA = footA;
  return out;
}

function armPoints(shoulder, phase, out) {
  const upperA = -0.92 * Math.sin(phase) + 0.12;
  const foreA = upperA + 1.48;
  const upperLen = 17;
  const foreLen = 16;
  const elbow = {
    x: shoulder.x + Math.sin(upperA) * upperLen,
    y: shoulder.y + Math.cos(upperA) * upperLen
  };
  const hand = {
    x: elbow.x + Math.sin(foreA) * foreLen,
    y: elbow.y + Math.cos(foreA) * foreLen
  };
  out.shoulder = shoulder; out.elbow = elbow; out.hand = hand;
  out.upperA = upperA; out.foreA = foreA;
  return out;
}

function makeSkeleton(pose, phase, speed) {
  const sk = { pose, legs: [], arms: [], hip: null, chest: null, head: null, neck: null };
  let lean = 0.2 + clamp(speed, 0, 1) * 0.12;
  const bob = Math.sin(phase * 2) * 1.1;
  const hip = { x: 0, y: -57 + bob };
  let chest, head, neck, shoulder;

  if (pose === 'run') {
    chest = { x: hip.x + Math.sin(lean) * 39, y: hip.y - Math.cos(lean) * 39 };
    neck = { x: chest.x + 4, y: chest.y - 7 };
    head = { x: chest.x + 9.5, y: chest.y - 22 + Math.sin(phase * 2 + 0.4) * 1.2 };
    shoulder = { x: chest.x - 1, y: chest.y + 4 };

    const l1 = legPoints(hip, phase, lean, {});
    const l2 = legPoints(hip, phase + Math.PI, lean, {});
    l1.back = l1.knee.x < l2.knee.x;
    l2.back = !l1.back;
    sk.legs = [l1, l2];

    const a1 = armPoints(shoulder, phase + Math.PI, {});
    const a2 = armPoints(shoulder, phase, {});
    a1.back = a1.elbow.x < a2.elbow.x;
    a2.back = !a1.back;
    sk.arms = [a1, a2];
  } else if (pose === 'walk') {
    lean = 0.04;
    chest = { x: hip.x + Math.sin(lean) * 38, y: hip.y - Math.cos(lean) * 38 };
    neck = { x: chest.x + 3, y: chest.y - 7 };
    head = { x: chest.x + 8, y: chest.y - 22 };
    shoulder = { x: chest.x - 1, y: chest.y + 4 };
    const l1 = legPoints(hip, phase * 0.64, lean, {});
    const l2 = legPoints(hip, phase * 0.64 + Math.PI, lean, {});
    l1.back = l1.knee.x < l2.knee.x; l2.back = !l1.back;
    sk.legs = [l1, l2];
    const a1 = armPoints(shoulder, phase * 0.6 + Math.PI, {});
    const a2 = armPoints(shoulder, phase * 0.6, {});
    a1.back = true; a2.back = false;
    sk.arms = [a1, a2];
  } else if (pose === 'idle') {
    lean = 0.045;
    chest = { x: hip.x + Math.sin(lean) * 39, y: hip.y - Math.cos(lean) * 39 };
    neck = { x: chest.x + 3, y: chest.y - 7 };
    head = { x: chest.x + 8.5, y: chest.y - 22 };
    shoulder = { x: chest.x - 1, y: chest.y + 4 };
    const breathe = Math.sin(phase * 0.8) * 0.8;
    hip.y += breathe * 0.25;
    chest.y += breathe;
    head.y += breathe;
    sk.legs = [
      { hip, knee: { x: -6, y: -31 }, ankle: { x: -9, y: -3 }, toe: { x: 3, y: -1 }, back: true },
      { hip, knee: { x: 7, y: -31 }, ankle: { x: 10, y: -3 }, toe: { x: 22, y: -1 }, back: false }
    ];
    sk.arms = [
      { shoulder, elbow: { x: shoulder.x - 10, y: shoulder.y + 15 }, hand: { x: shoulder.x - 5, y: shoulder.y + 27 }, back: true },
      { shoulder, elbow: { x: shoulder.x + 8, y: shoulder.y + 16 }, hand: { x: shoulder.x + 4, y: shoulder.y + 29 }, back: false }
    ];
  } else if (pose === 'victory') {
    lean = -0.04;
    hip.y = -58;
    chest = { x: hip.x + Math.sin(lean) * 40, y: hip.y - Math.cos(lean) * 40 };
    neck = { x: chest.x + 2, y: chest.y - 7 };
    head = { x: chest.x + 7, y: chest.y - 23 };
    shoulder = { x: chest.x - 1, y: chest.y + 4 };
    sk.legs = [
      { hip, knee: { x: -10, y: -31 }, ankle: { x: -15, y: -2 }, toe: { x: -3, y: 0 }, back: true },
      { hip, knee: { x: 9, y: -31 }, ankle: { x: 13, y: -2 }, toe: { x: 24, y: 0 }, back: false }
    ];
    sk.arms = [
      { shoulder, elbow: { x: shoulder.x + 12, y: shoulder.y - 13 }, hand: { x: shoulder.x + 17, y: shoulder.y - 29 }, back: true },
      { shoulder, elbow: { x: shoulder.x - 10, y: shoulder.y - 16 }, hand: { x: shoulder.x - 7, y: shoulder.y - 33 }, back: false }
    ];
    sk.medal = true;
  } else if (pose === 'crouch' || pose === 'set') {
    const set = pose === 'set';
    hip.x = set ? 1 : 0;
    hip.y = set ? -47 : -39;
    lean = set ? 1.04 : 0.94;
    chest = { x: hip.x + Math.sin(lean) * 36, y: hip.y - Math.cos(lean) * 36 };
    neck = { x: chest.x + 7, y: chest.y - 5 };
    head = { x: chest.x + 15, y: chest.y - 16 };
    shoulder = { x: chest.x - 2, y: chest.y + 3 };
    sk.legs = [
      { hip, knee: { x: -23, y: hip.y + 16 }, ankle: { x: -46, y: -4 }, toe: { x: -34, y: -1 }, back: true, start: true },
      { hip, knee: { x: 17, y: hip.y + 13 }, ankle: { x: 13, y: -3 }, toe: { x: 26, y: -1 }, back: false, start: true }
    ];
    sk.arms = [
      { shoulder, elbow: { x: shoulder.x + 8, y: shoulder.y + 22 }, hand: { x: 41, y: -2 }, back: true, start: true },
      { shoulder, elbow: { x: shoulder.x + 17, y: shoulder.y + 20 }, hand: { x: 52, y: -1 }, back: false, start: true }
    ];
  } else if (pose === 'jump') {
    lean = 0.05;
    hip.y = -66;
    chest = { x: 2, y: -102 };
    neck = { x: 5, y: -109 };
    head = { x: 12, y: -124 };
    shoulder = { x: 1, y: -98 };
    sk.legs = [
      { hip, knee: { x: 26, y: -57 }, ankle: { x: 41, y: -39 }, toe: { x: 51, y: -34 }, back: false },
      { hip, knee: { x: -17, y: -50 }, ankle: { x: -30, y: -66 }, toe: { x: -35, y: -51 }, back: true }
    ];
    sk.arms = [
      { shoulder, elbow: { x: -14, y: -115 }, hand: { x: -5, y: -129 }, back: true },
      { shoulder, elbow: { x: 16, y: -118 }, hand: { x: 30, y: -126 }, back: false }
    ];
  } else if (pose === 'land') {
    lean = 0.65;
    hip.y = -43;
    chest = { x: 18, y: -75 };
    neck = { x: 23, y: -81 };
    head = { x: 33, y: -93 };
    shoulder = { x: 16, y: -71 };
    sk.legs = [
      { hip, knee: { x: -9, y: -24 }, ankle: { x: -20, y: -3 }, toe: { x: -10, y: -1 }, back: true },
      { hip, knee: { x: 24, y: -24 }, ankle: { x: 31, y: -3 }, toe: { x: 42, y: -1 }, back: false }
    ];
    sk.arms = [
      { shoulder, elbow: { x: 34, y: -59 }, hand: { x: 48, y: -55 }, back: true },
      { shoulder, elbow: { x: 2, y: -54 }, hand: { x: -6, y: -44 }, back: false }
    ];
  } else if (pose === 'throw') {
    lean = -0.11;
    hip.y = -58;
    chest = { x: 7, y: -95 };
    neck = { x: 10, y: -102 };
    head = { x: 18, y: -116 };
    shoulder = { x: 7, y: -91 };
    sk.legs = [
      { hip, knee: { x: -18, y: -35 }, ankle: { x: -27, y: -3 }, toe: { x: -15, y: -1 }, back: true },
      { hip, knee: { x: 19, y: -34 }, ankle: { x: 27, y: -3 }, toe: { x: 39, y: -1 }, back: false }
    ];
    sk.arms = [
      { shoulder, elbow: { x: -8, y: -112 }, hand: { x: -19, y: -126 }, back: true },
      { shoulder, elbow: { x: 28, y: -102 }, hand: { x: 40, y: -90 }, back: false }
    ];
    sk.throwHand = { x: -19, y: -126 };
  } else if (pose === 'release') {
    lean = 0.16;
    hip.y = -60;
    chest = { x: 7, y: -98 };
    neck = { x: 9, y: -105 };
    head = { x: 17, y: -119 };
    shoulder = { x: 7, y: -94 };
    sk.legs = [
      { hip, knee: { x: -20, y: -37 }, ankle: { x: -31, y: -3 }, toe: { x: -19, y: -1 }, back: true },
      { hip, knee: { x: 23, y: -32 }, ankle: { x: 31, y: -2 }, toe: { x: 43, y: 0 }, back: false }
    ];
    sk.arms = [
      { shoulder, elbow: { x: 23, y: -108 }, hand: { x: 38, y: -117 }, back: true },
      { shoulder, elbow: { x: 17, y: -80 }, hand: { x: 9, y: -68 }, back: false }
    ];
    sk.throwHand = { x: 38, y: -117 };
  } else {
    return makeSkeleton('idle', phase, speed);
  }

  sk.legs.forEach(l => { l.thighA = Math.atan2(l.knee.x - l.hip.x, l.knee.y - l.hip.y); l.calfA = Math.atan2(l.ankle.x - l.knee.x, l.ankle.y - l.knee.y); });
  sk.hip = hip; sk.chest = chest; sk.head = head; sk.neck = neck; sk.shoulder = shoulder;
  sk.lean = lean;
  return sk;
}

function limb(ctx, a, b, width, color, dark, light) {
  ctx.lineCap = 'round';
  ctx.lineJoin = 'round';
  ctx.strokeStyle = dark;
  ctx.lineWidth = width + 1.9;
  ctx.beginPath(); ctx.moveTo(a.x, a.y); ctx.lineTo(b.x, b.y); ctx.stroke();
  ctx.strokeStyle = color;
  ctx.lineWidth = width;
  ctx.beginPath(); ctx.moveTo(a.x, a.y); ctx.lineTo(b.x, b.y); ctx.stroke();
  if (light) {
    ctx.strokeStyle = light;
    ctx.lineWidth = Math.max(1, width * 0.2);
    ctx.globalAlpha *= 0.8;
    ctx.beginPath();
    ctx.moveTo(a.x + width * 0.2, a.y - width * 0.18);
    ctx.lineTo(b.x + width * 0.18, b.y - width * 0.16);
    ctx.stroke();
    ctx.globalAlpha /= 0.8;
  }
}

function drawShoe(ctx, leg, kit, alpha = 1) {
  const { ankle, toe, footA } = leg;
  const dx = Math.sin(footA), dy = Math.cos(footA);
  const nx = -dy, ny = dx;
  const heel = { x: ankle.x - dx * 4.5, y: ankle.y - dy * 4.5 };
  const tip = { x: toe.x + dx * 1.8, y: toe.y + dy * 1.8 };
  ctx.globalAlpha *= alpha;
  ctx.beginPath();
  ctx.moveTo(heel.x + nx * 4.3, heel.y + ny * 4.3);
  ctx.quadraticCurveTo(tip.x + nx * 3.2, tip.y + ny * 3.2, tip.x, tip.y);
  ctx.lineTo(heel.x - nx * 3.4, heel.y - ny * 3.4);
  ctx.closePath();
  ctx.fillStyle = kit.shoe;
  ctx.fill();
  ctx.strokeStyle = shade(kit.shoe, -0.48);
  ctx.lineWidth = 1;
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(heel.x + nx * 2.2, heel.y + ny * 2.2);
  ctx.quadraticCurveTo(tip.x + nx * 2.2, tip.y + ny * 2.2, tip.x, tip.y);
  ctx.strokeStyle = 'rgba(255,255,255,.82)';
  ctx.lineWidth = 1.15;
  ctx.stroke();
  ctx.globalAlpha /= alpha;
}

function drawMedal(ctx, kit) {
  ctx.save();
  ctx.translate(10, -84);
  ctx.strokeStyle = 'rgba(255,210,80,.72)';
  ctx.lineWidth = 1.4;
  ctx.beginPath(); ctx.moveTo(-4, 0); ctx.quadraticCurveTo(2, 10, 0, 14); ctx.stroke();
  ctx.beginPath(); ctx.moveTo(6, 0); ctx.quadraticCurveTo(2, 9, 0, 14); ctx.stroke();
  const grad = ctx.createRadialGradient(-1, 13, 0, 0, 15, 6);
  grad.addColorStop(0, '#fff3b1'); grad.addColorStop(0.5, '#f0c84d'); grad.addColorStop(1, '#a87518');
  ctx.fillStyle = grad;
  ctx.beginPath(); ctx.arc(0, 16, 5.6, 0, TAU); ctx.fill();
  ctx.strokeStyle = 'rgba(255,255,255,.5)'; ctx.lineWidth = 0.7; ctx.stroke();
  ctx.restore();
}

function drawJavelin(ctx, hand, angle, kit) {
  ctx.save();
  ctx.translate(hand.x, hand.y);
  ctx.rotate(angle);
  const grad = ctx.createLinearGradient(0, -30, 0, 30);
  grad.addColorStop(0, '#e8d4a2'); grad.addColorStop(0.5, '#a68a58'); grad.addColorStop(1, '#e4cd98');
  ctx.strokeStyle = grad;
  ctx.lineWidth = 2.1;
  ctx.lineCap = 'round';
  ctx.beginPath(); ctx.moveTo(-48, 0); ctx.lineTo(50, 0); ctx.stroke();
  ctx.strokeStyle = '#6c542f'; ctx.lineWidth = 1.1;
  ctx.beginPath(); ctx.moveTo(-8, 0); ctx.lineTo(10, 0); ctx.stroke();
  ctx.fillStyle = '#e9edf1';
  ctx.beginPath(); ctx.moveTo(50, 0); ctx.lineTo(39, -3.3); ctx.lineTo(39, 3.3); ctx.closePath(); ctx.fill();
  ctx.restore();
}

function drawTorso(ctx, sk, kit) {
  const hip = sk.hip, chest = sk.chest;
  const dx = chest.x - hip.x, dy = chest.y - hip.y;
  const len = Math.hypot(dx, dy) || 1;
  const nx = -dy / len, ny = dx / len;
  const hipW = 7.3, chestW = 11.5;
  const hipL = { x: hip.x + nx * hipW, y: hip.y + ny * hipW };
  const hipR = { x: hip.x - nx * hipW, y: hip.y - ny * hipW };
  const chestL = { x: chest.x + nx * chestW, y: chest.y + ny * chestW };
  const chestR = { x: chest.x - nx * chestW, y: chest.y - ny * chestW };

  // shorts
  ctx.beginPath();
  ctx.moveTo(hipL.x - 1, hipL.y - 1);
  ctx.quadraticCurveTo(hip.x - 11, hip.y + 8, hipL.x - 4, hip.y + 15);
  ctx.lineTo(hipL.x + 7, hip.y + 16);
  ctx.quadraticCurveTo(hip.x + 7, hip.y + 6, hipR.x + 7, hipR.y + 1);
  ctx.closePath();
  ctx.fillStyle = kit.primary;
  ctx.fill();

  // jersey
  ctx.beginPath();
  ctx.moveTo(hipR.x, hipR.y);
  ctx.quadraticCurveTo(hip.x - 10, (hip.y + chest.y) / 2, chestR.x - 2, chestR.y + 3);
  ctx.quadraticCurveTo(chest.x - 2, chest.y - 6, chestL.x + 1, chestL.y);
  ctx.quadraticCurveTo(chest.x + 12, (hip.y + chest.y) / 2, hipL.x + 2, hipL.y + 2);
  ctx.closePath();
  ctx.fillStyle = kit.primary;
  ctx.fill();
  ctx.strokeStyle = shade(kit.primary, -0.4);
  ctx.lineWidth = 0.8;
  ctx.stroke();

  // chest stripe
  ctx.save();
  ctx.clip();
  ctx.strokeStyle = kit.secondary;
  ctx.lineWidth = 5;
  ctx.beginPath();
  ctx.moveTo(chest.x - 18, chest.y + 7);
  ctx.lineTo(chest.x + 18, chest.y - 5);
  ctx.stroke();
  ctx.strokeStyle = rgba(kit.accent, 0.9);
  ctx.lineWidth = 1.1;
  ctx.beginPath();
  ctx.moveTo(chest.x - 18, chest.y + 10);
  ctx.lineTo(chest.x + 18, chest.y - 2);
  ctx.stroke();
  ctx.restore();

  // side stripe
  ctx.strokeStyle = rgba(kit.secondary, 0.85);
  ctx.lineWidth = 1.5;
  ctx.beginPath();
  ctx.moveTo(hipR.x - 1, hipR.y - 1);
  ctx.quadraticCurveTo(hip.x - 7, (hip.y + chest.y) / 2, chestR.x - 1, chestR.y + 4);
  ctx.stroke();

  // bib
  ctx.save();
  ctx.translate(chest.x + 2, chest.y + 14);
  ctx.rotate(sk.lean * 0.7);
  ctx.fillStyle = 'rgba(247,244,234,.92)';
  ctx.fillRect(-5.5, -4, 11, 8.5);
  ctx.fillStyle = '#101828';
  ctx.font = '600 6.5px "Barlow Condensed", sans-serif';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillText('7', 0, 0.4);
  ctx.restore();

  // shorts trim
  ctx.strokeStyle = rgba(kit.accent, 0.88);
  ctx.lineWidth = 1.1;
  ctx.beginPath();
  ctx.moveTo(hipL.x - 3, hip.y + 8);
  ctx.quadraticCurveTo(hip.x, hip.y + 13, hipR.x + 3, hip.y + 7);
  ctx.stroke();

  // rim light along back/upper torso
  ctx.strokeStyle = rgba(kit.trim || '#ffffff', 0.62);
  ctx.lineWidth = 1.25;
  ctx.beginPath();
  ctx.moveTo(chestL.x, chestL.y + 2);
  ctx.quadraticCurveTo(chest.x + 11, chest.y + 12, hipL.x - 1, hip.y - 2);
  ctx.stroke();

  // subtle chest shadow
  ctx.strokeStyle = 'rgba(0,0,0,.18)';
  ctx.lineWidth = 4;
  ctx.beginPath();
  ctx.moveTo(chestR.x + 3, chestR.y + 7);
  ctx.quadraticCurveTo(chest.x - 4, (hip.y + chest.y) / 2, hipR.x + 3, hipR.y - 2);
  ctx.stroke();
}

function drawHead(ctx, sk, kit, phase) {
  const head = sk.head;
  const r = 9.2;
  // neck
  ctx.strokeStyle = kit.skinDark;
  ctx.lineWidth = 5.8;
  ctx.lineCap = 'round';
  ctx.beginPath();
  ctx.moveTo(sk.neck.x, sk.neck.y + 1);
  ctx.lineTo(head.x - 3, head.y + r * 0.7);
  ctx.stroke();
  ctx.strokeStyle = kit.skin;
  ctx.lineWidth = 4.5;
  ctx.beginPath();
  ctx.moveTo(sk.neck.x, sk.neck.y);
  ctx.lineTo(head.x - 3, head.y + r * 0.6);
  ctx.stroke();

  // ear
  ctx.fillStyle = kit.skinDark;
  ctx.beginPath(); ctx.ellipse(head.x - 4.5, head.y + 1, 2.4, 3.2, -0.2, 0, TAU); ctx.fill();

  // head shape (slight forward jaw)
  ctx.beginPath();
  ctx.ellipse(head.x, head.y, r * 0.94, r, 0.08, 0, TAU);
  ctx.fillStyle = kit.skin;
  ctx.fill();

  // jaw shading
  ctx.beginPath();
  ctx.ellipse(head.x + 1.5, head.y + 3.4, 6.7, 6.1, 0.1, 0.2, Math.PI * 1.02);
  ctx.fillStyle = rgba(kit.skinDark, 0.25);
  ctx.fill();

  // nose
  ctx.beginPath();
  ctx.moveTo(head.x + 7.6, head.y - 1.5);
  ctx.quadraticCurveTo(head.x + 10, head.y + 1.6, head.x + 7.3, head.y + 3.2);
  ctx.lineTo(head.x + 6.4, head.y + 2.2);
  ctx.closePath();
  ctx.fillStyle = kit.skin;
  ctx.fill();

  // hair
  ctx.beginPath();
  ctx.arc(head.x - 1, head.y - 1.2, r * 1.02, Math.PI * 0.68, Math.PI * 2.02);
  ctx.quadraticCurveTo(head.x + 2, head.y - 8.2, head.x + 4, head.y - 5.2);
  ctx.quadraticCurveTo(head.x - 1, head.y - 5.7, head.x - 7.2, head.y + 3.3);
  ctx.closePath();
  ctx.fillStyle = kit.hair;
  ctx.fill();
  // hair sheen
  ctx.strokeStyle = 'rgba(255,255,255,.2)';
  ctx.lineWidth = 0.8;
  ctx.beginPath();
  ctx.arc(head.x - 2, head.y - 2.2, r * 0.78, Math.PI * 0.9, Math.PI * 1.5);
  ctx.stroke();

  // headband
  if (kit.trim) {
    ctx.strokeStyle = rgba(kit.trim, 0.9);
    ctx.lineWidth = 2.1;
    ctx.beginPath();
    ctx.arc(head.x - 0.5, head.y - 1.2, r * 0.87, Math.PI * 1.08, Math.PI * 1.87);
    ctx.stroke();
  }

  // features
  ctx.fillStyle = '#15100e';
  ctx.beginPath();
  ctx.ellipse(head.x + 4.6, head.y - 0.8, 1.15, 0.9, 0.15, 0, TAU);
  ctx.fill();
  ctx.strokeStyle = 'rgba(36,18,10,.75)';
  ctx.lineWidth = 0.75;
  ctx.beginPath();
  ctx.moveTo(head.x + 2.6, head.y - 3.4);
  ctx.lineTo(head.x + 6.9, head.y - 2.7);
  ctx.stroke();
  ctx.strokeStyle = 'rgba(80,35,25,.6)';
  ctx.lineWidth = 0.8;
  ctx.beginPath();
  ctx.moveTo(head.x + 6.2, head.y + 5.1);
  ctx.quadraticCurveTo(head.x + 7.5, head.y + 5.4, head.x + 7.8, head.y + 4.7);
  ctx.stroke();
}

function drawStartBlocks(ctx, sk, kit) {
  // miniature block pedals behind the athlete's feet
  ctx.fillStyle = 'rgba(11,20,34,.95)';
  ctx.strokeStyle = 'rgba(247,201,80,.5)';
  ctx.lineWidth = 1;
  ctx.beginPath();
  ctx.moveTo(-54, -1); ctx.lineTo(-31, -7); ctx.lineTo(-27, -2); ctx.lineTo(-50, 4); ctx.closePath();
  ctx.fill(); ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(-4, -1); ctx.lineTo(18, -7); ctx.lineTo(22, -2); ctx.lineTo(0, 4); ctx.closePath();
  ctx.fill(); ctx.stroke();
}

/**
 * Draw a stylised side-view athlete.
 */
export function drawAthlete(ctx, opts) {
  const {
    x = 0, y = 0, scale = 1, phase = 0, pose = 'run', speed = 0.6,
    kit = KITS.player, flip = false, alpha = 1, shadow = 1, javelin = null,
    glow = 0, medal = false
  } = opts;
  const sk = makeSkeleton(pose, phase, speed);
  const s = scale * (flip ? -1 : 1);
  const bob = pose === 'run' ? Math.sin(phase * 2 + 0.15) : 0;

  ctx.save();
  ctx.globalAlpha *= alpha;
  ctx.translate(x, y);
  if (shadow) {
    ctx.save();
    ctx.translate(0, 1.5);
    ctx.scale(1, 0.24);
    const grad = ctx.createRadialGradient(0, 0, 1, 0, 0, 32);
    grad.addColorStop(0, 'rgba(0,0,0,.42)');
    grad.addColorStop(0.65, 'rgba(0,0,0,.19)');
    grad.addColorStop(1, 'rgba(0,0,0,0)');
    ctx.fillStyle = grad;
    ctx.beginPath(); ctx.arc(0, 0, 32 * shadow, 0, TAU); ctx.fill();
    ctx.restore();
  }
  ctx.scale(s, scale);
  ctx.translate(0, bob);
  if (glow > 0) {
    ctx.shadowColor = rgba(kit.trim || '#f6cc58', 0.7 * glow);
    ctx.shadowBlur = 18 * glow;
  }

  if (sk.medal || medal) drawMedal(ctx, kit);

  // Back limbs
  const backLeg = sk.legs.find(l => l.back) || sk.legs[0];
  const frontLeg = sk.legs.find(l => !l.back) || sk.legs[1];
  const backArm = sk.arms.find(a => a.back) || sk.arms[0];
  const frontArm = sk.arms.find(a => !a.back) || sk.arms[1];

  if (backLeg) {
    limb(ctx, backLeg.hip, backLeg.knee, 10, shade(kit.skin, -0.18), shade(kit.skinDark, -0.22), rgba('#ffffff', 0.1));
    limb(ctx, backLeg.knee, backLeg.ankle, 6.7, shade(kit.skin, -0.12), shade(kit.skinDark, -0.18), null);
    // sock
    const sockA = { x: lerp(backLeg.knee.x, backLeg.ankle.x, 0.72), y: lerp(backLeg.knee.y, backLeg.ankle.y, 0.72) };
    limb(ctx, sockA, backLeg.ankle, 7.2, shade(kit.sock, -0.12), 'rgba(20,25,36,.4)', null);
    drawShoe(ctx, backLeg, kit, 0.88);
  }
  if (backArm) {
    limb(ctx, backArm.shoulder, backArm.elbow, 6.4, shade(kit.skin, -0.18), shade(kit.skinDark, -0.2), null);
    limb(ctx, backArm.elbow, backArm.hand, 4.8, shade(kit.skin, -0.12), shade(kit.skinDark, -0.16), null);
    // sleeve
    limb(ctx, backArm.shoulder, { x: lerp(backArm.shoulder.x, backArm.elbow.x, 0.28), y: lerp(backArm.shoulder.y, backArm.elbow.y, 0.28) }, 8.2, shade(kit.primary, -0.1), shade(kit.primary, -0.4), null);
    ctx.fillStyle = shade(kit.skin, -0.14);
    ctx.beginPath(); ctx.arc(backArm.hand.x, backArm.hand.y, 3, 0, TAU); ctx.fill();
  }

  drawTorso(ctx, sk, kit);

  if (frontLeg) {
    limb(ctx, frontLeg.hip, frontLeg.knee, 10.5, kit.skin, kit.skinDark, rgba('#ffffff', 0.22));
    limb(ctx, frontLeg.knee, frontLeg.ankle, 7, kit.skin, kit.skinDark, rgba('#ffffff', 0.12));
    const sockA = { x: lerp(frontLeg.knee.x, frontLeg.ankle.x, 0.72), y: lerp(frontLeg.knee.y, frontLeg.ankle.y, 0.72) };
    limb(ctx, sockA, frontLeg.ankle, 7.5, kit.sock, 'rgba(30,35,48,.35)', null);
    drawShoe(ctx, frontLeg, kit, 1);
  }

  if (frontArm) {
    limb(ctx, frontArm.shoulder, frontArm.elbow, 6.7, kit.skin, kit.skinDark, rgba('#ffffff', 0.18));
    limb(ctx, frontArm.elbow, frontArm.hand, 5, kit.skin, kit.skinDark, rgba('#ffffff', 0.1));
    limb(ctx, frontArm.shoulder, { x: lerp(frontArm.shoulder.x, frontArm.elbow.x, 0.3), y: lerp(frontArm.shoulder.y, frontArm.elbow.y, 0.3) }, 8.4, kit.primary, shade(kit.primary, -0.42), null);
    // wristband
    const wrist = { x: lerp(frontArm.elbow.x, frontArm.hand.x, 0.78), y: lerp(frontArm.elbow.y, frontArm.hand.y, 0.78) };
    limb(ctx, wrist, { x: lerp(frontArm.elbow.x, frontArm.hand.x, 0.9), y: lerp(frontArm.elbow.y, frontArm.hand.y, 0.9) }, 5.4, kit.accent, shade(kit.accent, -0.3), null);
    ctx.fillStyle = kit.skin;
    ctx.beginPath(); ctx.arc(frontArm.hand.x, frontArm.hand.y, 3.15, 0, TAU); ctx.fill();
  }

  drawHead(ctx, sk, kit, phase);

  if ((pose === 'crouch' || pose === 'set') && sk.legs[0]?.start) {
    drawStartBlocks(ctx, sk, kit);
  }

  if (javelin) {
    const hand = sk.throwHand || (frontArm ? frontArm.hand : { x: 18, y: -112 });
    drawJavelin(ctx, hand, javelin.angle ?? -0.16, kit);
  }

  ctx.restore();
}

export function drawAthleteShadow(ctx, x, y, scale = 1, width = 38) {
  ctx.save();
  ctx.translate(x, y);
  ctx.scale(1, 0.23);
  const grad = ctx.createRadialGradient(0, 0, 1, 0, 0, width * scale);
  grad.addColorStop(0, 'rgba(0,0,0,.42)');
  grad.addColorStop(0.6, 'rgba(0,0,0,.15)');
  grad.addColorStop(1, 'rgba(0,0,0,0)');
  ctx.fillStyle = grad;
  ctx.beginPath(); ctx.arc(0, 0, width * scale, 0, TAU); ctx.fill();
  ctx.restore();
}

import {
  clamp, lerp, rand, seeded, TAU, rgba, shade, withAlpha
} from './utils.js';
import { drawAthlete, KITS } from './athlete.js';

const CROWD_COLORS = [
  '#26324a', '#39405a', '#614b49', '#7b4d42', '#283d3b', '#4f4f5d',
  '#8b6a45', '#b99146', '#d5c197', '#2e4666', '#5c3440', '#46556d',
  '#b65543', '#d9a637', '#5e7b91', '#e4d6ae', '#84495a', '#1e2a42'
];

const FLASH_COLORS = ['#f8f4e2', '#f8d87b', '#ffffff', '#8cd9ff'];

export class StadiumWorld {
  constructor() {
    this.t = 0;
    this.W = 0;
    this.H = 0;
    this.crowd = null;
    this.trackNoise = null;
    this.stars = [];
    this.motes = [];
    this.flashes = [];
    this.beamPhase = 0;
    this.camX = 0;
    this.meter = 50;
    this.anchor = 0.42;
    this.mode = 'menu';
    this.layoutData = null;
    this.fireworks = [];
    this.resize(window.innerWidth, window.innerHeight);
  }

  resize(w, h) {
    this.W = w;
    this.H = h;
    this.u = clamp(h / 900, 0.62, 1.35);
    this.buildCrowd();
    this.buildTrackNoise();
    this.buildStars();
    this.buildMotes();
    this.layoutData = null;
  }

  buildStars() {
    const r = seeded(41);
    this.stars = Array.from({ length: Math.floor(70 + this.W / 36) }, () => ({
      x: r() * this.W,
      y: r() * this.H * 0.26,
      s: r() * 1.45 + 0.25,
      a: 0.18 + r() * 0.62,
      tw: r() * TAU
    }));
  }

  buildMotes() {
    const r = seeded(77);
    this.motes = Array.from({ length: Math.min(90, Math.floor(this.W / 16)) }, () => ({
      x: r() * this.W,
      y: this.H * (0.25 + r() * 0.62),
      s: 0.4 + r() * 1.8,
      vx: (r() - 0.5) * 3.5,
      vy: -2 - r() * 6,
      a: 0.05 + r() * 0.3,
      ph: r() * TAU
    }));
  }

  buildCrowd() {
    const W = this.W, H = this.H;
    const cw = Math.ceil(W * 1.7);
    const ch = Math.ceil(H * 0.31);
    const c = document.createElement('canvas');
    const scale = Math.min(2, Math.max(1, window.devicePixelRatio || 1));
    c.width = Math.ceil(cw * scale);
    c.height = Math.ceil(ch * scale);
    const ctx = c.getContext('2d');
    ctx.scale(scale, scale);
    const r = seeded(129);
    ctx.clearRect(0, 0, cw, ch);

    // Back rows are dimmer and denser.
    const rows = 18;
    for (let row = 0; row < rows; row++) {
      const ry = (row / rows) * ch + r() * 2;
      const depth = row / rows;
      const count = Math.floor(cw / (5.2 + depth * 1.8));
      for (let i = 0; i < count; i++) {
        const x = r() * cw;
        const y = ry + (r() - 0.5) * 3.2;
        const color = CROWD_COLORS[Math.floor(r() * CROWD_COLORS.length)];
        const a = 0.18 + r() * 0.6;
        const size = 1.1 + depth * 1.8 + r() * 0.8;
        ctx.globalAlpha = a;
        ctx.fillStyle = color;
        ctx.beginPath();
        ctx.arc(x, y, size * 0.58, 0, TAU);
        ctx.fill();
        ctx.globalAlpha = a * 0.7;
        ctx.fillRect(x - size * 0.62, y + size * 0.55, size * 1.25, size * 1.4);
      }
    }

    // Occasional phone camera lights.
    for (let i = 0; i < 34; i++) {
      const x = r() * cw;
      const y = r() * ch;
      ctx.globalAlpha = 0.5 + r() * 0.5;
      ctx.fillStyle = r() > 0.35 ? '#fff8db' : '#a9e7ff';
      ctx.beginPath(); ctx.arc(x, y, 0.7 + r() * 1.1, 0, TAU); ctx.fill();
    }
    ctx.globalAlpha = 1;
    this.crowd = c;
    this.crowdW = cw;
    this.crowdH = ch;

    this.flashes = Array.from({ length: 11 }, () => ({
      x: r() * W,
      y: H * (0.28 + r() * 0.2),
      next: 1 + r() * 7,
      life: 0
    }));
  }

  buildTrackNoise() {
    const c = document.createElement('canvas');
    c.width = 180;
    c.height = 180;
    const ctx = c.getContext('2d');
    const r = seeded(313);
    for (let i = 0; i < 1700; i++) {
      const g = 80 + r() * 90;
      ctx.fillStyle = `rgba(${g + r() * 35},${g * 0.65},${g * 0.55},${0.04 + r() * 0.09})`;
      ctx.fillRect(r() * 180, r() * 180, 0.5 + r() * 1.4, 0.5 + r() * 1.4);
    }
    this.trackNoise = c;
  }

  update(dt) {
    this.t += dt;
    this.beamPhase += dt;
    for (const m of this.motes) {
      m.x += m.vx * dt;
      m.y += m.vy * dt;
      if (m.y < this.H * 0.15) { m.y = this.H * 0.88; m.x = rand(0, this.W); }
      if (m.x < -4) m.x = this.W + 4;
      if (m.x > this.W + 4) m.x = -4;
    }
    for (const f of this.flashes) {
      f.next -= dt;
      if (f.next <= 0) {
        f.life = 0.26;
        f.next = 2.8 + rand() * 8;
      }
      f.life = Math.max(0, f.life - dt);
    }
    for (let i = this.fireworks.length - 1; i >= 0; i--) {
      const fw = this.fireworks[i];
      fw.life += dt;
      if (fw.life > fw.dur) this.fireworks.splice(i, 1);
    }
  }

  getLayout(mode = this.mode) {
    const W = this.W, H = this.H;
    if (mode === 'sprint') {
      const top = H * 0.585;
      const bottom = H * 0.975;
      const laneCount = 8;
      return { top, bottom, laneCount, laneH: (bottom - top) / laneCount, anchor: 0.415, runway: false };
    }
    if (mode === 'longjump' || mode === 'javelin') {
      const top = H * 0.635;
      const bottom = H * 0.82;
      return { top, bottom, laneCount: 3, laneH: (bottom - top) / 3, anchor: 0.36, runway: true };
    }
    if (mode === 'ceremony') {
      return { top: H * 0.705, bottom: H * 0.99, laneCount: 5, laneH: H * 0.057, anchor: 0.42, runway: false };
    }
    // menu
    return { top: H * 0.665, bottom: H * 1.04, laneCount: 5, laneH: H * 0.075, anchor: 0.42, runway: false };
  }

  groundY(lane = 3, mode = this.mode) {
    const L = this.getLayout(mode);
    if (L.runway) return L.top + L.laneH * 1.62;
    return L.top + (lane + 0.72) * L.laneH;
  }

  laneScale(lane = 3, mode = this.mode) {
    const L = this.getLayout(mode);
    if (L.runway) return 0.92;
    return 0.75 + (lane / Math.max(1, L.laneCount - 1)) * 0.28;
  }

  sx(worldX) {
    return this.W * this.anchor + (worldX - this.camX) * this.meter;
  }

  setCamera(camX, meter, anchor = 0.42, mode = this.mode) {
    this.camX = camX;
    this.meter = meter;
    this.anchor = anchor;
    this.mode = mode;
  }

  /* ------------------------------------------------------------------ */
  /*  SKY + STADIUM                                                      */
  /* ------------------------------------------------------------------ */
  drawSky(ctx, opts = {}) {
    const W = this.W, H = this.H;
    const mode = opts.mode || this.mode;
    const menu = mode === 'menu' || mode === 'ceremony';

    const sky = ctx.createLinearGradient(0, 0, 0, H * 0.58);
    if (menu) {
      sky.addColorStop(0, '#030713');
      sky.addColorStop(0.36, '#09142a');
      sky.addColorStop(0.66, '#1a2740');
      sky.addColorStop(1, '#4a3c3d');
    } else {
      sky.addColorStop(0, '#020611');
      sky.addColorStop(0.42, '#071226');
      sky.addColorStop(0.72, '#16243a');
      sky.addColorStop(1, '#4b3b39');
    }
    ctx.fillStyle = sky;
    ctx.fillRect(0, 0, W, H * 0.62);

    // Haze glow on the horizon.
    const hg = ctx.createRadialGradient(W * 0.58, H * 0.47, 0, W * 0.58, H * 0.47, W * 0.55);
    hg.addColorStop(0, 'rgba(255,164,91,.16)');
    hg.addColorStop(0.45, 'rgba(220,98,58,.065)');
    hg.addColorStop(1, 'rgba(40,40,60,0)');
    ctx.fillStyle = hg;
    ctx.fillRect(0, 0, W, H * 0.58);

    // Stars.
    for (const s of this.stars) {
      const tw = 0.55 + 0.45 * Math.sin(this.t * 1.3 + s.tw);
      ctx.globalAlpha = s.a * tw * (menu ? 0.8 : 0.65);
      ctx.fillStyle = '#d9e8ff';
      ctx.beginPath(); ctx.arc(s.x, s.y, s.s, 0, TAU); ctx.fill();
    }
    ctx.globalAlpha = 1;

    // Thin clouds, low-lit by the stadium.
    ctx.save();
    for (let i = 0; i < 4; i++) {
      const y = H * (0.12 + i * 0.072);
      const x = W * (0.15 + i * 0.22) + Math.sin(this.t * 0.02 + i) * 30;
      const g = ctx.createRadialGradient(x, y, 0, x, y, W * 0.3);
      g.addColorStop(0, `rgba(118,132,164,${0.035 + i * 0.008})`);
      g.addColorStop(1, 'rgba(118,132,164,0)');
      ctx.fillStyle = g;
      ctx.beginPath();
      ctx.ellipse(x, y, W * 0.3, H * 0.055, -0.05, 0, TAU);
      ctx.fill();
    }
    ctx.restore();
  }

  drawCity(ctx) {
    const W = this.W, H = this.H;
    const base = H * 0.505;
    const r = seeded(88);
    ctx.save();
    ctx.globalAlpha = 0.72;
    for (let i = 0; i < 34; i++) {
      const bw = 9 + r() * 32;
      const bh = 15 + r() * H * 0.09;
      const x = r() * W;
      const y = base - bh;
      ctx.fillStyle = i % 4 === 0 ? '#0a1526' : '#07101f';
      ctx.fillRect(x, y, bw, bh);
      if (r() > 0.35) {
        ctx.fillStyle = 'rgba(255,191,104,.36)';
        for (let wy = y + 5; wy < base - 4; wy += 7) {
          if (r() > 0.58) ctx.fillRect(x + 3 + r() * Math.max(1, bw - 7), wy, 1.3, 1.3);
        }
      }
    }
    ctx.restore();
    const haze = ctx.createLinearGradient(0, base - 90, 0, base + 15);
    haze.addColorStop(0, 'rgba(4,10,20,0)');
    haze.addColorStop(1, 'rgba(5,11,21,.86)');
    ctx.fillStyle = haze;
    ctx.fillRect(0, base - 100, W, 115);
  }

  drawRoof(ctx) {
    const W = this.W, H = this.H;
    const roofY = H * 0.115;
    const roofBottom = H * 0.245;

    // roof canopy shadow
    ctx.fillStyle = 'rgba(2,6,14,.62)';
    ctx.beginPath();
    ctx.moveTo(-20, H * 0.02);
    ctx.lineTo(W + 20, H * -0.01);
    ctx.lineTo(W + 20, roofBottom * 0.82);
    ctx.quadraticCurveTo(W * 0.78, roofBottom, W * 0.62, roofBottom * 0.93);
    ctx.quadraticCurveTo(W * 0.4, roofBottom * 1.08, W * 0.2, roofBottom * 0.96);
    ctx.quadraticCurveTo(W * 0.04, roofBottom * 0.9, -20, H * 0.17);
    ctx.closePath();
    ctx.fill();

    // leading edge of the roof
    const edge = ctx.createLinearGradient(0, roofY, 0, roofBottom);
    edge.addColorStop(0, '#101c2d');
    edge.addColorStop(0.45, '#0a1525');
    edge.addColorStop(1, '#040a14');
    ctx.strokeStyle = 'rgba(128,157,195,.18)';
    ctx.lineWidth = 1.1;
    ctx.beginPath();
    ctx.moveTo(0, H * 0.183);
    ctx.quadraticCurveTo(W * 0.22, H * 0.225, W * 0.44, H * 0.212);
    ctx.quadraticCurveTo(W * 0.7, H * 0.198, W, H * 0.232);
    ctx.stroke();

    // trusses
    ctx.strokeStyle = 'rgba(111,141,181,.11)';
    ctx.lineWidth = 0.8;
    for (let i = 0; i < 12; i++) {
      const x = (i / 11) * W;
      const y = H * 0.088 + Math.sin(i * 1.3) * H * 0.012;
      ctx.beginPath();
      ctx.moveTo(x, 0);
      ctx.lineTo(x, H * 0.175 + i % 3 * 7);
      ctx.stroke();
    }
    ctx.strokeStyle = 'rgba(123,153,191,.08)';
    for (let i = 0; i < 8; i++) {
      const y = H * 0.04 + i * H * 0.021;
      ctx.beginPath();
      ctx.moveTo(0, y);
      ctx.lineTo(W, y - H * 0.012);
      ctx.stroke();
    }
    ctx.fillStyle = edge;
    ctx.beginPath();
    ctx.moveTo(0, H * 0.16);
    ctx.quadraticCurveTo(W * 0.25, H * 0.19, W * 0.5, H * 0.182);
    ctx.quadraticCurveTo(W * 0.76, H * 0.174, W, H * 0.204);
    ctx.lineTo(W, H * 0.225);
    ctx.quadraticCurveTo(W * 0.76, H * 0.198, W * 0.5, H * 0.207);
    ctx.quadraticCurveTo(W * 0.25, H * 0.215, 0, H * 0.185);
    ctx.closePath();
    ctx.fill();
  }

  drawFloodlights(ctx) {
    const W = this.W, H = this.H;
    const towers = [
      { x: W * 0.075, h: H * 0.085, scale: 1.05 },
      { x: W * 0.925, h: H * 0.075, scale: 1.0 },
      { x: W * 0.52, h: H * 0.07, scale: 0.74, faint: true }
    ];
    for (const tw of towers) {
      const topY = tw.h;
      const bankY = H * 0.16;
      const bankW = 58 * tw.scale * this.u / 0.9;
      const bankH = 25 * tw.scale * this.u / 0.9;
      // mast
      ctx.strokeStyle = 'rgba(126,150,183,.24)';
      ctx.lineWidth = 1.3 * tw.scale;
      ctx.beginPath(); ctx.moveTo(tw.x - 7, bankY); ctx.lineTo(tw.x - 2, topY); ctx.stroke();
      ctx.beginPath(); ctx.moveTo(tw.x + 7, bankY); ctx.lineTo(tw.x + 2, topY); ctx.stroke();
      for (let i = 0; i < 6; i++) {
        const yy = lerp(bankY, topY, i / 6);
        const spread = lerp(7, 2, i / 6);
        ctx.beginPath(); ctx.moveTo(tw.x - spread, yy); ctx.lineTo(tw.x + spread, yy); ctx.stroke();
      }
      // light bank
      const bx = tw.x - bankW / 2, by = bankY - bankH;
      ctx.save();
      ctx.globalAlpha = tw.faint ? 0.56 : 0.9;
      ctx.fillStyle = '#111b2a';
      ctx.strokeStyle = 'rgba(190,208,232,.27)';
      ctx.lineWidth = 1;
      ctx.beginPath();
      ctx.roundRect ? ctx.roundRect(bx, by, bankW, bankH, 2) : ctx.rect(bx, by, bankW, bankH);
      ctx.fill(); ctx.stroke();
      for (let row = 0; row < 2; row++) {
        for (let col = 0; col < 5; col++) {
          const lx = bx + 7 + col * (bankW - 14) / 4;
          const ly = by + 7 + row * 10;
          const lg = ctx.createRadialGradient(lx, ly, 0, lx, ly, 5.5);
          lg.addColorStop(0, 'rgba(255,252,226,1)');
          lg.addColorStop(0.3, 'rgba(255,225,166,.72)');
          lg.addColorStop(1, 'rgba(255,205,120,0)');
          ctx.fillStyle = lg;
          ctx.beginPath(); ctx.arc(lx, ly, 5.5, 0, TAU); ctx.fill();
          ctx.fillStyle = '#fff9de';
          ctx.beginPath(); ctx.arc(lx, ly, 1.35, 0, TAU); ctx.fill();
        }
      }
      ctx.restore();

      // beams of light
      ctx.save();
      ctx.globalCompositeOperation = 'screen';
      const beamAlpha = tw.faint ? 0.024 : 0.046;
      const beam = ctx.createLinearGradient(tw.x, bankY, tw.x + (W * 0.5 - tw.x) * 0.34, H * 0.63);
      beam.addColorStop(0, `rgba(255,247,215,${beamAlpha})`);
      beam.addColorStop(0.5, `rgba(255,225,165,${beamAlpha * 0.35})`);
      beam.addColorStop(1, 'rgba(255,220,160,0)');
      ctx.fillStyle = beam;
      ctx.beginPath();
      ctx.moveTo(bx, by + bankH);
      ctx.lineTo(bx + bankW, by + bankH);
      ctx.lineTo(tw.x + bankW * 2.4, H * 0.69);
      ctx.lineTo(tw.x - bankW * 2.4, H * 0.69);
      ctx.closePath();
      ctx.fill();
      ctx.restore();
    }
  }

  drawCrowd(ctx) {
    const W = this.W, H = this.H;
    if (!this.crowd) return;
    const top = H * 0.245;
    const bottom = H * 0.53;
    const height = bottom - top;
    const cw = this.crowdW * (W / this.W);
    const offset = -((this.camX * 2.1) % cw + cw) % cw;
    const grad = ctx.createLinearGradient(0, top, 0, bottom);
    grad.addColorStop(0, 'rgba(8,16,30,.76)');
    grad.addColorStop(0.4, 'rgba(9,17,31,.38)');
    grad.addColorStop(1, 'rgba(3,8,17,.82)');
    ctx.save();
    ctx.beginPath();
    ctx.moveTo(0, top + H * 0.012);
    ctx.quadraticCurveTo(W * 0.22, top - H * 0.01, W * 0.46, top + H * 0.004);
    ctx.quadraticCurveTo(W * 0.72, top + H * 0.016, W, top - H * 0.006);
    ctx.lineTo(W, bottom + H * 0.012);
    ctx.lineTo(0, bottom + H * 0.022);
    ctx.closePath();
    ctx.clip();
    ctx.globalAlpha = 0.9;
    for (let i = -1; i < 3; i++) {
      ctx.drawImage(this.crowd, offset + i * cw, top, cw, height);
    }
    ctx.globalAlpha = 1;
    ctx.fillStyle = grad;
    ctx.fillRect(0, top, W, height);
    ctx.restore();

    // tier ledges and stair aisles
    ctx.save();
    for (let row = 0; row < 7; row++) {
      const y = top + (row / 7) * height;
      ctx.strokeStyle = `rgba(131,151,177,${0.035 + row * 0.004})`;
      ctx.lineWidth = 0.8;
      ctx.beginPath();
      ctx.moveTo(0, y + 7);
      ctx.quadraticCurveTo(W * 0.5, y + 1, W, y + 7);
      ctx.stroke();
    }
    for (let i = 1; i < 12; i++) {
      const x = (i / 12) * W;
      ctx.strokeStyle = 'rgba(2,6,14,.18)';
      ctx.lineWidth = 3.5;
      ctx.beginPath();
      ctx.moveTo(x, top + 4);
      ctx.lineTo(x, bottom);
      ctx.stroke();
    }
    // dark rail at the bottom of the stands
    ctx.fillStyle = 'rgba(3,8,17,.72)';
    ctx.fillRect(0, bottom - H * 0.008, W, H * 0.02);
    ctx.strokeStyle = 'rgba(178,198,220,.12)';
    ctx.lineWidth = 1;
    ctx.beginPath(); ctx.moveTo(0, bottom - H * 0.006); ctx.lineTo(W, bottom - H * 0.002); ctx.stroke();
    ctx.restore();

    // phone flashes
    ctx.save();
    ctx.globalCompositeOperation = 'screen';
    for (const f of this.flashes) {
      if (f.life > 0) {
        const a = f.life / 0.26;
        const g = ctx.createRadialGradient(f.x, f.y, 0, f.x, f.y, 11);
        g.addColorStop(0, `rgba(255,250,226,${0.9 * a})`);
        g.addColorStop(0.25, `rgba(255,240,195,${0.45 * a})`);
        g.addColorStop(1, 'rgba(255,230,180,0)');
        ctx.fillStyle = g;
        ctx.beginPath(); ctx.arc(f.x, f.y, 11, 0, TAU); ctx.fill();
      }
    }
    ctx.restore();
  }

  drawLedRibbon(ctx, opts = {}) {
    const W = this.W, H = this.H;
    const y = H * 0.528;
    const h = H * 0.022;
    ctx.fillStyle = '#030810';
    ctx.fillRect(0, y, W, h);
    ctx.strokeStyle = 'rgba(255,255,255,.09)';
    ctx.lineWidth = 1;
    ctx.beginPath(); ctx.moveTo(0, y); ctx.lineTo(W, y); ctx.stroke();
    ctx.beginPath(); ctx.moveTo(0, y + h); ctx.lineTo(W, y + h); ctx.stroke();

    const msg = opts.ribbon || 'OLYMPIA 2026  •  NIGHT SESSION  •  100M FINAL  •  CHASE THE GOLD  •  ';
    const font = `600 ${Math.round(h * 0.48)}px "Barlow Condensed", sans-serif`;
    ctx.font = font;
    const textW = ctx.measureText(msg).width;
    const offset = -((this.t * 28) % textW);
    ctx.save();
    ctx.beginPath(); ctx.rect(0, y, W, h); ctx.clip();
    ctx.textBaseline = 'middle';
    ctx.fillStyle = 'rgba(247,201,80,.9)';
    ctx.shadowColor = 'rgba(247,201,80,.6)';
    ctx.shadowBlur = 8;
    for (let x = offset; x < W + textW; x += textW) {
      ctx.fillText(msg, x, y + h * 0.54);
    }
    ctx.shadowBlur = 0;
    // panel seams
    ctx.fillStyle = 'rgba(0,0,0,.45)';
    for (let x = 80; x < W; x += 150) ctx.fillRect(x, y, 1, h);
    ctx.restore();
  }

  drawJumbotron(ctx, opts = {}) {
    const W = this.W, H = this.H;
    const mode = opts.mode || this.mode;
    if (mode === 'menu') {
      const bw = Math.min(W * 0.18, 255);
      const bh = bw * 0.57;
      const x = W * 0.73 - bw / 2;
      const y = H * 0.12;
      this.drawBoardBox(ctx, x, y, bw, bh, 'OLYMPIA', '26', 'NIGHT SESSION', '20:26');
      return;
    }
    if (mode === 'ceremony') {
      const bw = Math.min(W * 0.2, 280);
      const bh = bw * 0.55;
      this.drawBoardBox(ctx, W * 0.71 - bw / 2, H * 0.115, bw, bh, 'OLYMPIA', '26', 'THE PODIUM', 'GOLD');
      return;
    }
    const bw = Math.min(W * 0.2, 270);
    const bh = bw * 0.52;
    this.drawBoardBox(
      ctx, W * 0.74 - bw / 2, H * 0.13, bw, bh,
      opts.boardTop || 'OLYMPIA', opts.boardBig || '100M', opts.boardSub || 'FINAL', opts.boardValue || '0.00'
    );
  }

  drawBoardBox(ctx, x, y, w, h, top, big, sub, value) {
    ctx.save();
    // support cables
    ctx.strokeStyle = 'rgba(120,143,172,.24)';
    ctx.lineWidth = 1;
    ctx.beginPath(); ctx.moveTo(x + w * 0.18, y); ctx.lineTo(x + w * 0.13, 0); ctx.stroke();
    ctx.beginPath(); ctx.moveTo(x + w * 0.82, y); ctx.lineTo(x + w * 0.87, 0); ctx.stroke();
    // frame
    ctx.fillStyle = '#050a12';
    ctx.strokeStyle = 'rgba(150,175,205,.3)';
    ctx.lineWidth = 1.3;
    ctx.beginPath();
    if (ctx.roundRect) ctx.roundRect(x, y, w, h, 3); else ctx.rect(x, y, w, h);
    ctx.fill(); ctx.stroke();
    // screen
    const pad = Math.max(4, w * 0.025);
    const sx = x + pad, sy = y + pad, sw = w - pad * 2, sh = h - pad * 2;
    const bg = ctx.createLinearGradient(sx, sy, sx, sy + sh);
    bg.addColorStop(0, '#102f3d');
    bg.addColorStop(0.5, '#071b2b');
    bg.addColorStop(1, '#030c16');
    ctx.fillStyle = bg;
    ctx.fillRect(sx, sy, sw, sh);
    ctx.globalAlpha = 0.18;
    ctx.fillStyle = '#65e3ff';
    for (let yy = sy; yy < sy + sh; yy += 3) ctx.fillRect(sx, yy, sw, 0.5);
    ctx.globalAlpha = 1;
    // scan glow
    const glow = ctx.createLinearGradient(sx, sy, sx, sy + sh);
    glow.addColorStop(0, 'rgba(83,205,255,.1)');
    glow.addColorStop(1, 'rgba(15,82,130,.02)');
    ctx.fillStyle = glow;
    ctx.fillRect(sx, sy, sw, sh);

    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillStyle = 'rgba(247,201,80,.9)';
    ctx.font = `700 ${Math.max(7, w * 0.042)}px "Barlow Condensed", sans-serif`;
    ctx.fillText(top, x + w / 2, sy + sh * 0.14);
    ctx.fillStyle = '#f3ead3';
    ctx.font = `800 ${Math.max(22, w * 0.24)}px "Barlow Condensed", sans-serif`;
    ctx.fillText(big, x + w / 2, sy + sh * 0.43);
    ctx.fillStyle = 'rgba(144,229,255,.9)';
    ctx.font = `600 ${Math.max(7, w * 0.052)}px "Barlow Condensed", sans-serif`;
    ctx.fillText(sub, x + w / 2, sy + sh * 0.68);
    ctx.fillStyle = '#f7c950';
    ctx.font = `600 ${Math.max(9, w * 0.075)}px "Barlow Condensed", sans-serif`;
    ctx.fillText(value, x + w / 2, sy + sh * 0.87);
    // screen glare
    ctx.globalAlpha = 0.08;
    ctx.fillStyle = '#ffffff';
    ctx.beginPath();
    ctx.moveTo(sx, sy); ctx.lineTo(sx + sw * 0.72, sy); ctx.lineTo(sx, sy + sh * 0.6); ctx.closePath(); ctx.fill();
    ctx.restore();
  }

  /* ------------------------------------------------------------------ */
  /*  GROUND                                                             */
  /* ------------------------------------------------------------------ */
  drawGround(ctx, opts = {}) {
    const W = this.W, H = this.H;
    const mode = opts.mode || this.mode;
    const L = this.getLayout(mode);

    // infield / grass behind the track
    const grassTop = H * 0.545;
    const grassBottom = L.top + 2;
    const grass = ctx.createLinearGradient(0, grassTop, 0, grassBottom);
    grass.addColorStop(0, '#061a17');
    grass.addColorStop(0.55, '#0a2c24');
    grass.addColorStop(1, '#0d3528');
    ctx.fillStyle = grass;
    ctx.fillRect(0, grassTop, W, Math.max(0, grassBottom - grassTop));
    // mowing stripes
    ctx.save();
    ctx.beginPath(); ctx.rect(0, grassTop, W, Math.max(0, grassBottom - grassTop)); ctx.clip();
    const stripeW = Math.max(50, W * 0.075);
    for (let i = -2; i < W / stripeW + 2; i++) {
      if (i % 2 === 0) {
        ctx.fillStyle = 'rgba(74,158,109,.045)';
        ctx.fillRect(i * stripeW + (this.camX * 3) % (stripeW * 2), grassTop, stripeW, grassBottom - grassTop);
      }
    }
    // little mow arrows
    ctx.globalAlpha = 0.05;
    ctx.strokeStyle = '#b8ffd9';
    ctx.lineWidth = 1;
    for (let x = -100; x < W + 100; x += 170) {
      const y = grassTop + (grassBottom - grassTop) * 0.55;
      ctx.beginPath(); ctx.moveTo(x, y); ctx.lineTo(x + 60, y); ctx.stroke();
    }
    ctx.restore();

    // banner boards at the back of the track
    this.drawAdBoards(ctx, mode, L);

    if (mode === 'longjump') {
      this.drawRunway(ctx, L, 'longjump');
      return;
    }
    if (mode === 'javelin') {
      this.drawRunway(ctx, L, 'javelin');
      this.drawJavelinField(ctx, L);
      return;
    }
    this.drawSprintTrack(ctx, L, mode);
  }

  drawAdBoards(ctx, mode, L) {
    const W = this.W;
    const y = H_(this.H, 0.545);
    const h = Math.max(18, this.H * 0.027);
    const labels = ['OLYMPIA', 'GOLD SERIES', 'TRACK & FIELD', 'PARIS 26', 'NIGHT SESSION', 'OLYMPIA'];
    const panelW = 155 * this.u;
    const startWorld = Math.floor((this.camX - 20) / 20) * 20;
    for (let xw = startWorld; xw < this.camX + (W / this.meter) + 40; xw += 20) {
      const idx = Math.abs(Math.round(xw / 20)) % labels.length;
      const x = this.sx(xw);
      const yTop = y - h;
      ctx.save();
      ctx.globalAlpha = 0.9;
      const g = ctx.createLinearGradient(x, yTop, x, yTop + h);
      g.addColorStop(0, 'rgba(12,23,40,.92)');
      g.addColorStop(1, 'rgba(4,9,17,.97)');
      ctx.fillStyle = g;
      ctx.fillRect(x, yTop, panelW, h);
      ctx.strokeStyle = 'rgba(118,153,190,.22)';
      ctx.lineWidth = 0.7;
      ctx.strokeRect(x, yTop, panelW, h);
      ctx.fillStyle = idx % 3 === 0 ? 'rgba(247,201,80,.86)' : 'rgba(239,244,250,.72)';
      ctx.font = `700 ${Math.max(7, h * 0.34)}px "Barlow Condensed", sans-serif`;
      ctx.textAlign = 'center';
      ctx.textBaseline = 'middle';
      ctx.fillText(labels[idx], x + panelW / 2, yTop + h * 0.53);
      ctx.fillStyle = 'rgba(247,201,80,.55)';
      ctx.fillRect(x, yTop + h - 2, panelW, 1.2);
      ctx.restore();
    }
  }

  drawSprintTrack(ctx, L, mode) {
    const W = this.W, H = this.H;
    const top = L.top, bottom = L.bottom;
    const base = ctx.createLinearGradient(0, top, 0, bottom);
    base.addColorStop(0, '#4b1e1d');
    base.addColorStop(0.2, '#6e2922');
    base.addColorStop(0.65, '#8b3427');
    base.addColorStop(1, '#66241e');
    ctx.fillStyle = base;
    ctx.fillRect(0, top, W, bottom - top);

    const playerLane = this.playerLane ?? 3;
    for (let i = 0; i < L.laneCount; i++) {
      const y = top + i * L.laneH;
      if (i === playerLane && (mode === 'sprint')) {
        ctx.fillStyle = 'rgba(247,201,80,.045)';
        ctx.fillRect(0, y, W, L.laneH);
      } else if (i % 2 === 0) {
        ctx.fillStyle = 'rgba(255,150,110,.028)';
        ctx.fillRect(0, y, W, L.laneH);
      }
      // lane line
      ctx.strokeStyle = 'rgba(240,232,214,.6)';
      ctx.lineWidth = Math.max(0.7, 1.2 * this.u);
      ctx.beginPath(); ctx.moveTo(0, y); ctx.lineTo(W, y); ctx.stroke();
      // inner shadow on the line
      ctx.strokeStyle = 'rgba(60,10,8,.35)';
      ctx.lineWidth = 1;
      ctx.beginPath(); ctx.moveTo(0, y + 1.6); ctx.lineTo(W, y + 1.6); ctx.stroke();
    }
    // outer edge
    ctx.strokeStyle = 'rgba(240,232,214,.5)';
    ctx.lineWidth = 1.4;
    ctx.beginPath(); ctx.moveTo(0, bottom); ctx.lineTo(W, bottom); ctx.stroke();

    // noise + light pools
    ctx.save();
    ctx.globalAlpha = 0.32;
    const pattern = ctx.createPattern(this.trackNoise, 'repeat');
    ctx.fillStyle = pattern;
    ctx.fillRect(0, top, W, bottom - top);
    ctx.restore();

    ctx.save();
    ctx.globalCompositeOperation = 'screen';
    for (let i = 0; i < 4; i++) {
      const x = W * (0.1 + i * 0.28) + Math.sin(this.t * 0.1 + i) * 25;
      const g = ctx.createRadialGradient(x, top + (bottom - top) * 0.55, 0, x, top + (bottom - top) * 0.55, W * 0.22);
      g.addColorStop(0, 'rgba(255,213,157,.035)');
      g.addColorStop(1, 'rgba(255,213,157,0)');
      ctx.fillStyle = g;
      ctx.fillRect(0, top, W, bottom - top);
    }
    ctx.restore();

    // world markings
    this.drawTrackMarks(ctx, L, mode);

    // start blocks
    for (let i = 0; i < L.laneCount; i++) {
      const x = this.sx(-1.5);
      const y = this.groundY(i, mode) + 1;
      const w = Math.max(14, this.meter * 1.2);
      ctx.save();
      ctx.translate(x, y);
      ctx.fillStyle = 'rgba(5,9,16,.92)';
      ctx.strokeStyle = 'rgba(247,201,80,.55)';
      ctx.lineWidth = 0.9;
      ctx.beginPath();
      ctx.moveTo(-w * 0.2, 0); ctx.lineTo(w * 0.62, -8); ctx.lineTo(w * 0.8, -2); ctx.lineTo(0, 5);
      ctx.closePath(); ctx.fill(); ctx.stroke();
      ctx.restore();
    }
  }

  drawTrackMarks(ctx, L, mode) {
    const top = L.top, bottom = L.bottom;
    const W = this.W;
    const worldStart = Math.floor((this.camX - W / this.meter) / 5) * 5;
    const worldEnd = this.camX + W / this.meter + 5;
    for (let xw = worldStart; xw <= worldEnd; xw += 5) {
      if (xw < -10 || xw > 120) continue;
      const x = this.sx(xw);
      const major = xw % 10 === 0;
      if (!major && this.meter < 18) continue;
      ctx.strokeStyle = major ? 'rgba(246,239,222,.28)' : 'rgba(246,239,222,.12)';
      ctx.lineWidth = major ? 1.1 : 0.6;
      ctx.beginPath();
      ctx.moveTo(x, top);
      ctx.lineTo(x, bottom);
      ctx.stroke();
      if (major && xw > 0 && xw < 100) {
        ctx.save();
        ctx.globalAlpha = 0.44;
        ctx.fillStyle = '#f5eddc';
        ctx.font = `600 ${Math.max(7, this.H * 0.011)}px "Barlow Condensed", sans-serif`;
        ctx.textAlign = 'center';
        ctx.textBaseline = 'top';
        ctx.fillText(`${xw}`, x, top + 5);
        ctx.restore();
      }
    }

    // start & finish
    const startX = this.sx(0);
    ctx.strokeStyle = 'rgba(255,255,255,.72)';
    ctx.lineWidth = 2;
    ctx.beginPath(); ctx.moveTo(startX, top); ctx.lineTo(startX, bottom); ctx.stroke();

    const finishX = this.sx(100);
    if (finishX > -50 && finishX < W + 50) {
      const cell = (bottom - top) / 10;
      for (let i = 0; i < 10; i++) {
        for (let c = 0; c < 2; c++) {
          ctx.fillStyle = (i + c) % 2 === 0 ? 'rgba(245,240,226,.82)' : 'rgba(14,20,30,.8)';
          ctx.fillRect(finishX - cell * 0.5 + c * cell * 0.5, top + i * cell, cell * 0.5, cell);
        }
      }
      ctx.save();
      ctx.fillStyle = 'rgba(247,201,80,.94)';
      ctx.font = `700 ${Math.max(10, this.H * 0.018)}px "Barlow Condensed", sans-serif`;
      ctx.textAlign = 'center';
      ctx.shadowColor = 'rgba(247,201,80,.65)';
      ctx.shadowBlur = 12;
      ctx.fillText('FINISH', finishX, top + 18);
      ctx.restore();
    }
  }

  drawRunway(ctx, L, type) {
    const W = this.W;
    const top = L.top - L.laneH * 0.1;
    const bottom = L.bottom;
    const base = ctx.createLinearGradient(0, top, 0, bottom);
    base.addColorStop(0, '#4d1c1b');
    base.addColorStop(0.5, '#832f24');
    base.addColorStop(1, '#5f211b');
    ctx.fillStyle = base;
    ctx.fillRect(0, top, W, bottom - top);

    // runway lane lines
    for (let i = 0; i <= L.laneCount; i++) {
      const y = top + (i / L.laneCount) * (bottom - top);
      ctx.strokeStyle = 'rgba(244,238,225,.6)';
      ctx.lineWidth = 1.1;
      ctx.beginPath(); ctx.moveTo(0, y); ctx.lineTo(W, y); ctx.stroke();
    }
    ctx.save();
    ctx.globalAlpha = 0.24;
    ctx.fillStyle = ctx.createPattern(this.trackNoise, 'repeat');
    ctx.fillRect(0, top, W, bottom - top);
    ctx.restore();

    // markings / distances
    const worldStart = Math.floor((this.camX - W / this.meter) / 5) * 5;
    const worldEnd = this.camX + W / this.meter + 8;
    for (let xw = worldStart; xw <= worldEnd; xw += 5) {
      if (xw < -5) continue;
      if (xw > 55) continue;
      const x = this.sx(xw);
      ctx.strokeStyle = xw % 10 === 0 ? 'rgba(246,239,222,.3)' : 'rgba(246,239,222,.14)';
      ctx.lineWidth = xw % 10 === 0 ? 1.1 : 0.65;
      ctx.beginPath(); ctx.moveTo(x, top); ctx.lineTo(x, bottom); ctx.stroke();
      if (xw % 10 === 0 && xw <= 40) {
        ctx.save();
        ctx.globalAlpha = 0.58;
        ctx.fillStyle = '#f7efdd';
        ctx.font = `600 ${Math.max(7, this.H * 0.011)}px "Barlow Condensed", sans-serif`;
        ctx.textAlign = 'center'; ctx.textBaseline = 'top';
        ctx.fillText(`${xw}M`, x, top + 4);
        ctx.restore();
      }
    }

    if (type === 'longjump') {
      this.drawLongJumpPit(ctx, L);
    } else {
      this.drawJavelinRunway(ctx, L);
    }
  }

  drawLongJumpPit(ctx, L) {
    const W = this.W;
    const top = L.top - L.laneH * 0.1;
    const bottom = L.bottom;
    const boardX = this.sx(40);
    const pitEnd = this.sx(49);

    // takeoff zone before the board
    const zoneStart = this.sx(38.2);
    const zoneEnd = this.sx(39.8);
    ctx.save();
    ctx.globalCompositeOperation = 'screen';
    const zg = ctx.createLinearGradient(zoneStart, 0, zoneEnd, 0);
    zg.addColorStop(0, 'rgba(89,255,178,.02)');
    zg.addColorStop(0.35, 'rgba(89,255,178,.2)');
    zg.addColorStop(1, 'rgba(89,255,178,.32)');
    ctx.fillStyle = zg;
    ctx.fillRect(zoneStart, top, zoneEnd - zoneStart, bottom - top);
    ctx.strokeStyle = 'rgba(126,255,198,.65)';
    ctx.lineWidth = 1.2;
    ctx.strokeRect(zoneStart, top, zoneEnd - zoneStart, bottom - top);
    // chevrons
    ctx.strokeStyle = 'rgba(157,255,211,.45)';
    ctx.lineWidth = 2;
    for (let i = 0; i < 4; i++) {
      const x = zoneStart + (zoneEnd - zoneStart) * (0.18 + i * 0.2);
      ctx.beginPath(); ctx.moveTo(x - 5, top + 8); ctx.lineTo(x + 3, (top + bottom) / 2); ctx.lineTo(x - 5, bottom - 8); ctx.stroke();
    }
    ctx.restore();

    // sand pit
    const sand = ctx.createLinearGradient(0, top, 0, bottom);
    sand.addColorStop(0, '#7c6037');
    sand.addColorStop(0.4, '#b18b4e');
    sand.addColorStop(1, '#8f6c3b');
    ctx.fillStyle = sand;
    ctx.beginPath();
    ctx.moveTo(boardX, top);
    ctx.lineTo(pitEnd, top + 3);
    ctx.lineTo(pitEnd, bottom + 2);
    ctx.lineTo(boardX, bottom);
    ctx.closePath();
    ctx.fill();
    // sand speckles
    const r = seeded(402);
    ctx.save();
    ctx.beginPath();
    ctx.moveTo(boardX, top); ctx.lineTo(pitEnd, top + 3); ctx.lineTo(pitEnd, bottom + 2); ctx.lineTo(boardX, bottom); ctx.closePath(); ctx.clip();
    for (let i = 0; i < 340; i++) {
      const x = boardX + r() * (pitEnd - boardX);
      const y = top + r() * (bottom - top);
      ctx.fillStyle = r() > 0.5 ? 'rgba(255,222,157,.2)' : 'rgba(74,46,21,.24)';
      ctx.fillRect(x, y, 1 + r() * 2, 0.8 + r());
    }
    // light shadow at the front lip
    const lip = ctx.createLinearGradient(0, top, 0, bottom);
    lip.addColorStop(0, 'rgba(0,0,0,.18)');
    lip.addColorStop(0.15, 'rgba(0,0,0,0)');
    lip.addColorStop(1, 'rgba(0,0,0,.15)');
    ctx.fillStyle = lip;
    ctx.fillRect(boardX, top, pitEnd - boardX, bottom - top);
    ctx.restore();

    // board
    ctx.save();
    ctx.fillStyle = '#f4efe2';
    ctx.fillRect(boardX - 4 * this.u, top, 8 * this.u, bottom - top);
    ctx.fillStyle = 'rgba(247,201,80,.9)';
    ctx.fillRect(boardX - 1.2 * this.u, top, 2.4 * this.u, bottom - top);
    ctx.shadowColor = 'rgba(247,201,80,.85)';
    ctx.shadowBlur = 18;
    ctx.strokeStyle = 'rgba(255,236,170,.85)';
    ctx.lineWidth = 1.2;
    ctx.beginPath(); ctx.moveTo(boardX, top); ctx.lineTo(boardX, bottom); ctx.stroke();
    ctx.restore();

    // pit edge lines
    ctx.strokeStyle = 'rgba(245,239,226,.55)';
    ctx.lineWidth = 1;
    ctx.strokeRect(boardX, top, pitEnd - boardX, bottom - top);
  }

  drawJavelinRunway(ctx, L) {
    const top = L.top - L.laneH * 0.1;
    const bottom = L.bottom;
    const lineX = this.sx(36);
    // grass beyond the foul line
    ctx.fillStyle = '#0a3327';
    ctx.fillRect(lineX, 0, this.W, this.H);
    // mowing stripes in the sector
    ctx.save();
    ctx.beginPath(); ctx.rect(lineX, this.H * 0.52, this.W, this.H * 0.46); ctx.clip();
    for (let i = -2; i < 10; i++) {
      ctx.fillStyle = i % 2 ? 'rgba(70,152,103,.05)' : 'rgba(10,42,30,.03)';
      ctx.fillRect(lineX + i * 80 + (this.camX * 2) % 160, this.H * 0.52, 80, this.H * 0.46);
    }
    ctx.restore();
    // foul line
    ctx.save();
    ctx.shadowColor = 'rgba(255,90,70,.9)';
    ctx.shadowBlur = 15;
    ctx.strokeStyle = 'rgba(255,99,88,.95)';
    ctx.lineWidth = 3;
    ctx.beginPath(); ctx.moveTo(lineX, top - 8); ctx.lineTo(lineX, bottom + 4); ctx.stroke();
    ctx.restore();
    ctx.fillStyle = 'rgba(255,99,88,.65)';
    ctx.font = `700 ${Math.max(7, this.H * 0.012)}px "Barlow Condensed", sans-serif`;
    ctx.textAlign = 'center';
    ctx.fillText('FOUL LINE', lineX, top - 12);
    // distance arcs on the grass (subtle)
    ctx.save();
    ctx.strokeStyle = 'rgba(219,240,226,.1)';
    ctx.lineWidth = 1;
    for (let m = 40; m <= 90; m += 10) {
      const x = this.sx(m);
      ctx.beginPath();
      ctx.moveTo(x, this.H * 0.60);
      ctx.lineTo(x - 25, this.H * 0.82);
      ctx.stroke();
      ctx.fillStyle = 'rgba(219,240,226,.18)';
      ctx.font = `500 ${Math.max(6, this.H * 0.009)}px "Barlow Condensed", sans-serif`;
      ctx.fillText(`${m}M`, x - 14, this.H * 0.815);
    }
    ctx.restore();
  }

  drawJavelinField(ctx, L) {
    // javelin throw sector edge, behind the runner
    const W = this.W, H = this.H;
    ctx.save();
    ctx.globalAlpha = 0.22;
    ctx.strokeStyle = '#d8f3e5';
    ctx.lineWidth = 1.2;
    const x = this.sx(36);
    ctx.beginPath();
    ctx.moveTo(x, H * 0.58);
    ctx.lineTo(x + W * 0.4, H * 0.56);
    ctx.stroke();
    ctx.beginPath();
    ctx.moveTo(x, H * 0.58);
    ctx.lineTo(x + W * 0.36, H * 0.84);
    ctx.stroke();
    ctx.restore();
  }

  /* ------------------------------------------------------------------ */
  /*  FOREGROUND                                                         */
  /* ------------------------------------------------------------------ */
  drawAtmosphere(ctx) {
    const W = this.W, H = this.H;
    // Warm haze around the track.
    ctx.save();
    ctx.globalCompositeOperation = 'screen';
    const haze = ctx.createRadialGradient(W * 0.5, H * 0.62, 0, W * 0.5, H * 0.62, W * 0.6);
    haze.addColorStop(0, 'rgba(255,175,110,.045)');
    haze.addColorStop(0.5, 'rgba(255,148,88,.018)');
    haze.addColorStop(1, 'rgba(255,130,80,0)');
    ctx.fillStyle = haze;
    ctx.fillRect(0, 0, W, H);
    ctx.restore();

    // Motes in the floodlight.
    ctx.save();
    ctx.globalCompositeOperation = 'screen';
    for (const m of this.motes) {
      const a = m.a * (0.55 + 0.45 * Math.sin(this.t * 0.8 + m.ph));
      ctx.fillStyle = `rgba(255,225,177,${a})`;
      ctx.beginPath();
      ctx.arc(m.x, m.y + Math.sin(this.t * 0.5 + m.ph) * 4, m.s, 0, TAU);
      ctx.fill();
    }
    ctx.restore();

    // Foreground rail / blurred track edge.
    const bottom = this.H * 0.985;
    const fg = ctx.createLinearGradient(0, bottom - 22, 0, this.H);
    fg.addColorStop(0, 'rgba(3,7,14,0)');
    fg.addColorStop(0.5, 'rgba(3,7,14,.46)');
    fg.addColorStop(1, 'rgba(2,5,11,.92)');
    ctx.fillStyle = fg;
    ctx.fillRect(0, bottom - 22, W, this.H - bottom + 22);
  }

  drawSpotlight(ctx, x, y, radius, strength = 1) {
    ctx.save();
    ctx.globalCompositeOperation = 'screen';
    const g = ctx.createRadialGradient(x, y, 0, x, y, radius);
    g.addColorStop(0, `rgba(255,223,159,${0.19 * strength})`);
    g.addColorStop(0.25, `rgba(255,201,114,${0.095 * strength})`);
    g.addColorStop(1, 'rgba(255,190,100,0)');
    ctx.fillStyle = g;
    ctx.beginPath(); ctx.arc(x, y, radius, 0, TAU); ctx.fill();
    ctx.restore();
  }

  drawMenuTouches(ctx) {
    // Sweeping ring of light behind the hero.
    const W = this.W, H = this.H;
    const x = W * 0.625, y = H * 0.47;
    ctx.save();
    ctx.globalCompositeOperation = 'screen';
    const g = ctx.createRadialGradient(x, y, 0, x, y, H * 0.43);
    g.addColorStop(0, 'rgba(255,205,105,.11)');
    g.addColorStop(0.33, 'rgba(255,185,85,.04)');
    g.addColorStop(1, 'rgba(255,170,70,0)');
    ctx.fillStyle = g;
    ctx.fillRect(0, 0, W, H);
    // orbital lines
    ctx.strokeStyle = 'rgba(247,201,80,.09)';
    ctx.lineWidth = 1;
    ctx.beginPath(); ctx.ellipse(x, H * 0.77, H * 0.28, H * 0.035, 0, 0, TAU); ctx.stroke();
    ctx.restore();
  }

  drawCeremonyPodium(ctx, standings, playerId, t) {
    const W = this.W, H = this.H;
    const baseY = H * 0.875;
    const cx = W * 0.46;
    const totalW = Math.min(W * 0.48, 650 * this.u);
    const stepW = totalW / 3;
    const stepH = [H * 0.085, H * 0.13, H * 0.10];
    const order = [1, 0, 2]; // silver, gold, bronze on screen
    const byPlace = [standings[0], standings[1], standings[2]];
    const stepHeights = [H * 0.13, H * 0.09, H * 0.07];

    // glow behind podium
    ctx.save();
    ctx.globalCompositeOperation = 'screen';
    const glow = ctx.createRadialGradient(cx, baseY - H * 0.15, 0, cx, baseY - H * 0.15, W * 0.27);
    glow.addColorStop(0, 'rgba(255,216,130,.12)');
    glow.addColorStop(1, 'rgba(255,190,90,0)');
    ctx.fillStyle = glow;
    ctx.fillRect(0, 0, W, H);
    ctx.restore();

    // steps
    const stepOrder = [1, 0, 2];
    for (let k = 0; k < 3; k++) {
      const place = stepOrder[k]; // 1 silver left, 0 gold middle, 2 bronze right
      const sw = stepW * 0.94;
      const sh = stepHeights[place];
      const x = cx - totalW / 2 + k * stepW + (stepW - sw) / 2;
      const y = baseY - sh;
      const grad = ctx.createLinearGradient(x, y, x, baseY);
      if (place === 0) {
        grad.addColorStop(0, '#d8b452'); grad.addColorStop(0.25, '#7e6427'); grad.addColorStop(1, '#2d2515');
      } else if (place === 1) {
        grad.addColorStop(0, '#9aa5b4'); grad.addColorStop(0.3, '#566172'); grad.addColorStop(1, '#232a34');
      } else {
        grad.addColorStop(0, '#b8774d'); grad.addColorStop(0.3, '#6b3e29'); grad.addColorStop(1, '#2e1c15');
      }
      ctx.fillStyle = grad;
      ctx.strokeStyle = 'rgba(255,255,255,.16)';
      ctx.lineWidth = 1;
      ctx.fillRect(x, y, sw, sh);
      ctx.strokeRect(x, y, sw, sh);
      ctx.fillStyle = 'rgba(255,255,255,.11)';
      ctx.fillRect(x + 5, y + 5, sw - 10, 2);
      // number
      ctx.fillStyle = 'rgba(255,255,255,.42)';
      ctx.font = `700 ${H * 0.028}px "Barlow Condensed", sans-serif`;
      ctx.textAlign = 'center';
      ctx.textBaseline = 'middle';
      ctx.fillText(place + 1, x + sw / 2, y + sh * 0.5);
      // athlete
      const athlete = byPlace[place];
      if (athlete) {
        const scale = (place === 0 ? 1.55 : 1.38) * this.u;
        drawAthlete(ctx, {
          x: x + sw / 2,
          y: y + 1,
          scale,
          pose: place === 0 ? 'victory' : 'idle',
          phase: t * 0.9 + place,
          kit: athlete.kit,
          flip: false,
          shadow: 0.7,
          glow: place === 0 ? 0.2 : 0
        });
      }
    }
    // front lip
    ctx.fillStyle = 'rgba(2,6,12,.5)';
    ctx.fillRect(cx - totalW / 2, baseY, totalW, H - baseY);
    // gold confetti flecks on steps
    ctx.save();
    ctx.globalCompositeOperation = 'screen';
    for (let i = 0; i < 20; i++) {
      const x = cx - totalW / 2 + ((i * 193 + 37) % totalW);
      const y = baseY - ((i * 53) % (H * 0.17));
      ctx.fillStyle = `rgba(247,201,80,${0.1 + (i % 5) * 0.04})`;
      ctx.fillRect(x, y, 2, 5);
    }
    ctx.restore();
  }

  addFirework(x, y) {
    this.fireworks.push({ x, y, life: 0, dur: 2.2 + rand() * 1.2, seed: Math.random() * 999 });
  }

  drawFireworks(ctx) {
    const W = this.W, H = this.H;
    ctx.save();
    ctx.globalCompositeOperation = 'screen';
    for (const fw of this.fireworks) {
      const p = fw.life / fw.dur;
      if (p > 1) continue;
      const r = seeded(Math.floor(fw.seed));
      const rad = (0.05 + p * 0.33) * Math.min(W, H);
      const alpha = Math.max(0, 1 - p);
      for (let i = 0; i < 18; i++) {
        const a = r() * TAU;
        const d = rad * (0.65 + r() * 0.35);
        const x = fw.x + Math.cos(a) * d;
        const y = fw.y + Math.sin(a) * d + p * p * H * 0.08;
        ctx.fillStyle = i % 3 === 0
          ? `rgba(247,201,80,${alpha * 0.8})`
          : `rgba(126,228,255,${alpha * 0.55})`;
        ctx.beginPath(); ctx.arc(x, y, 1.2 + r() * 1.6, 0, TAU); ctx.fill();
      }
      const core = ctx.createRadialGradient(fw.x, fw.y, 0, fw.x, fw.y, rad * 0.4);
      core.addColorStop(0, `rgba(255,245,200,${alpha * 0.22})`);
      core.addColorStop(1, 'rgba(255,220,120,0)');
      ctx.fillStyle = core;
      ctx.beginPath(); ctx.arc(fw.x, fw.y, rad * 0.4, 0, TAU); ctx.fill();
    }
    ctx.restore();
  }
}

function H_(H, v) { return H * v; }

import { clamp, lerp, smoothstep, rand, fmtTime, fmtDist } from './utils.js';
import { drawAthlete } from './athlete.js';

const AI_LANES = [0, 1, 2, 4, 5, 6, 7];

class BaseEvent {
  constructor(game, id, options = {}) {
    this.game = game;
    this.id = id;
    this.practice = !!options.practice;
    this.world = game.world;
    this.state = 'ready';
    this.ended = false;
    this.camX = -10;
    this.meter = 45;
    this.anchor = 0.4;
    this.phase = 0;
    this.field = game.getField(id);
    this.particles = [];
    this.jumbo = { top: 'OLYMPIA', big: '100M', sub: 'FINAL', value: '0.00' };
  }
  get W() { return this.game.W; }
  get H() { return this.game.H; }
  get ctx() { return this.game.ctx; }
  setCamera(meter, anchor) {
    this.meter = meter;
    this.anchor = anchor;
  }
  updateCamera(dt, targetX, extra = 0) {
    const meter = clamp(this.W / 24, 16, 54);
    const anchor = this.W < 720 ? 0.42 : 0.4;
    this.meter = lerp(this.meter, meter, 1 - Math.exp(-2.4 * dt));
    this.anchor = lerp(this.anchor, anchor, 1 - Math.exp(-2 * dt));
    const targetCam = targetX - (this.W * this.anchor) / this.meter + extra;
    this.camX = lerp(this.camX, targetCam, 1 - Math.exp(-3.2 * dt));
    this.world.setCamera(this.camX, this.meter, this.anchor, this.id);
  }
  paint(extra = {}) {
    this.game.paintWorld(this.id, {
      jumbo: this.jumbo,
      ribbon: extra.ribbon
    });
  }
  hud(data) {
    this.game.setHUD(data);
  }
  done(mark, meta = {}) {
    if (this.ended) return;
    this.ended = true;
    this.game.completeEvent(this.id, mark, { ...meta, practice: this.practice });
  }
}

/* ================================================================== */
/*  100M SPRINT                                                        */
/* ================================================================== */
export class SprintEvent extends BaseEvent {
  constructor(game, options = {}) {
    super(game, 'sprint', options);
    this.playerLane = 3;
    this.raceTime = 0;
    this.finishDelay = 0;
    this.auto = false;
    this.player = null;
    this.runners = [];
    this.buildRunners();
    this.camX = -(this.W * 0.415) / clamp(this.W / 24, 16, 54);
    this.meter = clamp(this.W / 24, 16, 54);
    this.anchor = 0.415;
    this.jumbo = { top: 'OLYMPIA', big: '100M', sub: 'FINAL', value: '0.00' };
    this.lastPhase = 0;
    this.liveRank = 8;
  }

  buildRunners() {
    const roster = this.game.roster;
    let laneIndex = 0;
    this.runners = roster.map((athlete) => {
      const isPlayer = !!athlete.player;
      const lane = isPlayer ? 3 : AI_LANES[laneIndex++];
      const targetTime = isPlayer ? null : this.field[athlete.id];
      const r = {
        athlete,
        isPlayer,
        lane,
        dist: 0,
        speed: 0,
        phase: rand(0, Math.PI * 2),
        finished: false,
        time: null,
        targetTime,
        targetSpeed: targetTime ? 100 / Math.max(0.1, targetTime - 0.375) : 0
      };
      if (isPlayer) this.player = r;
      return r;
    });
  }

  start() {
    this.state = 'running';
    this.raceTime = 0;
    this.game.sound.setCrowd(0.028);
    this.hudFlash();
  }

  hudFlash() {
    this.game.setHUD({ prompt: { visible: false } });
  }

  tap(side) {
    if (this.state !== 'running' || this.player.finished) return;
    const p = this.player;
    const t = this.raceTime;
    if (t - p.lastTap < 0.055) return;
    if (t - p.lastTap > 0.32) p.speed *= 0.97;
    const valid = side !== p.lastSide;
    if (valid) {
      if (!p.started) {
        p.started = true;
        p.speed += 2.2;
        p.reaction = t;
      }
      p.auto = false;
      const boost = 0.55 * Math.max(0, 1 - p.speed / 13) + 0.08;
      p.speed += boost;
      p.taps++;
      p.lastSide = side;
      p.lastTap = t;
      this.game.sound.step(clamp(p.speed / 12, 0.2, 1));
      this.game.tapFlash(side);
      this.game.spawnParticle({
        x: this.game.W * 0.5 + rand(-60, 60),
        y: this.game.groundY(this.playerLane, 'sprint') - rand(4, 20),
        vx: rand(-30, 10), vy: rand(-20, -5), life: rand(0.2, 0.45),
        size: rand(1, 3), color: 'rgba(255,226,177,.32)', gravity: 8
      });
    } else {
      p.lastTap = t;
      p.speed *= 0.93;
    }
  }

  update(dt) {
    this.phase += dt;
    if (this.state !== 'running') return;
    this.raceTime += dt;

    const p = this.player;
    // Graceful fallback: nobody gets stuck at the start forever.
    if (!p.started && this.raceTime > 3.4) {
      p.started = true;
      p.auto = true;
      p.speed = 5.1;
      p.reaction = this.raceTime;
    }

    // Player physics: taps provide impulse, air / stride drag bleeds it away.
    if (p.started) {
      if (p.auto) p.speed = Math.max(p.speed, 5.1);
      p.speed *= Math.exp(-0.10 * dt);
      p.dist += p.speed * dt;
      p.phase += p.speed * 1.06 * dt;
      if (p.dist >= 100 && !p.finished) {
        p.finished = true;
        p.time = this.raceTime - (p.dist - 100) / Math.max(0.01, p.speed);
        p.dist = 100;
        this.state = 'finished';
        this.game.shake = Math.max(this.game.shake, 5);
        this.game.sound.cheer(1.1);
        this.game.toast('FINISH', 'gold', 900);
      }
    }

    for (const r of this.runners) {
      if (r.isPlayer || r.finished) continue;
      const speed = r.targetSpeed * smoothstep(0, 0.75, this.raceTime);
      r.speed = speed;
      r.dist += speed * dt;
      r.phase += speed * 1.04 * dt;
      if (r.dist >= 100) {
        r.finished = true;
        r.time = this.raceTime - (r.dist - 100) / Math.max(0.01, speed);
        r.dist = 100;
      }
    }

    const allDone = this.runners.every(r => r.finished);
    if (p.finished && (allDone || this.finishDelay > 1.35)) {
      this.finishDelay += dt;
      if (this.finishDelay > 1.35) {
        this.state = 'done';
        this.done(p.time, { placeHint: this.liveRank });
        return;
      }
    }

    this.updateCamera(dt, p.dist, 1.1);
    this.updateLive(dt);
    this.spawnFootDust(dt);
  }

  updateLive(dt) {
    const order = [...this.runners].sort((a, b) => {
      if (a.finished && b.finished) return a.time - b.time;
      return b.dist - a.dist;
    });
    this.liveRank = order.findIndex(r => r.isPlayer) + 1;
    this.game.setMiniBoard(
      order.map(r => ({
        id: r.athlete.id,
        name: r.athlete.name,
        code: r.athlete.code,
        player: r.isPlayer,
        value: r.finished ? fmtTime(r.time) : `${r.dist.toFixed(1)}m`
      })),
      'LIVE ORDER'
    );
    const next = this.player.lastSide === 'left' ? 'D' : 'A';
    const cadence = this.player.started ? clamp((this.player.speed - 4) / 8, 0, 1) : 0;
    this.hud({
      clock: fmtTime(this.raceTime),
      clockUnit: 's',
      clockLabel: 'RACE TIME',
      place: this.player.finished ? String(this.liveRank) : String(this.liveRank),
      meter: this.player.speed,
      meterMax: 13.2,
      meterUnit: 'M/S',
      meterLabel: 'VELOCITY',
      prompt: this.player.finished ? { visible: false } : {
        visible: true,
        key: next,
        title: this.player.started ? 'KEEP THE CADENCE' : 'EXPLODE FROM THE BLOCKS',
        sub: `Alternate ${this.player.lastSide === 'left' ? 'D' : 'A'} / ${next} — ${Math.round(this.player.speed * 10) / 10} m/s`,
        pulse: true
      },
      cadence,
      action: false
    });
  }

  spawnFootDust() {
    const p = this.player;
    if (!p.started || p.speed < 3.5) return;
    const crossed = Math.floor(p.phase / Math.PI);
    if (crossed !== this.lastPhase) {
      this.lastPhase = crossed;
      const x = this.world.sx(p.dist) - 12;
      const y = this.game.groundY(this.playerLane, 'sprint');
      for (let i = 0; i < 2; i++) {
        this.game.spawnParticle({
          x: x + rand(-12, 12), y: y - rand(0, 5),
          vx: rand(-50, -8), vy: rand(-34, -6), life: rand(0.28, 0.6),
          size: rand(1.4, 4.2), color: `rgba(255,214,154,${rand(0.12, 0.27)})`,
          gravity: 30, drag: 0.5
        });
      }
    }
  }

  render(ctx) {
    this.world.playerLane = this.playerLane;
    this.paint();
    const order = [...this.runners].sort((a, b) => a.lane - b.lane);
    for (const r of order) {
      const x = this.world.sx(r.dist);
      if (x < -100 || x > this.W + 130) continue;
      const y = this.game.groundY(r.lane, 'sprint');
      const scale = this.world.laneScale(r.lane, 'sprint') * (r.isPlayer ? 1.03 : 1);
      let pose = 'run';
      if (this.state === 'ready' || this.game.state === 'countdown') pose = 'set';
      if (this.game.state === 'false-start') pose = 'set';
      if (r.finished && r.speed < 1.5) pose = 'idle';
      drawAthlete(ctx, {
        x, y, scale,
        phase: r.phase,
        pose,
        speed: clamp(r.speed / 12, 0, 1),
        kit: r.athlete.kit,
        glow: r.isPlayer ? 0.18 : 0.04,
        shadow: r.isPlayer ? 1.15 : 0.9,
        number: r.isPlayer ? 7 : 7
      });
      if (r.isPlayer && this.state !== 'ready') {
        this.drawPlayerTag(ctx, x, y, scale, r);
      }
    }
    // Motion streaks for top speed.
    if (this.player.speed > 8.5) {
      const p = this.player;
      const x = this.world.sx(p.dist);
      const y = this.game.groundY(this.playerLane, 'sprint');
      ctx.save();
      ctx.globalCompositeOperation = 'screen';
      for (let i = 0; i < 7; i++) {
        const yy = y - 20 - i * 11 - rand(0, 8);
        const len = 28 + rand(0, 55) + p.speed * 2;
        const a = 0.018 + (p.speed - 8.5) * 0.013;
        const grad = ctx.createLinearGradient(x - len, yy, x + 12, yy);
        grad.addColorStop(0, 'rgba(255,236,185,0)');
        grad.addColorStop(0.7, `rgba(255,218,148,${a})`);
        grad.addColorStop(1, 'rgba(255,245,216,0)');
        ctx.strokeStyle = grad;
        ctx.lineWidth = 1 + rand(0, 1.7);
        ctx.beginPath(); ctx.moveTo(x - len, yy); ctx.lineTo(x + 20, yy); ctx.stroke();
      }
      ctx.restore();
    }
    this.drawFinishAtmosphere(ctx);
  }

  drawPlayerTag(ctx, x, y, scale, r) {
    const top = y - 132 * scale;
    ctx.save();
    ctx.globalAlpha = 0.92;
    ctx.fillStyle = 'rgba(4,10,20,.72)';
    ctx.strokeStyle = 'rgba(247,201,80,.38)';
    ctx.lineWidth = 1;
    const text = 'YOU';
    ctx.font = '700 8px "Barlow Condensed", sans-serif';
    const w = ctx.measureText(text).width + 14;
    ctx.beginPath();
    if (ctx.roundRect) ctx.roundRect(x - w / 2, top - 16, w, 13, 2); else ctx.rect(x - w / 2, top - 16, w, 13);
    ctx.fill(); ctx.stroke();
    ctx.fillStyle = '#f7c950';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillText(text, x, top - 9.5);
    ctx.restore();
  }

  drawFinishAtmosphere(ctx) {
    const x = this.world.sx(100);
    if (x < -60 || x > this.W + 60) return;
    const grad = ctx.createRadialGradient(x, this.H * 0.77, 0, x, this.H * 0.77, this.H * 0.27);
    grad.addColorStop(0, 'rgba(247,201,80,.07)');
    grad.addColorStop(1, 'rgba(247,201,80,0)');
    ctx.save();
    ctx.globalCompositeOperation = 'screen';
    ctx.fillStyle = grad;
    ctx.beginPath(); ctx.arc(x, this.H * 0.77, this.H * 0.27, 0, Math.PI * 2); ctx.fill();
    ctx.restore();
  }
}

/* ================================================================== */
/*  LONG JUMP                                                          */
/* ================================================================== */
export class LongJumpEvent extends BaseEvent {
  constructor(game, options = {}) {
    super(game, 'longjump', options);
    this.meter = clamp(this.W / 24, 16, 52);
    this.anchor = 0.37;
    this.camX = -(this.W * 0.37) / this.meter;
    this.x = 0;
    this.runTime = 0;
    this.speed = 0;
    this.phase = rand(0, 6);
    this.state = 'ready';
    this.quality = 0;
    this.baseDistance = 0;
    this.extension = 0;
    this.extended = false;
    this.flightT = 0;
    this.flightDur = 1;
    this.takeoffX = 0;
    this.landingX = 0;
    this.result = 0;
    this.peak = 0;
    this.landTimer = 0;
    this.jumbo = { top: 'OLYMPIA', big: 'JUMP', sub: 'FINAL', value: '0.00' };
    this.lastPhase = 0;
    this.liveRank = 8;
  }

  start() {
    this.state = 'run';
    this.runTime = 0;
    this.game.sound.setCrowd(0.024);
  }

  tap() {
    if (this.state === 'run') {
      this.jump();
    } else if (this.state === 'flight' && !this.extended) {
      const u = this.flightT / this.flightDur;
      if (u > 0.35 && u < 0.7) {
        this.extended = true;
        this.extension = 0.42;
        this.game.sound.tone(760, 0.12, 0.05, 'sine', 1040);
        this.game.toast('EXTENDED — +0.42 M', 'gold', 1100);
        const sx = this.world.sx(this.x);
        const sy = this.game.groundY(1, 'longjump') - this.peak * Math.sin(Math.PI * u);
        this.game.burst(sx, sy, 10, '#f7c950', 120, 0.5);
      } else {
        this.extended = true;
        this.game.toast(u <= 0.35 ? 'TOO EARLY TO EXTEND' : 'TOO LATE TO EXTEND', 'red', 900);
      }
    }
  }

  jump(auto = false) {
    if (this.state !== 'run') return;
    const x = this.x;
    let q;
    if (x >= 38.1 && x <= 39.9) {
      q = 1 - Math.abs(x - 39.0) / 1.3 * 0.12;
    } else if (x < 38.1) {
      q = clamp(0.22 + Math.max(0, x - 31) / 7.1 * 0.55, 0.22, 0.77);
    } else if (x <= 40.6) {
      q = 0.58;
    } else {
      q = 0.34;
    }
    if (auto) q = Math.min(q, 0.32);
    this.quality = q;
    this.takeoffX = x;
    this.baseDistance = 3.65 + this.speed * 0.337 + q * 1.18;
    this.result = this.baseDistance;
    const visual = Math.max(3.6, this.baseDistance);
    this.landingX = 40 + visual + 0.42;
    this.peak = this.H * (0.055 + clamp(this.speed / 12, 0, 1) * 0.04);
    this.flightDur = clamp(0.62 + this.baseDistance * 0.038, 0.86, 1.1);
    this.flightT = 0;
    this.state = 'flight';
    this.game.sound.jump();
    this.game.shake = Math.max(this.game.shake, 2.5);
    this.game.toast(x < 38.1 ? 'EARLY TAKEOFF' : x > 40.3 ? 'OVERSTEP' : 'CLEAN TAKEOFF', x < 38.1 || x > 40.3 ? 'red' : 'gold', 700);
  }

  update(dt) {
    this.phase += dt;
    if (this.state === 'ready') return;
    if (this.state === 'run') {
      this.runTime += dt;
      this.speed = 10.7 * smoothstep(0, 3.7, this.runTime);
      this.x += this.speed * dt;
      this.phase += this.speed * 0.96 * dt;
      if (this.x > 40.9) this.jump(true);
      this.updateCamera(dt, this.x, 3.2);
      this.spawnDust();
    } else if (this.state === 'flight') {
      this.flightT += dt;
      const u = clamp(this.flightT / this.flightDur, 0, 1);
      this.x = lerp(this.takeoffX, this.landingX, u);
      this.phase += 2.4 * dt;
      this.updateCamera(dt, this.x, 2.5);
      if (u >= 1) this.land();
    } else if (this.state === 'landed') {
      this.landTimer += dt;
      this.updateCamera(dt, this.landingX, 1.8);
      if (this.landTimer > 1.55) {
        this.state = 'done';
        this.done(this.result, { quality: this.quality, extended: this.extended });
      }
    }

    this.liveRank = 1 + this.game.fieldRank('longjump', this.state === 'landed' ? this.result : this.baseDistance);
    this.jumbo.value = this.state === 'landed' ? `${this.result.toFixed(2)}` : this.state === 'flight' ? 'AIR' : '0.00';
    this.hudState();
  }

  hudState() {
    const toBoard = Math.max(0, 40 - this.x);
    const clockValue = this.state === 'landed'
      ? fmtDist(this.result)
      : toBoard > 0 ? toBoard.toFixed(1) : 'BOARD';
    const clockUnit = this.state === 'landed' ? 'm' : toBoard > 0 ? 'm' : '';
    let prompt;
    if (this.state === 'run') {
      if (this.x < 30) prompt = { key: '↑', title: 'BUILD SPEED', sub: 'Stay relaxed — the board is coming', pulse: false };
      else if (this.x < 37.6) prompt = { key: '↑', title: 'FIND THE BOARD', sub: 'Tap as you enter the glowing zone', pulse: false };
      else prompt = { key: '↑', title: 'TAKE OFF NOW', sub: 'Hit the board cleanly', pulse: true };
    } else if (this.state === 'flight') {
      prompt = this.extended
        ? { key: '✓', title: 'EXTENSION LOCKED', sub: 'Ride the arc into the sand', pulse: false }
        : { key: '↑', title: 'TAP TO EXTEND', sub: 'Strike at the top of the flight', pulse: true };
    } else if (this.state === 'landed') {
      prompt = { key: '✓', title: 'MARK SET', sub: `${this.result.toFixed(2)} metres`, pulse: false };
    } else {
      prompt = { visible: false };
    }
    this.hud({
      clock: clockValue,
      clockUnit,
      clockLabel: this.state === 'landed' ? 'MEASURED' : 'TO BOARD',
      place: `${this.game.fieldRank('longjump', this.state === 'landed' ? this.result : this.baseDistance)}`,
      meter: this.speed,
      meterMax: 11.5,
      meterUnit: 'M/S',
      meterLabel: 'RUNWAY SPEED',
      prompt: { visible: true, ...prompt },
      action: true,
      actionLabel: this.state === 'flight' ? (this.extended ? 'LOCKED' : 'EXTEND') : 'JUMP',
      actionSub: this.state === 'flight' ? 'SPACE / TAP' : 'TAKE OFF',
      actionHot: this.state === 'run' ? (this.x > 37.5 && this.x < 40.1) : (this.state === 'flight' && !this.extended && this.flightT / this.flightDur > 0.3 && this.flightT / this.flightDur < 0.72),
      actionDisabled: this.state === 'landed' || (this.state === 'flight' && this.extended)
    });
    this.game.setMiniBoard(
      this.game.fieldBoard('longjump', this.state === 'landed' ? this.result : null),
      'FIELD ORDER'
    );
  }

  spawnDust() {
    if (this.speed < 3) return;
    const crossed = Math.floor(this.phase / Math.PI);
    if (crossed !== this.lastPhase) {
      this.lastPhase = crossed;
      const x = this.world.sx(this.x) - 10;
      const y = this.game.groundY(1, 'longjump');
      this.game.spawnParticle({
        x, y: y - 2, vx: rand(-45, -10), vy: rand(-25, -5), life: rand(0.3, 0.6),
        size: rand(1.2, 3.5), color: 'rgba(255,216,160,.26)', gravity: 30
      });
    }
  }

  land() {
    this.state = 'landed';
    this.result = this.baseDistance + this.extension;
    this.x = this.landingX;
    this.landTimer = 0;
    this.game.sound.sand(1);
    this.game.sound.cheer(0.8);
    this.game.shake = Math.max(this.game.shake, 4);
    const sx = this.world.sx(this.landingX);
    const gy = this.game.groundY(1, 'longjump');
    this.game.burst(sx, gy - 5, 26, '#cba465', 170, 0.8);
    this.game.burst(sx, gy - 5, 12, '#f7dfaa', 120, 0.55);
  }

  render(ctx) {
    this.paint();
    const ground = this.game.groundY(1, 'longjump');
    const scale = this.world.laneScale(1, 'longjump');
    const sx = this.world.sx(this.x);
    let y = ground;
    let pose = 'run';
    let height = 0;
    let alpha = 1;
    if (this.state === 'ready') { pose = 'idle'; }
    if (this.state === 'flight') {
      const u = clamp(this.flightT / this.flightDur, 0, 1);
      height = this.peak * Math.sin(Math.PI * u);
      y = ground - height;
      pose = 'jump';
    } else if (this.state === 'landed') {
      pose = 'land';
    }

    // shadow shrinks in the air
    if (height > 0) {
      ctx.save();
      ctx.globalAlpha = clamp(1 - height / (this.H * 0.25), 0.15, 0.6);
    }
    drawAthlete(ctx, {
      x: sx, y: y, scale, phase: this.phase, pose,
      speed: clamp(this.speed / 11, 0, 1), kit: this.game.playerKit,
      glow: 0.16, shadow: height > 0 ? 0.5 : 1
    });
    if (height > 0) ctx.restore();

    if (this.state === 'flight') {
      this.drawTrajectory(ctx, ground, scale);
    }
    if (this.state === 'landed') {
      this.drawMeasurement(ctx, ground, scale);
    }
    this.drawAthleteAura(ctx, sx, y, scale);
  }

  drawAthleteAura(ctx, x, y, scale) {
    const g = ctx.createRadialGradient(x, y - 60 * scale, 0, x, y - 60 * scale, 95 * scale);
    g.addColorStop(0, 'rgba(255,213,130,.045)');
    g.addColorStop(1, 'rgba(255,213,130,0)');
    ctx.save();
    ctx.globalCompositeOperation = 'screen';
    ctx.fillStyle = g;
    ctx.fillRect(x - 120 * scale, y - 190 * scale, 240 * scale, 200 * scale);
    ctx.restore();
  }

  drawTrajectory(ctx, ground, scale) {
    const start = this.world.sx(this.takeoffX);
    const end = this.world.sx(this.landingX);
    ctx.save();
    ctx.globalAlpha = 0.33;
    ctx.strokeStyle = 'rgba(247,201,80,.7)';
    ctx.lineWidth = 1;
    ctx.setLineDash([4, 7]);
    ctx.beginPath();
    for (let i = 0; i <= 20; i++) {
      const u = i / 20;
      const x = lerp(start, end, u);
      const y = ground - this.peak * Math.sin(Math.PI * u) - 50 * scale;
      i === 0 ? ctx.moveTo(x, y) : ctx.lineTo(x, y);
    }
    ctx.stroke();
    ctx.restore();
  }

  drawMeasurement(ctx, ground, scale) {
    const boardX = this.world.sx(40);
    const landX = this.world.sx(40 + this.result);
    const y = ground + 12;
    ctx.save();
    ctx.strokeStyle = 'rgba(247,201,80,.85)';
    ctx.lineWidth = 1.4;
    ctx.beginPath(); ctx.moveTo(boardX, y); ctx.lineTo(landX, y); ctx.stroke();
    ctx.fillStyle = 'rgba(247,201,80,.8)';
    for (let x = boardX; x <= landX; x += 12) ctx.fillRect(x, y - 3, 1, 6);
    ctx.fillStyle = 'rgba(5,11,22,.86)';
    ctx.strokeStyle = 'rgba(247,201,80,.55)';
    ctx.beginPath();
    if (ctx.roundRect) ctx.roundRect(landX - 25, y - 25, 50, 17, 2); else ctx.rect(landX - 25, y - 25, 50, 17);
    ctx.fill(); ctx.stroke();
    ctx.fillStyle = '#f7c950';
    ctx.font = '700 10px "Barlow Condensed", sans-serif';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillText(`${this.result.toFixed(2)}m`, landX, y - 16.5);
    ctx.restore();
  }
}

/* ================================================================== */
/*  JAVELIN                                                            */
/* ================================================================== */
export class JavelinEvent extends BaseEvent {
  constructor(game, options = {}) {
    super(game, 'javelin', options);
    this.meter = clamp(this.W / 24, 16, 52);
    this.anchor = 0.37;
    this.camX = -(this.W * 0.37) / this.meter;
    this.x = 0;
    this.runTime = 0;
    this.speed = 0;
    this.phase = rand(0, 6);
    this.angle = 36;
    this.angleTime = 0;
    this.state = 'ready';
    this.result = 0;
    this.flightT = 0;
    this.flightDur = 3.6;
    this.startX = 0;
    this.landX = 36;
    this.peak = 0;
    this.landTimer = 0;
    this.releaseScore = 1;
    this.angleScore = 1;
    this.jumbo = { top: 'OLYMPIA', big: 'JAVELIN', sub: 'FINAL', value: '0.00' };
    this.lastPhase = 0;
    this.trail = [];
    this.liveRank = 8;
  }

  start() {
    this.state = 'run';
    this.runTime = 0;
    this.game.sound.setCrowd(0.023);
  }

  tap() {
    if (this.state === 'run') this.throwSpear();
  }

  throwSpear(auto = false) {
    if (this.state !== 'run') return;
    const x = this.x;
    this.releaseScore = 1 - clamp((36 - x) / 13, 0, 1) * 0.6;
    this.angleScore = 1 - clamp(Math.abs(this.angle - 36) / 22, 0, 1) * 0.85;
    const precision = Math.max(0, 1 - Math.abs(this.angle - 36) / 4) * 0.8
      + Math.max(0, 1 - Math.abs(36 - x) / 1.6) * 0.5;
    const speedFactor = clamp(this.speed / 10.9, 0, 1);
    this.result = 54.5 + 34.5 * this.releaseScore * this.angleScore * (0.78 + 0.22 * speedFactor) + precision + rand(-0.45, 0.45);
    if (auto) this.result *= 0.88;
    this.result = clamp(this.result, 45, 93.4);
    this.startX = x + 1.2;
    this.landX = 36 + this.result;
    this.peak = this.H * (0.12 + this.result / 450);
    this.flightDur = 3.1 + this.result * 0.007;
    this.flightT = 0;
    this.state = 'flight';
    this.trail = [];
    this.game.sound.javelinThrow();
    this.game.shake = Math.max(this.game.shake, 6);
    this.game.flashScreen(0.22);
    this.game.toast(
      auto ? 'LATE RELEASE' : Math.abs(this.angle - 36) < 4 ? 'PERFECT ANGLE' : 'SPEAR AWAY',
      Math.abs(this.angle - 36) < 4 ? 'gold' : '', 850
    );
    // Camera expands to follow the whole throw.
    this.camX = (this.startX + this.landX) / 2 - (this.W * 0.5) / this.meter;
  }

  update(dt) {
    this.phase += dt;
    if (this.state === 'ready') return;
    if (this.state === 'run') {
      this.runTime += dt;
      this.angleTime += dt;
      this.angle = 36 + 21 * Math.sin(this.angleTime * 3.55 - 0.9);
      this.speed = 10.9 * smoothstep(0, 3.5, this.runTime);
      this.x += this.speed * dt;
      this.phase += this.speed * 0.92 * dt;
      if (this.x >= 36.35) {
        this.x = 36.2;
        this.throwSpear(true);
      }
      this.updateCamera(dt, this.x, 3.8);
      this.spawnDust();
    } else if (this.state === 'flight') {
      this.flightT += dt;
      const u = clamp(this.flightT / this.flightDur, 0, 1);
      this.x = lerp(this.startX, this.landX, u);
      const targetMeter = clamp(this.W / 102, 8.2, 18);
      this.meter = lerp(this.meter, targetMeter, 1 - Math.exp(-1.4 * dt));
      const targetCam = (this.startX + this.landX) / 2 - (this.W * 0.5) / this.meter;
      this.camX = lerp(this.camX, targetCam, 1 - Math.exp(-1.8 * dt));
      this.anchor = lerp(this.anchor, 0.5, 1 - Math.exp(-1.6 * dt));
      this.world.setCamera(this.camX, this.meter, this.anchor, 'javelin');
      if (u >= 1) this.land();
    } else if (this.state === 'landed') {
      this.landTimer += dt;
      const targetCam = (this.startX + this.landX) / 2 - (this.W * 0.5) / this.meter;
      this.camX = lerp(this.camX, targetCam, 1 - Math.exp(-1.2 * dt));
      this.world.setCamera(this.camX, this.meter, this.anchor, 'javelin');
      if (this.landTimer > 1.8) {
        this.state = 'done';
        this.done(this.result, { angle: this.angle, release: this.releaseScore });
        return;
      }
    }
    this.liveRank = 1 + this.game.fieldRank('javelin', this.state === 'landed' ? this.result : 0);
    this.jumbo.value = this.state === 'landed' ? this.result.toFixed(1) : this.state === 'flight' ? `${this.angle.toFixed(0)}°` : '0.00';
    this.hudState();
  }

  hudState() {
    const toLine = Math.max(0, 36 - this.x);
    const clockValue = this.state === 'landed' ? fmtDist(this.result, 1) : toLine.toFixed(1);
    const clockUnit = this.state === 'landed' ? 'm' : 'm';
    let prompt;
    if (this.state === 'run') {
      prompt = {
        key: '↑', title: 'RELEASE AT THE LINE',
        sub: `Arm angle ${this.angle.toFixed(0)}° — find the gold band`,
        pulse: Math.abs(this.angle - 36) < 5
      };
    } else if (this.state === 'flight') {
      prompt = { key: '✓', title: 'THE SPEAR IS FLYING', sub: 'The stadium is watching', pulse: false };
    } else if (this.state === 'landed') {
      prompt = { key: '✓', title: 'DISTANCE MEASURED', sub: `${this.result.toFixed(2)} metres`, pulse: false };
    } else {
      prompt = { visible: false };
    }
    this.hud({
      clock: clockValue,
      clockUnit,
      clockLabel: this.state === 'landed' ? 'MEASURED' : 'TO FOUL LINE',
      place: `${this.game.fieldRank('javelin', this.state === 'landed' ? this.result : 0)}`,
      meter: this.speed,
      meterMax: 11.5,
      meterUnit: 'M/S',
      meterLabel: 'APPROACH',
      prompt: { visible: true, ...prompt },
      action: true,
      actionLabel: this.state === 'flight' || this.state === 'landed' ? 'FLY' : 'THROW',
      actionSub: 'SPACE / TAP',
      actionHot: this.state === 'run' && this.x > 29,
      actionDisabled: this.state !== 'run',
      javelin: true,
      angle: this.angle,
      angleValue: this.angle
    });
    this.game.setMiniBoard(
      this.game.fieldBoard('javelin', this.state === 'landed' ? this.result : null),
      'FIELD ORDER'
    );
  }

  spawnDust() {
    if (this.speed < 3) return;
    const crossed = Math.floor(this.phase / Math.PI);
    if (crossed !== this.lastPhase) {
      this.lastPhase = crossed;
      const x = this.world.sx(this.x) - 10;
      const y = this.game.groundY(1, 'javelin');
      this.game.spawnParticle({
        x, y: y - 2, vx: rand(-40, -8), vy: rand(-24, -4), life: rand(0.3, 0.55),
        size: rand(1.2, 3.2), color: 'rgba(255,216,160,.23)', gravity: 28
      });
    }
  }

  land() {
    this.state = 'landed';
    this.x = this.landX;
    this.landTimer = 0;
    this.game.sound.javelinLand();
    this.game.sound.cheer(1.1);
    this.game.shake = Math.max(this.game.shake, 5);
    const sx = this.world.sx(this.landX);
    const gy = this.game.groundY(1, 'javelin');
    this.game.burst(sx, gy - 5, 28, '#d6c393', 150, 0.75);
    this.game.burst(sx, gy - 5, 18, '#f8e2ad', 100, 0.5);
    this.game.toast(`${this.result.toFixed(2)} M`, 'gold', 1300);
    this.trail = [];
  }

  render(ctx) {
    this.paint();
    const ground = this.game.groundY(1, 'javelin');
    const scale = this.world.laneScale(1, 'javelin');
    const sx = this.world.sx(this.x);

    if (this.state === 'run' || this.state === 'ready') {
      const pose = this.state === 'ready' ? 'idle' : 'run';
      drawAthlete(ctx, {
        x: sx, y: ground, scale, phase: this.phase, pose,
        speed: clamp(this.speed / 11, 0, 1), kit: this.game.playerKit,
        glow: 0.18, shadow: 1,
        javelin: { angle: -0.16 }
      });
    } else if (this.state === 'flight') {
      const pose = this.flightT < 0.35 ? 'release' : 'idle';
      drawAthlete(ctx, {
        x: sx, y: ground, scale, phase: this.phase, pose,
        speed: 0.2, kit: this.game.playerKit, glow: 0.2, shadow: 1
      });
    } else {
      drawAthlete(ctx, {
        x: sx, y: ground, scale, phase: this.phase, pose: 'idle',
        speed: 0.1, kit: this.game.playerKit, glow: 0.15, shadow: 1
      });
    }

    if (this.state === 'flight') this.drawSpearFlight(ctx, ground, scale);
    if (this.state === 'landed') this.drawJavelinMeasurement(ctx, ground, scale);
  }

  drawSpearFlight(ctx, ground, scale) {
    const u = clamp(this.flightT / this.flightDur, 0, 1);
    const x = this.world.sx(this.x);
    const shoulder = 2.2 * this.meter;
    const y = ground - shoulder * (1 - u) - this.peak * Math.sin(Math.PI * u);
    const x2 = this.world.sx(lerp(this.startX, this.landX, clamp(u + 0.008, 0, 1)));
    const y2 = ground - shoulder * (1 - clamp(u + 0.008, 0, 1)) - this.peak * Math.sin(Math.PI * clamp(u + 0.008, 0, 1));
    const angle = Math.atan2(y2 - y, x2 - x);
    const len = Math.max(34, 62 * this.u);
    ctx.save();
    ctx.translate(x, y);
    ctx.rotate(angle);
    const grad = ctx.createLinearGradient(-len / 2, 0, len / 2, 0);
    grad.addColorStop(0, '#6f5733');
    grad.addColorStop(0.45, '#e1c484');
    grad.addColorStop(0.8, '#f7ecc8');
    grad.addColorStop(1, '#ffffff');
    ctx.strokeStyle = grad;
    ctx.lineWidth = Math.max(1.4, 2.5 * this.u);
    ctx.lineCap = 'round';
    ctx.beginPath(); ctx.moveTo(-len / 2, 0); ctx.lineTo(len / 2, 0); ctx.stroke();
    ctx.fillStyle = '#f5f8fa';
    ctx.beginPath(); ctx.moveTo(len / 2 + 4, 0); ctx.lineTo(len / 2 - 4, -3); ctx.lineTo(len / 2 - 4, 3); ctx.closePath(); ctx.fill();
    ctx.restore();

    // speed trail
    for (let i = 0; i < 7; i++) {
      const uu = clamp(u - i * 0.012, 0, 1);
      const tx = this.world.sx(lerp(this.startX, this.landX, uu));
      const ty = ground - shoulder * (1 - uu) - this.peak * Math.sin(Math.PI * uu);
      ctx.fillStyle = `rgba(255,231,164,${0.13 * (1 - i / 7)})`;
      ctx.beginPath(); ctx.arc(tx, ty, 1.6, 0, Math.PI * 2); ctx.fill();
    }
  }

  drawJavelinMeasurement(ctx, ground, scale) {
    const lineX = this.world.sx(36);
    const landX = this.world.sx(this.landX);
    const y = ground + 16;
    ctx.save();
    ctx.strokeStyle = 'rgba(247,201,80,.82)';
    ctx.lineWidth = 1.3;
    ctx.beginPath(); ctx.moveTo(lineX, y); ctx.lineTo(landX, y); ctx.stroke();
    ctx.fillStyle = 'rgba(247,201,80,.75)';
    for (let x = lineX; x <= landX; x += 10) ctx.fillRect(x, y - 3, 1, 6);
    ctx.fillStyle = 'rgba(5,11,22,.88)';
    ctx.strokeStyle = 'rgba(247,201,80,.55)';
    ctx.beginPath();
    if (ctx.roundRect) ctx.roundRect(landX - 28, y - 28, 56, 18, 2); else ctx.rect(landX - 28, y - 28, 56, 18);
    ctx.fill(); ctx.stroke();
    ctx.fillStyle = '#f7c950';
    ctx.font = '700 11px "Barlow Condensed", sans-serif';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillText(`${this.result.toFixed(2)}m`, landX, y - 19);
    ctx.restore();
  }
}

