import { clamp, lerp, rand, ordinal, fmtTime, fmtDist, rgba, TAU } from './utils.js';
import { StadiumWorld } from './world.js';
import { drawAthlete, KITS } from './athlete.js';
import { SoundEngine } from './audio.js';
import { SprintEvent, LongJumpEvent, JavelinEvent } from './events.js';

const AI_DATA = [
  { id: 'nakamura', name: 'K. NAKAMURA', code: 'JPN', kit: KITS.jpn, sprint: 9.79, longjump: 8.31, javelin: 83.5 },
  { id: 'moreau', name: 'L. MOREAU', code: 'FRA', kit: KITS.fra, sprint: 9.92, longjump: 7.84, javelin: 81.8 },
  { id: 'okafor', name: 'D. OKAFOR', code: 'NGA', kit: KITS.nga, sprint: 9.98, longjump: 8.44, javelin: 86.9 },
  { id: 'voss', name: 'S. VOSS', code: 'GER', kit: KITS.ger, sprint: 9.86, longjump: 8.10, javelin: 88.4 },
  { id: 'silva', name: 'E. SILVA', code: 'BRA', kit: KITS.bra, sprint: 10.08, longjump: 7.96, javelin: 79.6 },
  { id: 'hassan', name: 'M. HASSAN', code: 'KEN', kit: KITS.ken, sprint: 10.16, longjump: 7.62, javelin: 85.1 },
  { id: 'petrov', name: 'A. PETROV', code: 'CRO', kit: KITS.cro, sprint: 10.29, longjump: 8.22, javelin: 90.6 }
];

const PLAYER = { id: 'player', name: 'YOU', code: 'AUR', kit: KITS.player, player: true };

const EVENTS = {
  sprint: {
    id: 'sprint', num: '01', name: '100M SPRINT', title: '100M<br/><em>SPRINT</em>',
    record: '9.63', recordUnit: 'SECONDS', champ: 'K. NAKAMURA', champCode: 'JPN',
    desc: 'Explode from the blocks. Alternate left and right strikes to drive your cadence, then hold top speed all the way through the line.',
    controls: [
      { keys: ['A', 'D'], label: 'ALTERNATE TAPS' },
      { keys: ['GUN'], label: 'GO ON THE BANG' },
      { keys: ['CADENCE'], label: 'FAST + CLEAN' }
    ],
    unit: 's'
  },
  longjump: {
    id: 'longjump', num: '02', name: 'LONG JUMP', title: 'LONG<br/><em>JUMP</em>',
    record: '8.95', recordUnit: 'METRES', champ: 'D. OKAFOR', champCode: 'NGA',
