drawRoof(ctx) {
  const W = this.W, H = this.H;
  const roofY = H * 0.115;
  const roofBottom = H * 0.245;

  // roof canopy shadow
  ctx.fillStyle = 'rgba(2,6,14,.62)';
  ctx.beginPath();
  ctx.moveTo(-20, H * 0.02);
  ctx.lineTo(W + 20, H * -0.01);
  ctx.lineTo(W + 20, roofBottom * 0.82);
  ctx.quadraticCurveTo(W * 0.78, roofBottom, W * 0.62, roofBottom * 0.93);
  ctx.quadraticCurveTo(W * 0.4, roofBottom * 1.08, W * 0.2, roofBottom * 0.96);
  ctx.quadraticCurveTo(W * 0.04, roofBottom * 0.9, -20, H * 0.17);
  ctx.closePath();
  ctx.fill();

  // leading edge of the roof
  const edge = ctx.createLinearGradient(0, roofY, 0, roofBottom);
  edge.addColorStop(0, '#101c2d');
  edge.addColorStop(0.45, '#0a1525');
  edge.addColorStop(1, '#040a14');
  ctx.strokeStyle = 'rgba(128,157,195,.18)';
  ctx.lineWidth = 1.1;
  ctx.beginPath();
  ctx.moveTo(0, H * 0.183);
  ctx.quadraticCurveTo(W * 0.22, H * 0.225, W * 0.44, H * 0.212);
  ctx.quadraticCurveTo(W * 0.7, H * 0.198, W, H * 0.232);
  ctx.stroke();

  // trusses
  ctx.strokeStyle = 'rgba(111,141,181,.11)';
  ctx.lineWidth = 0.8;
  for (let i = 0; i < 12; i++) {
    const x = (i / 11) * W;
    const y = H * 0.088 + Math.sin(i * 1.3) * H * 0.012;
    ctx.beginPath();
    ctx.moveTo(x, 0);
    ctx.lineTo(x, H * 0.175 + i % 3 * 7);
    ctx.stroke();
  }
  ctx.strokeStyle = 'rgba(123,153,191,.08)';
  for (let i = 0; i < 8; i++) {
    const y = H * 0.04 + i * H * 0.021;
    ctx.beginPath();
    ctx.moveTo(0, y);
    ctx.lineTo(W, y - H * 0.012);
    ctx.stroke();
  }
  ctx.fillStyle = edge;
  ctx.beginPath();
  ctx.moveTo(0, H * 0.16);
  ctx.quadraticCurveTo(W * 0.25, H * 0.19, W * 0.5, H * 0.182);
  ctx.quadraticCurveTo(W * 0.76, H * 0.174, W, H * 0.204);
  ctx.lineTo(W, H * 0.225);
  ctx.quadraticCurveTo(W * 0.76, H * 0.198, W * 0.5, H * 0.207);
  ctx.quadraticCurveTo(W * 0.25, H * 0.215, 0, H * 0.185);
  ctx.closePath();
  ctx.fill();
}

