content.text:
import { clamp, lerp, rand, ordinal, fmtTime, fmtDist, rgba, TAU } from './utils.js';
import { StadiumWorld } from './world.js';
import { drawAthlete, KITS } from './athlete.js';
import { SoundEngine } from './audio.js';
import { SprintEvent, LongJumpEvent, JavelinEvent } from './events.js';

const AI_DATA = [
  { id: 'nakamura', name: 'K. NAKAMURA', code: 'JPN', kit: KITS.jpn, sprint: 9.79, longjump: 8.31, javelin: 83.5 },
  { id: 'moreau', name: 'L. MOREAU', code: 'FRA', kit: KITS.fra, sprint: 9.92, longjump: 7.84, javelin: 81.8 },
  { id: 'okafor', name: 'D. OKAFOR', code: 'NGA', kit: KITS.nga, sprint: 9.98, longjump: 8.44, javelin: 86.9 },
  { id: 'voss', name: 'S. VOSS', code: 'GER', kit: KITS.ger, sprint: 9.86, longjump: 8.10, javelin: 88.4 },
  { id: 'silva', name: 'E. SILVA', code: 'BRA', kit: KITS.bra, sprint: 10.08, longjump: 7.96, javelin: 79.6 },
  { id: 'hassan', name: 'M. HASSAN', code: 'KEN', kit: KITS.ken, sprint: 10.16, longjump: 7.62, javelin: 85.1 },
  { id: 'petrov', name: 'A. PETROV', code: 'CRO', kit: KITS.cro, sprint: 10.29, longjump: 8.22, javelin: 90.6 }
];

const PLAYER = { id: 'player', name: 'YOU', code: 'AUR', kit: KITS.player, player: true };

const EVENTS = {
  sprint: {
    id: 'sprint', num: '01', name: '100M SPRINT', title: '100M<br/><em>SPRINT</em>',
    record: '9.63', recordUnit: 'SECONDS', champ: 'K. NAKAMURA', champCode: 'JPN',
    desc: 'Explode from the blocks. Alternate left and right strikes to drive your cadence, then hold top speed all the way through the line.',
    controls: [
      { keys: ['A', 'D'], label: 'ALTERNATE TAPS' },
      { keys: ['GUN'], label: 'GO ON THE BANG' },
      { keys: ['CADENCE'], label: 'FAST + CLEAN' }
    ],
    unit: 's'
  },
  longjump: {
    id: 'longjump', num: '02', name: 'LONG JUMP', title: 'LONG<br/><em>JUMP</em>',
    record: '8.95', recordUnit: 'METRES', champ: 'D. OKAFOR', champCode: 'NGA',
    desc: 'The runway is automatic. Tap as you enter the glowing takeoff zone, then tap again at the top of the flight to stretch your landing.',
    controls: [
      { keys: ['SPACE'], label: 'TAKE OFF' },
      { keys: ['SPACE'], label: 'EXTEND AT APEX' },
      { keys: ['BOARD'], label: 'DON’T OVERSTEP' }
    ],
    unit: 'm'
  },
  javelin: {
    id: 'javelin', num: '03', name: 'JAVELIN', title: 'JAVE<br/><em>LIN</em>',
    record: '98.48', recordUnit: 'METRES', champ: 'A. PETROV', champCode: 'CRO',
    desc: 'Release the spear as close to the foul line as you dare. Time the tap while the arm angle is in the gold band around 36 degrees.',
    controls: [
      { keys: ['SPACE'], label: 'RELEASE' },
      { keys: ['36°'], label: 'PERFECT ANGLE' },
      { keys: ['LINE'], label: 'MAXIMUM POWER' }
    ],
    unit: 'm'
  }
};

class Particles {
  constructor() { this.list = []; }
  spawn(o) {
    if (this.list.length > 900) this.list.shift();
    const life = o.life ?? 0.7;
    this.list.push({
      x: o.x, y: o.y, vx: o.vx ?? 0, vy: o.vy ?? 0,
      life, maxLife: life, size: o.size ?? 2, color: o.color ?? '#fff',
      gravity: o.gravity ?? 0, drag: o.drag ?? 0, shape: o.shape ?? 'circle',
      rot: o.rot ?? 0, vr: o.vr ?? 0, alpha: o.alpha ?? 1
    });
  }
  burst(x, y, count, color, speed = 120, life = 0.7, gravity = 160) {
    for (let i = 0; i < count; i++) {
      const a = rand(0, TAU);
      const v = speed * rand(0.25, 1);
      this.spawn({
        x, y, vx: Math.cos(a) * v, vy: Math.sin(a) * v - rand(0, 45),
        life: life * rand(0.55, 1.2), size: rand(1, 3.5), color,
        gravity, drag: 0.8, alpha: rand(0.35, 0.9)
      });
    }
  }
  confetti(n = 60, W, H) {
    const colors = ['#f7c950', '#f7f1dc', '#80e5ff', '#d9a42c', '#ff7766', '#75e3a4'];
    for (let i = 0; i < n; i++) {
      this.spawn({
        x: rand(0, W), y: rand(-H * 0.2, H * 0.1),
        vx: rand(-45, 45), vy: rand(50, 190), life: rand(2.5, 5),
        size: rand(2, 5.5), color: colors[Math.floor(rand(0, colors.length))],
        gravity: 28, drag: 0.1, shape: 'confetti', rot: rand(0, TAU), vr: rand(-8, 8), alpha: rand(0.6, 1)
      });
    }
  }
  clear() { this.list.length = 0; }
  update(dt) {
    for (let i = this.list.length - 1; i >= 0; i--) {
      const p = this.list[i];
      p.life -= dt;
      if (p.life <= 0) { this.list.splice(i, 1); continue; }
      p.vy += p.gravity * dt;
      if (p.drag) {
        const d = Math.exp(-p.drag * dt);
        p.vx *= d; p.vy *= d;
      }
      p.x += p.vx * dt;
      p.y += p.vy * dt;
      p.rot += p.vr * dt;
    }
  }
  draw(ctx) {
    for (const p of this.list) {
      const a = clamp(p.life / p.maxLife, 0, 1) * p.alpha;
      ctx.save();
      ctx.globalAlpha = a;
      ctx.fillStyle = p.color;
      ctx.translate(p.x, p.y);
      if (p.shape === 'confetti') {
        ctx.rotate(p.rot);
        ctx.fillRect(-p.size / 2, -p.size * 1.4, p.size, p.size * 2.8);
      } else if (p.shape === 'streak') {
        ctx.rotate(p.rot);
        ctx.fillRect(-p.size * 2.5, -p.size * 0.4, p.size * 5, p.size * 0.8);
      } else {
        ctx.beginPath();
        ctx.arc(0, 0, Math.max(0.3, p.size * (0.4 + a * 0.6)), 0, TAU);
        ctx.fill();
      }
      ctx.restore();
    }
  }
}

class Game {
  constructor() {
    this.canvas = document.getElementById('stage');
    this.ctx = this.canvas.getContext('2d', { alpha: false });
    this.world = new StadiumWorld();
    this.sound = new SoundEngine();
    this.particles = new Particles();
    this.roster = [PLAYER, ...AI_DATA.map(a => ({ ...a }))];
    this.playerKit = KITS.player;
    this.state = 'menu';
    this.paused = false;
    this.menuT = 0;
    this.shake = 0;
    this.hudData = null;
    this.miniData = null;
    this.miniMeta = '';
    this.miniTimer = 0;
    this.countdown = null;
    this.falseStartTimer = 0;
    this.goHideTimer = 0;
    this.currentEvent = null;
    this.currentEventId = null;
    this.series = null;
    this.fields = null;
    this.pending = null;
    this.lastEvent = null;
    this.resultsMode = null;
    this.ceremonyT = 0;
    this.lastFirework = 0;
    this.miniPulse = 0;
    this.toastTimer = null;
    this.flashTimer = null;
    this.hideTimer = null;
    this.bests = this.loadBests();
    this.scoreBest = Number(localStorage.getItem('olympia-best-score') || 0) || 0;
    this.bind();
    this.resize();
    this.setSoundUi();
    this.updateMenuBest();
    this.last = performance.now();
    this.loop = this.loop.bind(this);
    requestAnimationFrame(this.loop);
    // A gentle trail of dust makes the opening frame feel alive immediately.
    this.menuSpawnAcc = 0;
  }

  /* ---------------------------------------------------------------- */
  loadBests() {
    try {
      const b = JSON.parse(localStorage.getItem('olympia-bests') || '{}');
      return { sprint: b.sprint || null, longjump: b.longjump || null, javelin: b.javelin || null };
    } catch { return { sprint: null, longjump: null, javelin: null }; }
  }
  saveBests() {
    localStorage.setItem('olympia-bests', JSON.stringify(this.bests));
  }
  updateMenuBest() {
    const fmt = (id, unit) => {
      const v = this.bests[id];
      const el = document.getElementById(`pb-${id}`);
      if (!el) return;
      el.textContent = v ? `PB ${id === 'sprint' ? fmtTime(v) : fmtDist(v)}${unit}` : 'PB —';
    };
    fmt('sprint', 's');
    fmt('longjump', 'm');
    fmt('javelin', 'm');
    const best = document.getElementById('menuBest');
    if (best) best.textContent = this.scoreBest ? `${this.scoreBest} PTS` : '—';
  }

  /* ---------------------------------------------------------------- */
  resize() {
    this.W = window.innerWidth;
    this.H = window.innerHeight;
    this.dpr = Math.min(window.devicePixelRatio || 1, 2);
    this.canvas.width = Math.round(this.W * this.dpr);
    this.canvas.height = Math.round(this.H * this.dpr);
    this.canvas.style.width = `${this.W}px`;
    this.canvas.style.height = `${this.H}px`;
    this.ctx.setTransform(this.dpr, 0, 0, this.dpr, 0, 0);
    this.world.resize(this.W, this.H);
  }

  /* ---------------------------------------------------------------- */
  bind() {
    window.addEventListener('resize', () => this.resize());
    window.addEventListener('orientationchange', () => setTimeout(() => this.resize(), 80));
    window.addEventListener('keydown', e => this.onKey(e));
    document.addEventListener('visibilitychange', () => {
      if (document.hidden && this.state === 'running' && !this.paused) this.openPause();
    });

    document.addEventListener('click', e => {

  document.addEventListener('click', e => {
    const btn = e.target.closest('[data-action]');
    if (!btn) return;
    e.preventDefault();
    this.sound.init();
    this.onAction(btn.dataset.action, btn.dataset.event, btn);
  });

  document.querySelectorAll('[data-tap]').forEach(btn => {
    btn.addEventListener('pointerdown', e => {
      e.preventDefault();
      this.sound.init();
      this.handleDirectional(btn.dataset.tap);
    });
  });

  const actionBtn = document.getElementById('actionBtn');
  if (actionBtn) {
    actionBtn.addEventListener('pointerdown', e => {
      e.preventDefault();
      this.sound.init();
      this.handleAction();
    });
  }

  const soundBtn = document.getElementById('soundBtn');
  if (soundBtn) soundBtn.addEventListener('click', e => { e.stopPropagation(); });

  document.addEventListener('contextmenu', e => {
    if (e.target.closest('#app')) e.preventDefault();
  });
}

onAction(action, eventId) {
  switch (action) {
    case 'start-series':
      this.sound.ui();
      this.startSeries();
      break;
    case 'practice':
      this.sound.ui();
      this.openPractice();
      break;
    case 'close-practice':
      this.sound.uiBack();
      document.getElementById('practiceMenu').classList.remove('is-active');
      break;
    case 'practice-event':
      this.sound.ui();
      this.startPractice(eventId);
      break;
    case 'enter-event':
      this.sound.ui();
      this.enterEvent();
      break;
    case 'pause':
      this.openPause();
      break;
    case 'resume':
      this.resume();
      break;
    case 'restart-event':
      this.restartEvent();
      break;
    case 'quit-event':
      this.quitEvent();
      break;
    case 'guide':
      this.openGuide();
      break;
    case 'close-guide':
      this.closeGuide();
      break;
    case 'sound':
      this.toggleSound();
      break;
    case 'results-next':
      this.onResultsNext();
      break;
    case 'results-replay':
      this.onResultsReplay();
      break;
    case 'to-menu':
      this.showMenu();
      break;
    case 'restart-series':
      this.sound.ui();
      this.startSeries();
      break;
    case 'programme':
      this.sound.ui();
      this.startPractice(eventId);
      break;
    default:
      break;
  }
}

onKey(e) {
  const key = e.key;
  const lower = key.toLowerCase();
  if (key === 'Escape') {
    if (document.getElementById('guide').classList.contains('is-active')) { this.closeGuide(); return; }
    if (this.paused) { this.resume(); return; }
    if (this.state === 'running') { this.openPause(); return; }
    if (document.getElementById('practiceMenu').classList.contains('is-active')) {
      document.getElementById('practiceMenu').classList.remove('is-active');
    }
    return;
  }
  if (this.paused && (lower === 'r')) { this.restartEvent(); return; }
  if (this.state === 'running' && this.currentEvent) {
    if (this.currentEventId === 'sprint') {
      if (lower === 'a' || key === 'ArrowLeft') { e.preventDefault(); this.handleDirectional('left'); }
      if (lower === 'd' || key === 'ArrowRight') { e.preventDefault(); this.handleDirectional('right'); }
    } else if (key === ' ' || lower === 'j') {
      e.preventDefault();
      if (!e.repeat) this.handleAction();
    }
  } else if (this.state === 'countdown') {
    if (this.currentEventId === 'sprint' && (lower === 'a' || lower === 'd' || key === 'ArrowLeft' || key === 'ArrowRight' || key === ' ')) {
      e.preventDefault();
      this.onFalseStartInput();
    }
  }
  if (key === ' ' && this.state === 'countdown') e.preventDefault();
}

toggleSound() {
  this.sound.init();
  this.sound.setMuted(!this.sound.muted);
  this.setSoundUi();
  if (!this.sound.muted) this.sound.ui();
}
setSoundUi() {
  const btn = document.getElementById('soundBtn');
  if (!btn) return;
  btn.classList.toggle('is-muted', this.sound.muted);
  btn.setAttribute('aria-label', this.sound.muted ? 'Enable sound' : 'Mute sound');
}

/* ---------------------------------------------------------------- */
startSeries() {
  this.closeAllOverlays();
  this.sound.init();
  this.fields = null;
  this.ensureFields();
  this.series = {
    index: 0,
    totals: Object.fromEntries(this.roster.map(a => [a.id, 0])),
    golds: Object.fromEntries(this.roster.map(a => [a.id, 0])),
    silvers: Object.fromEntries(this.roster.map(a => [a.id, 0])),
    bronzes: Object.fromEntries(this.roster.map(a => [a.id, 0])),
    events: []
  };
  this.pending = { type: 'series' };
  this.showIntro('sprint');
}

startPractice(id) {
  this.closeAllOverlays();
  this.sound.init();
  this.fields = null;
  this.ensureFields();
  this.series = null;
  this.pending = { type: 'practice', id };
  this.showIntro(id);
}

openPractice() {
  if (this.state !== 'menu') return;
  document.getElementById('practiceMenu').classList.add('is-active');
}

showIntro(id) {
  this.state = 'intro';
  this.currentEventId = id;
  this.paused = false;
  this.sound.setCrowd(0.018);
  this.hideScreens();
  const intro = document.getElementById('eventIntro');
  intro.classList.add('is-active');
  const meta = EVENTS[id];
  const isPractice = this.pending?.type === 'practice';
  document.getElementById('introNumber').textContent = meta.num;
  document.getElementById('introKicker').textContent = `EVENT ${meta.num} / 03 · ${isPractice ? 'PRACTICE' : 'FINAL'}`;
  document.getElementById('introTitle').innerHTML = meta.title;
  document.getElementById('introDesc').textContent = meta.desc;
  document.getElementById('introRecord').textContent = meta.record;
  document.getElementById('introChamp').textContent = meta.champ;
  document.getElementById('introControls').innerHTML = meta.controls.map(c => `
    <div class="intro-control"><span>${c.keys.map(k => `<kbd>${k}</kbd>`).join('')}</span>${c.label}</div>
  `).join('');
  document.getElementById('introBtnLabel').textContent = isPractice ? 'START PRACTICE' : 'TAKE YOUR POSITION';
  this.setHudMode(id, isPractice);
  this.currentEvent = this.makeEvent(id);
}

makeEvent(id) {
  this.ensureFields();
  const options = { practice: this.pending?.type === 'practice' };
  if (id === 'sprint') return new SprintEvent(this, options);
  if (id === 'longjump') return new LongJumpEvent(this, options);
  return new JavelinEvent(this, options);
}

enterEvent() {
  if (this.state !== 'intro') return;
  this.hideScreens();
  this.sound.init();
  this.state = 'countdown';
  const id = this.currentEventId;
  this.countdown = {
    t: 0,
    step: 0,
    id,
    sprint: id === 'sprint',
    done: false
  };
  const cd = document.getElementById('countdown');
  cd.classList.add('is-active');
  const stage = document.getElementById('countdownStage');
  stage.classList.add('is-on');
  if (id === 'sprint') {
    this.setCountdown('ON YOUR MARKS', 'WAIT FOR THE GUN', '');
  } else {
    this.setCountdown('READY', 'THE RUNWAY IS YOURS', '');
  }
  this.sound.countBeep(false);
}

setCountdown(word, sub, cls = '') {
  const w = document.getElementById('countdownWord');
  const s = document.getElementById('countdownSub');
  if (!w) return;
  w.textContent = word;
  w.className = `countdown-word ${cls}`;
  s.textContent = sub;
}

updateCountdown(dt) {
  const c = this.countdown;
  if (!c) return;
  c.t += dt;
  if (c.sprint) {
    if (c.step === 0 && c.t > 1.02) {
      c.step = 1;
      this.setCountdown('SET', 'STEADY · DO NOT JUMP THE GUN', 'set');
      this.sound.countBeep(true);
    } else if (c.step === 1 && c.t > 1.95) {
      c.step = 2;
      this.fireGun();
    }
  } else {
    if (c.step === 0 && c.t > 0.88) {
      c.step = 1;
      this.setCountdown('SET', 'EYES ON THE LINE', 'set');
      this.sound.countBeep(true);
    } else if (c.step === 1 && c.t > 1.58) {
      c.step = 2;
      this.fireGo();
    }
  }
}

fireGun() {
  this.sound.gun();
  this.flashScreen(0.85);
  this.shake = 12;
  this.startRunning();
}

fireGo() {
  this.sound.tone(740, 0.18, 0.07, 'sine', 1050);
  this.setCountdown('GO', 'ATTACK THE RUNWAY', 'go');
  this.flashScreen(0.28);
  this.shake = 5;
  this.startRunning();
  this.goHideTimer = 0.42;
}

startRunning() {
  if (!this.currentEvent) return;
  this.state = 'running';
  this.showHUD();
  this.currentEvent.start();
  this.sound.setCrowd(0.027);
}

onFalseStartInput() {
  if (this.state !== 'countdown' || !this.countdown || this.countdown.step < 1) return;
  this.state = 'false-start';
  this.falseStartTimer = 0;
  this.setCountdown('FALSE START', 'RESETTING THE BLOCKS · STAY STILL', 'false');
  this.sound.falseStart();
  this.flashScreen(0.35);
  this.shake = 8;
  document.getElementById('countdown').classList.add('is-hot');
  setTimeout(() => document.getElementById('countdown').classList.remove('is-hot'), 420);
}

updateFalseStart(dt) {
  this.falseStartTimer += dt;
  if (this.falseStartTimer > 1.65) {
    this.state = 'countdown';
    this.countdown = { t: 0, step: 0, id: 'sprint', sprint: true, done: false };
    this.setCountdown('ON YOUR MARKS', 'WAIT FOR THE GUN', '');
    this.sound.countBeep(false);
  }
}

hideCountdown() {
  document.getElementById('countdown').classList.remove('is-active');
  document.getElementById('countdownStage').classList.remove('is-on');
}

/* ---------------------------------------------------------------- */
handleDirectional(side) {
  if (this.state === 'countdown' && this.currentEventId === 'sprint') {
    this.onFalseStartInput();
    return;
  }
  if (this.state !== 'running' || !this.currentEvent) return;
  if (this.currentEventId !== 'sprint') return;
  this.currentEvent.tap(side);
}

handleAction() {
  if (this.state !== 'running' || !this.currentEvent) return;
  if (this.currentEventId === 'sprint') return;
  this.currentEvent.tap();
}

tapFlash(side) {
  const btn = document.querySelector(`.tap-btn[data-tap="${side}"]`);
  if (btn) {
    btn.classList.add('is-hit');
    setTimeout(() => btn.classList.remove('is-hit'), 90);
  }
}

/* ---------------------------------------------------------------- */
paintWorld(mode, opts = {}) {
  const ctx = this.ctx;
  const w = this.world;
  w.mode = mode;
  if (this.currentEvent) {
    w.setCamera(this.currentEvent.camX, this.currentEvent.meter, this.currentEvent.anchor, mode);
  } else if (mode === 'menu') {
    w.setCamera(8 + Math.sin(this.menuT * 0.07) * 1.4, clamp(this.W / 24, 16, 54), 0.42, mode);
  } else {
    w.setCamera(12, clamp(this.W / 24, 16, 54), 0.42, mode);
  }
  w.playerLane = this.currentEvent?.playerLane ?? 3;
  w.drawSky(ctx, { mode });
  w.drawCity(ctx);
  w.drawRoof(ctx);
  w.drawCrowd(ctx);
  w.drawJumbotron(ctx, { ...(opts.jumbo || {}), mode });
  w.drawLedRibbon(ctx, { ribbon: opts.ribbon });
  w.drawGround(ctx, { mode });
  w.drawFloodlights(ctx);
  w.drawAtmosphere(ctx);
}

render() {
  const ctx = this.ctx;
  ctx.setTransform(this.dpr, 0, 0, this.dpr, 0, 0);
  ctx.clearRect(0, 0, this.W, this.H);
  const shake = this.shake;
  ctx.save();
  if (shake > 0.15) {
    ctx.translate(rand(-shake, shake) * 0.55, rand(-shake, shake) * 0.4);
  }

  if (this.state === 'menu' || (this.state === 'guide')) {
    this.renderMenu();
  } else if (this.state === 'intro') {
    if (this.currentEvent) this.currentEvent.render(ctx);
  } else if (this.state === 'countdown' || this.state === 'false-start' || this.state === 'running' || this.state === 'results' || this.paused) {
    if (this.currentEvent) this.currentEvent.render(ctx);
  } else if (this.state === 'ceremony') {
    this.renderCeremony();
  } else {
    this.renderMenu();
  }
  ctx.restore();

  this.particles.draw(ctx);

  if (this.state === 'ceremony') {
    this.world.drawFireworks(ctx);
  }
  if (!this.wasAnimating) this.wasAnimating = true;
}

renderMenu() {
  const ctx = this.ctx;
  this.paintWorld('menu', {
    jumbo: { top: 'OLYMPIA', big: 'OLYMPIA', sub: 'NIGHT SESSION', value: '20:26' }
  });
  const portrait = this.W < 760;
  const hx = this.W * (portrait ? 0.75 : 0.61);
  const gy = this.H * (portrait ? 0.80 : 0.815);
  const scale = clamp(this.H * (portrait ? 0.00205 : 0.00255), 1.2, 2.45);
  this.world.drawSpotlight(ctx, hx, gy - this.H * 0.22, this.H * (portrait ? 0.32 : 0.42), 1.05);
  // eclipse ring
  ctx.save();
  ctx.globalCompositeOperation = 'screen';
  const ring = ctx.createRadialGradient(hx, gy - this.H * 0.24, this.H * 0.12, hx, gy - this.H * 0.24, this.H * 0.34);
  ring.addColorStop(0, 'rgba(255,214,122,0)');
  ring.addColorStop(0.82, 'rgba(255,205,100,.022)');
  ring.addColorStop(1, 'rgba(255,205,100,0)');
  ctx.fillStyle = ring;
  ctx.fillRect(hx - this.H * 0.4, gy - this.H * 0.62, this.H * 0.8, this.H * 0.8);
  ctx.restore();
  drawAthlete(ctx, {
    x: hx, y: gy, scale,
    phase: this.menuT * 0.78,
    pose: 'victory',
    speed: 0,
    kit: KITS.player,
    flip: true,
    glow: 0.4,
    shadow: 1.15
  });
  // A slim golden light rim on the floor.
  ctx.save();
  ctx.globalCompositeOperation = 'screen';
  const floor = ctx.createRadialGradient(hx, gy + 4, 0, hx, gy + 4, 110 * scale);
  floor.addColorStop(0, 'rgba(247,201,80,.12)');
  floor.addColorStop(1, 'rgba(247,201,80,0)');
  ctx.fillStyle = floor;
  ctx.beginPath(); ctx.ellipse(hx, gy + 4, 110 * scale, 13 * scale, 0, 0, TAU); ctx.fill();
  ctx.restore();
}

renderCeremony() {
  const ctx = this.ctx;
  this.world.setCamera(16 + Math.sin(this.ceremonyT * 0.06) * 1.2, clamp(this.W / 24, 16, 54), 0.42, 'ceremony');
  this.paintWorld('ceremony', {
    jumbo: { top: 'OLYMPIA', big: 'PODIUM', sub: 'THE NIGHT SESSION', value: `${this.standings?.[0]?.total ?? 0} PTS` }
  });
  this.world.drawCeremonyPodium(ctx, this.standings || [], 'player', this.ceremonyT);
  this.world.drawFireworks(ctx);
  // extra stage glow
  ctx.save();
  ctx.globalCompositeOperation = 'screen';
  const g = ctx.createRadialGradient(this.W * 0.46, this.H * 0.7, 0, this.W * 0.46, this.H * 0.7, this.W * 0.3);
  g.addColorStop(0, 'rgba(255,215,125,.10)');
  g.addColorStop(1, 'rgba(255,200,100,0)');
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, this.W, this.H);
  ctx.restore();
}

/* ---------------------------------------------------------------- */
loop(now) {
  const dt = Math.min(0.05, Math.max(0.001, (now - this.last) / 1000));
  this.last = now;
  if (!this.paused) this.update(dt);
  this.render();
  requestAnimationFrame(this.loop);
}

update(dt) {
  this.menuT += dt;
  this.world.update(dt * (this.paused ? 0.22 : 1));
  this.particles.update(dt);
  this.shake *= Math.exp(-7.5 * dt);
  if (this.miniTimer > 0) this.miniTimer -= dt;

  switch (this.state) {
    case 'menu':
    case 'guide':
      break;
    case 'intro':
      if (this.currentEvent) this.currentEvent.phase += dt * 0.55;
      break;
    case 'countdown':
      this.updateCountdown(dt);
      break;
    case 'false-start':
      this.updateFalseStart(dt);
      break;
    case 'running':
      if (this.currentEvent) this.currentEvent.update(dt);
      if (this.goHideTimer > 0) {
        this.goHideTimer -= dt;
        if (this.goHideTimer <= 0) this.hideCountdown();
      }
      if (this.miniTimer <= 0) this.renderMiniBoard();
      this.applyHud();
      break;
    case 'results':
      if (this.miniTimer <= 0) this.renderMiniBoard();
      break;
    case 'ceremony':
      this.ceremonyT += dt;
      this.lastFirework -= dt;
      if (this.lastFirework <= 0) {
        this.lastFirework = rand(0.8, 1.7);
        this.world.addFirework(rand(this.W * 0.15, this.W * 0.85), rand(this.H * 0.12, this.H * 0.4));
        this.sound.setCrowd(0.035);
      }
      break;
    default:
      break;
  }
  if (this.state !== 'running' && this.miniTimer <= 0) this.renderMiniBoard();
}

/* ---------------------------------------------------------------- */
ensureFields() {
  if (this.fields) return;
  const f = { sprint: {}, longjump: {}, javelin: {} };
  for (const a of AI_DATA) {
    f.sprint[a.id] = Number((a.sprint + rand(-0.055, 0.055)).toFixed(2));
    f.longjump[a.id] = Number((a.longjump + rand(-0.09, 0.09)).toFixed(2));
    f.javelin[a.id] = Number((a.javelin + rand(-1.1, 1.1)).toFixed(1));
  }
  this.fields = f;
}
getField(id) {
  this.ensureFields();
  return this.fields[id];
}
fieldRank(id, mark) {
  if (!mark || mark <= 0) return 8;
  const field = this.getField(id);
  let rank = 1;
  for (const a of AI_DATA) {
    if (field[a.id] > mark) rank++;
  }
  return rank;
}
fieldBoard(id, live) {
  const field = this.getField(id);
  const rows = this.roster.map(a => ({
    id: a.id,
    name: a.name,
    code: a.code,
    player: !!a.player,
    value: a.player ? (live || this.bests[id] || 0) : field[a.id]
  })).sort((a, b) => b.value - a.value);
  return rows.map(r => ({
    ...r,
    value: r.value ? (id === 'longjump' || id === 'javelin' ? `${r.value.toFixed(2)}m` : fmtTime(r.value)) : '—'
  }));
}

/* ---------------------------------------------------------------- */
setHudMode(id, practice = false) {
  const hud = document.getElementById('hud');
  hud.classList.remove('is-sprint', 'is-field', 'is-javelin');
  hud.classList.add(id === 'sprint' ? 'is-sprint' : 'is-field');
  if (id === 'javelin') hud.classList.add('is-javelin');
  const meta = EVENTS[id];
  document.getElementById('hudEventNum').textContent = meta.num;
  document.getElementById('hudEventName').textContent = meta.name;
  document.getElementById('hudEventRound').textContent = practice ? 'PRACTICE RUN' : 'OLYMPIC FINAL';
  const hints = document.getElementById('keyHints');
  if (hints) {
    hints.innerHTML = id === 'sprint'
      ? '<span><kbd>A</kbd><kbd>D</kbd> ALTERNATE TO SPRINT</span><span><kbd>ESC</kbd> PAUSE</span>'
      : id === 'longjump'
        ? '<span><kbd>SPACE</kbd> TAP TO JUMP / EXTEND</span><span><kbd>ESC</kbd> PAUSE</span>'
        : '<span><kbd>SPACE</kbd> RELEASE THE SPEAR</span><span><kbd>ESC</kbd> PAUSE</span>';
  }
  const jc = document.getElementById('javelinCluster');
  if (jc) jc.classList.toggle('is-on', id === 'javelin');
  const ac = document.getElementById('actionControls');
  if (ac) ac.classList.toggle('is-on', id !== 'sprint');
  this.resetHud();
}

resetHud() {
  document.getElementById('hudClock').innerHTML = '0.00<span>s</span>';
  document.getElementById('clockLabel').textContent = 'RACE TIME';
  document.getElementById('hudPlace').textContent = '—';
  document.getElementById('meterFill').style.width = '0%';
  document.getElementById('meterValue').textContent = '0.0';
  document.getElementById('meterLabel').textContent = 'VELOCITY';
  const prompt = document.getElementById('hudPrompt');
  prompt.classList.remove('is-on');
  const action = document.getElementById('actionBtn');
  if (action) { action.disabled = false; action.classList.remove('is-hot'); }
  this.miniData = null;
  this.renderMiniBoard();
}

showHUD() {
  document.getElementById('hud').classList.add('is-active');
}
hideHUD() {
  document.getElementById('hud').classList.remove('is-active');
}

setHUD(data) {
  this.hudData = { ...(this.hudData || {}), ...data };
}

applyHud() {
  if (!this.hudData) return;
  const d = this.hudData;
  if (d.clock !== undefined) {
    const unit = d.clockUnit ? `<span>${d.clockUnit}</span>` : '';
    const next = `${d.clock}${unit}`;
    const el = document.getElementById('hudClock');
    if (el.innerHTML !== next) el.innerHTML = next;
  }
  if (d.clockLabel) document.getElementById('clockLabel').textContent = d.clockLabel;
  if (d.place !== undefined) {
    const n = Number(String(d.place).replace(/\D/g, ''));
    const next = n ? ordinal(n) : '—';
    const el = document.getElementById('hudPlace');
    if (el.textContent !== next) el.textContent = next;
  }
  if (d.meter !== undefined) {
    const pct = clamp((d.meter / (d.meterMax || 12)) * 100, 0, 100);
    document.getElementById('meterFill').style.width = `${pct.toFixed(1)}%`;
    document.getElementById('meterValue').textContent = (Math.round(d.meter * 10) / 10).toFixed(1);
  }
  if (d.meterUnit) document.querySelector('.meter-head small').textContent = d.meterUnit;
  if (d.meterLabel) document.getElementById('meterLabel').textContent = d.meterLabel;
  if (d.cadence !== undefined) {
    const dots = document.querySelectorAll('#cadenceOrbit i');
    dots.forEach((dot, i) => dot.classList.toggle('on', i < Math.round(d.cadence * 3)));
  }
  if (d.prompt) {
    const prompt = document.getElementById('hudPrompt');
    prompt.classList.toggle('is-on', !!d.prompt.visible);
    prompt.classList.toggle('pulse', !!d.prompt.pulse);
    if (d.prompt.visible) {
      if (d.prompt.key) document.getElementById('promptKey').textContent = d.prompt.key;
      if (d.prompt.title) document.getElementById('promptTitle').textContent = d.prompt.title;
      if (d.prompt.sub) document.getElementById('promptSub').textContent = d.prompt.sub;
    }
  }
  if (d.action !== undefined) {
    const action = document.getElementById('actionBtn');
    if (action) {
      action.classList.toggle('is-hot', !!d.actionHot);
      action.disabled = !!d.actionDisabled;
      if (d.actionLabel) document.getElementById('actionBtnLabel').textContent = d.actionLabel;
      if (d.actionSub) document.getElementById('actionBtnSub').textContent = d.actionSub;
    }
  }
  if (d.javelin) {
    this.updateAngleDial(d.angle ?? 36);
  }
}

updateAngleDial(value) {
  const knob = document.getElementById('angleKnob');
  if (!knob) return;
  const t = clamp((value - 15) / 42, 0, 1);
  const angle = (200 + t * 140) * Math.PI / 180;
  const cx = 90 + Math.cos(angle) * 92;
  const cy = 142 + Math.sin(angle) * 92;
  knob.setAttribute('cx', cx.toFixed(1));
  knob.setAttribute('cy', cy.toFixed(1));
  const read = document.getElementById('angleValue');
  if (read) read.textContent = `${Math.round(value)}°`;
}

setMiniBoard(rows, meta = '') {
  this.miniData = rows;
  this.miniMeta = meta;
  if (this.miniTimer <= 0) this.renderMiniBoard();
}

renderMiniBoard() {
  this.miniTimer = 0.18;
  const board = document.getElementById('miniBoard');
  if (!board) return;
  if (!this.miniData || !this.miniData.length || this.state === 'results' || this.state === 'ceremony') {
    board.classList.remove('is-on');
    return;
  }
  board.classList.add('is-on');
  document.getElementById('miniBoardMeta').textContent = this.miniMeta || '8 ATHLETES';
  const rows = this.miniData.slice(0, 8);
  document.getElementById('miniBoardRows').innerHTML = rows.map((r, i) => `
    <div class="mini-row ${r.player ? 'is-player' : ''} ${i === 0 ? 'is-leader' : ''}">
      <span class="pos">${i + 1}</span>
      <span class="who"><span class="flag">${r.code}</span><span class="name">${r.name}</span></span>
      <span class="score">${r.value}</span>
    </div>
  `).join('');
}

/* ---------------------------------------------------------------- */
completeEvent(id, mark, meta = {}) {
  const isPractice = this.pending?.type === 'practice';
  const rows = this.buildEventRows(id, mark);
  const playerIndex = rows.findIndex(r => r.player);
  const playerPlace = playerIndex + 1;
  const playerPoints = rows[playerIndex].points;
  const result = {
    id,
    mark,
    rows,
    place: playerPlace,
    points: playerPoints,
    practice: isPractice,
    meta
  };
  this.recordBest(id, mark);
  if (this.series) {
    this.series.totals.player += playerPoints;
    this.series.events.push(result);
    for (const r of rows) {
      if (r.place === 1) this.series.golds[r.id]++;
      if (r.place === 2) this.series.silvers[r.id]++;
      if (r.place === 3) this.series.bronzes[r.id]++;
    }
  }
  this.lastEvent = result;
  this.resultsMode = isPractice ? 'practice' : 'series';
  this.state = 'results';

    this.state = 'results';
    this.paused = false;
    this.hideHUD();
    this.hideCountdown();
    this.miniData = null;
    this.renderMiniBoard();
    this.showResults(result);
    this.particles.confetti(isPractice ? 18 : 38, this.W, this.H);
    this.flashScreen(0.2);
    this.sound.cheer(isPractice ? 0.5 : 0.9);
  }

  buildEventRows(id, mark) {
    const field = this.getField(id);
    const raw = this.roster.map(a => ({
      id: a.id,
      name: a.name,
      code: a.code,
      athlete: a,
      player: !!a.player,
      mark: a.player ? mark : field[a.id]
    }));
    raw.sort((a, b) => id === 'sprint' ? a.mark - b.mark : b.mark - a.mark);
    return raw.map((r, i) => ({
      ...r,
      place: i + 1,
      points: 8 - i,
      display: id === 'sprint' ? `${fmtTime(r.mark)} s` : `${fmtDist(r.mark)} m`,
      displayShort: id === 'sprint' ? fmtTime(r.mark) : fmtDist(r.mark)
    }));
  }

  recordBest(id, mark) {
    const old = this.bests[id];
    let better = false;
    if (id === 'sprint') better = !old || mark < old;
    else better = !old || mark > old;
    if (better) {
      this.bests[id] = mark;
      this.saveBests();
      this.updateMenuBest();
      setTimeout(() => this.toast(`NEW PERSONAL BEST — ${id === 'sprint' ? fmtTime(mark) + ' S' : fmtDist(mark) + ' M'}`, 'gold', 1500), 650);
    }
  }

  showResults(result) {
    this.hideScreens();
    const el = document.getElementById('results');
    el.classList.add('is-active');
    const meta = EVENTS[result.id];
    document.getElementById('resultsKicker').textContent = `EVENT ${meta.num} · ${result.practice ? 'PRACTICE' : 'FINAL'}`;
    document.getElementById('resultsTitle').textContent = meta.name;
    document.getElementById('resultsMark').textContent = result.id === 'sprint' ? fmtTime(result.mark) : fmtDist(result.mark);
    document.getElementById('resultsUnit').textContent = result.id === 'sprint' ? 'SECONDS' : 'METRES';
    const medal = document.getElementById('verdictMedal');
    medal.textContent = result.place;
    medal.className = `verdict-medal ${result.place === 1 ? '' : result.place === 2 ? 'silver' : result.place === 3 ? 'bronze' : 'plain'}`;
    document.getElementById('verdictPlace').textContent = `${ordinal(result.place).toUpperCase()} PLACE`;
    document.getElementById('verdictPoints').textContent = `+${result.points} POINTS`;
    document.getElementById('resultRows').innerHTML = result.rows.map(r => `
      <div class="result-row ${r.player ? 'is-player' : ''}">
        <span class="pos">${r.place}</span>
        <span class="athlete"><span class="code">${r.code}</span><span class="name">${r.name}</span></span>
        <span class="mark">${r.display}</span>
        <span class="pts">${r.points}</span>
      </div>
    `).join('');
    document.getElementById('resultNote').innerHTML = this.resultNote(result);
    document.getElementById('seriesMini').innerHTML = this.seriesMiniMarkup(result);
    const replay = document.querySelector('[data-action="results-replay"]');
    if (replay) replay.style.display = result.practice ? '' : 'none';
    const next = document.getElementById('resultsNextLabel');
    if (result.practice) next.textContent = 'TRY AGAIN';
    else if (this.series && this.series.events.length >= 3) next.textContent = 'THE MEDAL CEREMONY';
    else next.textContent = 'NEXT EVENT';
    setTimeout(() => {
      const panel = document.querySelector('.results-panel');
      if (panel) panel.scrollTop = 0;
    }, 30);
    this.sound.ui();
  }

  resultNote(result) {
    const name = EVENTS[result.id].name;
    if (result.practice) {
      return `<b>Practice run complete.</b> Your ${name.toLowerCase()} mark is in the books. Run it again to build the rhythm before the championship.`;
    }
    if (result.place === 1) {
      const notes = {
        sprint: '<b>Untouchable.</b> A devastating final 30 metres. The field is chasing shadows and the stadium is roaring.',
        longjump: '<b>Gold-standard flight.</b> The board, the arc, the landing — everything clicked when it mattered.',
        javelin: '<b>A spear from the gods.</b> The angle was pure and the crowd rose before it even landed.'
      };
      return notes[result.id];
    }
    if (result.place <= 3) {
      return `<b>On the podium.</b> A composed ${name.toLowerCase()} performance. There are more points on the table — and one event left to chase.`;
    }
    if (result.place <= 5) {
      return `<b>In the hunt.</b> The mark is respectable, but the leaders have opened a gap. A big next event can turn the campaign.`;
    }
    return `<b>Tough night.</b> The field is deep at this level. Reset, find the rhythm, and attack the next event with nothing to lose.`;
  }

  seriesMiniMarkup(result) {
    if (!this.series) {
      return '<div class="series-mini-head">PRACTICE SESSION</div><div class="series-mini-row current"><i></i>NO SERIES POINTS<B>—</B></div>';
    }
    const current = this.series.events.length;
    return `
      <div class="series-mini-head">CAMPAIGN · ${Math.min(this.series.totals.player, 24)} PTS</div>
      ${['sprint', 'longjump', 'javelin'].map((id, i) => {
        const done = this.series.events.find(e => e.id === id);
        const cls = done ? 'done' : current === i ? 'current' : '';
        return `<div class="series-mini-row ${cls}"><i></i>${EVENTS[id].name}<b>${done ? `+${done.points}` : current === i ? 'NEXT' : '—'}</b></div>`;
      }).join('')}
    `;
  }

  onResultsNext() {
    this.sound.ui();
    const result = this.lastEvent;
    if (!result) return;
    if (result.practice) {
      this.restartPractice();
      return;
    }
    if (this.series && this.series.events.length >= 3) {
      this.showCeremony();
    } else {
      this.series.index = this.series.events.length;
      const nextId = ['sprint', 'longjump', 'javelin'][this.series.index];
      this.showIntro(nextId);
    }
  }

  onResultsReplay() {
    if (!this.lastEvent?.practice) return;
    this.restartPractice();
  }

  restartPractice() {
    const id = this.lastEvent?.id || this.currentEventId || 'sprint';
    this.startPractice(id);
  }

  /* ---------------------------------------------------------------- */
  buildStandings() {
    if (!this.series) return [];
    return this.roster.map(a => ({
      ...a,
      total: this.series.totals[a.id],
      golds: this.series.golds[a.id],
      silvers: this.series.silvers[a.id],
      bronzes: this.series.bronzes[a.id]
    })).sort((a, b) =>
      b.total - a.total ||
      b.golds - a.golds ||
      b.silvers - a.silvers ||
      b.bronzes - a.bronzes ||
      a.name.localeCompare(b.name)
    );
  }

  showCeremony() {
    if (!this.series) return;
    this.state = 'ceremony';
    this.paused = false;
    this.hideHUD();
    this.hideCountdown();
    this.hideScreens();
    this.standings = this.buildStandings();
    const playerIndex = this.standings.findIndex(a => a.player);
    const place = playerIndex + 1;
    const isMedal = place <= 3;
    const medalName = place === 1 ? 'GOLD' : place === 2 ? 'SILVER' : place === 3 ? 'BRONZE' : null;
    document.getElementById('ceremony').classList.add('is-active');
    const title = document.getElementById('ceremonyTitle');
    title.innerHTML = medalName ? `${medalName}<br/><em>MEDAL</em>` : `${ordinal(place).toUpperCase()}<br/><em>PLACE</em>`;
    const sub = document.getElementById('ceremonySub');
    if (place === 1) sub.textContent = 'Champion of the night session. The stadium belongs to you.';
    else if (place === 2) sub.textContent = 'Olympic silver. One brilliant night, one relentless rival.';
    else if (place === 3) sub.textContent = 'Olympic bronze. A place on the podium and a night to remember.';
    else sub.textContent = `You finish ${ordinal(place)} overall. The podium was close — the next campaign starts now.`;
    const total = this.series.totals.player;
    if (total > this.scoreBest) {
      this.scoreBest = total;
      localStorage.setItem('olympia-best-score', String(total));
      this.updateMenuBest();
    }
    document.getElementById('finalBoard').innerHTML = `
      <div class="final-board-head"><span>FINAL STANDINGS</span><span>${total} PTS · YOU</span></div>
      ${this.standings.map((a, i) => `
        <div class="final-row ${a.player ? 'is-player' : ''}">
          <span class="place">${i + 1}</span>
          <span class="who"><span class="code">${a.code}</span><span class="name">${a.name}</span></span>
          <span class="total">${a.total}</span>
          <span class="medal-mini">${i === 0 ? '🥇' : i === 1 ? '🥈' : i === 2 ? '🥉' : ''}</span>
        </div>
      `).join('')}
    `;
    this.ceremonyT = 0;
    this.lastFirework = 0;
    this.particles.clear();
    this.particles.confetti(110, this.W, this.H);
    if (isMedal) {
      this.sound.fanfare();
      this.world.addFirework(this.W * 0.35, this.H * 0.25);
      this.world.addFirework(this.W * 0.65, this.H * 0.19);
      setTimeout(() => this.toast(`${medalName} MEDAL — ${total} POINTS`, 'gold', 2200), 500);
    } else {
      this.sound.cheer(0.8);
    }
  }

  /* ---------------------------------------------------------------- */
  openPause() {
    if (this.state !== 'running' || this.paused) return;
    this.paused = true;
    document.getElementById('pause').classList.add('is-active');
    this.sound.ui();
  }
  resume() {
    this.paused = false;
    document.getElementById('pause').classList.remove('is-active');
    this.sound.uiBack();
  }
  restartEvent() {
    const id = this.currentEventId;
    if (!id) return;
    this.paused = false;
    document.getElementById('pause').classList.remove('is-active');
    this.hideScreens();
    this.currentEvent = this.makeEvent(id);
    this.setHudMode(id, this.pending?.type === 'practice');
    this.state = 'countdown';
    this.countdown = { t: 0, step: 0, id, sprint: id === 'sprint', done: false };
    document.getElementById('countdown').classList.add('is-active');
    document.getElementById('countdownStage').classList.add('is-on');
    this.setCountdown(id === 'sprint' ? 'ON YOUR MARKS' : 'READY', id === 'sprint' ? 'WAIT FOR THE GUN' : 'THE RUNWAY IS YOURS', '');
    this.sound.countBeep(false);
  }
  quitEvent() {
    this.paused = false;
    document.getElementById('pause').classList.remove('is-active');
    this.showMenu();
  }

  openGuide() {
    this.sound.ui();
    document.getElementById('guide').classList.add('is-active');
    if (this.state === 'menu') this.state = 'guide';
  }
  closeGuide() {
    document.getElementById('guide').classList.remove('is-active');
    if (this.state === 'guide') this.state = 'menu';
  }

  showMenu() {
    this.state = 'menu';
    this.paused = false;
    this.series = null;
    this.fields = null;
    this.currentEvent = null;
    this.currentEventId = null;
    this.lastEvent = null;
    this.hudData = null;
    this.miniData = null;
    this.particles.clear();
    this.closeAllOverlays();
    this.hideScreens();
    document.getElementById('menu').classList.add('is-active');
    this.updateMenuBest();
    this.sound.setCrowd(0.018);
  }

  hideScreens() {
    ['menu', 'eventIntro', 'results', 'ceremony'].forEach(id => document.getElementById(id).classList.remove('is-active'));
    this.hideHUD();
    this.hideCountdown();
    document.getElementById('practiceMenu').classList.remove('is-active');
    document.getElementById('readyOverlay')?.classList.remove('is-active');
  }

  closeAllOverlays() {
    ['pause', 'guide', 'practiceMenu'].forEach(id => document.getElementById(id).classList.remove('is-active'));
  }

  /* ---------------------------------------------------------------- */
  spawnParticle(o) { this.particles.spawn(o); }
  burst(x, y, count, color, speed, life) { this.particles.burst(x, y, count, color, speed, life); }
  flashScreen(strength = 0.3) {
    const el = document.getElementById('flash');
    if (!el) return;
    el.style.opacity = String(clamp(strength, 0, 0.9));
    el.classList.remove('fire');
    void el.offsetWidth;
    el.classList.add('fire');
    clearTimeout(this.flashTimer);
    this.flashTimer = setTimeout(() => { el.classList.remove('fire'); el.style.opacity = '0'; }, 360);
  }
  toast(message, type = '', ms = 1300) {
    const el = document.getElementById('toast');
    if (!el) return;
    el.textContent = message;
    el.className = `toast is-on ${type || ''}`;
    clearTimeout(this.toastTimer);
    this.toastTimer = setTimeout(() => el.classList.remove('is-on'), ms);
  }
  groundY(lane, mode) { return this.world.groundY(lane, mode); }
}

const game = new Game();
window.__olympia = game;

import { clamp, lerp, smoothstep, rand, fmtTime, fmtDist } from './utils.js';
import { drawAthlete } from './athlete.js';

const AI_LANES = [0, 1, 2, 4, 5, 6, 7];

class BaseEvent {
  constructor(game, id, options = {}) {
    this.game = game;
    this.id = id;
    this.practice = !!options.practice;
    this.world = game.world;
    this.state = 'ready';
    this.ended = false;
    this.camX = -10;
    this.meter = 45;
    this.anchor = 0.4;
    this.phase = 0;
    this.field = game.getField(id);
    this.particles = [];
    this.jumbo = { top: 'OLYMPIA', big: '100M', sub: 'FINAL', value: '0.00' };
  }
  get W() { return this.game.W; }
  get H() { return this.game.H; }
  get ctx() { return this.game.ctx; }
  setCamera(meter, anchor) {
    this.meter = meter;
    this.anchor = anchor;
  }
  updateCamera(dt, targetX, extra = 0) {
    const meter = clamp(this.W / 24, 16, 54);
    const anchor = this.W < 720 ? 0.42 : 0.4;
    this.meter = lerp(this.meter, meter, 1 - Math.exp(-2.4 * dt));
    this.anchor = lerp(this.anchor, anchor, 1 - Math.exp(-2 * dt));
    const targetCam = targetX - (this.W * this.anchor) / this.meter + extra;
    this.camX = lerp(this.camX, targetCam, 1 - Math.exp(-3.2 * dt));
    this.world.setCamera(this.camX, this.meter, this.anchor, this.id);
  }
  paint(extra = {}) {
    this.game.paintWorld(this.id, {
      jumbo: this.jumbo,
      ribbon: extra.ribbon
    });
  }
  hud(data) {
    this.game.setHUD(data);
  }
  done(mark, meta = {}) {
    if (this.ended) return;
    this.ended = true;
    this.game.completeEvent(this.id, mark, { ...meta, practice: this.practice });
  }
}

/* ================================================================== */
/*  100M SPRINT                                                        */
/* ================================================================== */
export class SprintEvent extends BaseEvent {
  constructor(game, options = {}) {
    super(game, 'sprint', options);
    this.playerLane = 3;
    this.raceTime = 0;
    this.finishDelay = 0;
    this.auto = false;
    this.player = null;
    this.runners = [];
    this.buildRunners();
    this.camX = -(this.W * 0.415) / clamp(this.W / 24, 16, 54);
    this.meter = clamp(this.W / 24, 16, 54);
    this.anchor = 0.415;
    this.jumbo = { top: 'OLYMPIA', big: '100M', sub: 'FINAL', value: '0.00' };
    this.lastPhase = 0;
    this.liveRank = 8;
  }

  buildRunners() {
    const roster = this.game.roster;
    let laneIndex = 0;
    this.runners = roster.map((athlete) => {
      const isPlayer = !!athlete.player;
      const lane = isPlayer ? 3 : AI_LANES[laneIndex++];
      const targetTime = isPlayer ? null : this.field[athlete.id];
      const r = {
        athlete,
        isPlayer,
        lane,
        dist: 0,
        speed: 0,
        phase: rand(0, Math.PI * 2),
        finished: false,
        time: null,
        targetTime,
        targetSpeed: targetTime ? 100 / Math.max(0.1, targetTime - 0.375) : 0
      };
      if (isPlayer) this.player = r;
      return r;
    });
  }

  start() {
    this.state = 'running';
    this.raceTime = 0;
    this.game.sound.setCrowd(0.028);
    this.hudFlash();
  }

  hudFlash() {
    this.game.setHUD({ prompt: { visible: false } });
  }

  tap(side) {
    if (this.state !== 'running' || this.player.finished) return;
    const p = this.player;
    const t = this.raceTime;
    if (t - p.lastTap < 0.055) return;
    if (t - p.lastTap > 0.32) p.speed *= 0.97;
    const valid = side !== p.lastSide;
    if (valid) {
      if (!p.started) {
        p.started = true;
        p.speed += 2.2;
        p.reaction = t;
      }
      p.auto = false;
      const boost = 0.55 * Math.max(0, 1 - p.speed / 13) + 0.08;
      p.speed += boost;
      p.taps++;
      p.lastSide = side;
      p.lastTap = t;
      this.game.sound.step(clamp(p.speed / 12, 0.2, 1));
      this.game.tapFlash(side);
      this.game.spawnParticle({
        x: this.game.W * 0.5 + rand(-60, 60),
        y: this.game.groundY(this.playerLane, 'sprint') - rand(4, 20),
        vx: rand(-30, 10), vy: rand(-20, -5), life: rand(0.2, 0.45),
        size: rand(1, 3), color: 'rgba(255,226,177,.32)', gravity: 8
      });
    } else {
      p.lastTap = t;
      p.speed *= 0.93;
    }
  }

  update(dt) {
    this.phase += dt;
    if (this.state !== 'running') return;
    this.raceTime += dt;

    const p = this.player;
    // Graceful fallback: nobody gets stuck at the start forever.
    if (!p.started && this.raceTime > 3.4) {
      p.started = true;
      p.auto = true;
      p.speed = 5.1;
      p.reaction = this.raceTime;
    }

    // Player physics: taps provide impulse, air / stride drag bleeds it away.
    if (p.started) {
      if (p.auto) p.speed = Math.max(p.speed, 5.1);
      p.speed *= Math.exp(-0.10 * dt);
      p.dist += p.speed * dt;
      p.phase += p.speed * 1.06 * dt;
      if (p.dist >= 100 && !p.finished) {
        p.finished = true;
        p.time = this.raceTime - (p.dist - 100) / Math.max(0.01, p.speed);
        p.dist = 100;
        this.state = 'finished';
        this.game.shake = Math.max(this.game.shake, 5);
        this.game.sound.cheer(1.1);
        this.game.toast('FINISH', 'gold', 900);
      }
    }

    for (const r of this.runners) {
      if (r.isPlayer || r.finished) continue;
      const speed = r.targetSpeed * smoothstep(0, 0.75, this.raceTime);
      r.speed = speed;
      r.dist += speed * dt;
      r.phase += speed * 1.04 * dt;
      if (r.dist >= 100) {
        r.finished = true;
        r.time = this.raceTime - (r.dist - 100) / Math.max(0.01, speed);
        r.dist = 100;
      }
    }

    const allDone = this.runners.every(r => r.finished);
    if (p.finished && (allDone || this.finishDelay > 1.35)) {
      this.finishDelay += dt;
      if (this.finishDelay > 1.35) {
        this.state = 'done';
        this.done(p.time, { placeHint: this.liveRank });
        return;
      }
    }

    this.updateCamera(dt, p.dist, 1.1);
    this.updateLive(dt);
    this.spawnFootDust(dt);
  }

  updateLive(dt) {
    const order = [...this.runners].sort((a, b) => {
      if (a.finished && b.finished) return a.time - b.time;
      return b.dist - a.dist;
    });
    this.liveRank = order.findIndex(r => r.isPlayer) + 1;
    this.game.setMiniBoard(
      order.map(r => ({
        id: r.athlete.id,
        name: r.athlete.name,
        code: r.athlete.code,
        player: r.isPlayer,
        value: r.finished ? fmtTime(r.time) : `${r.dist.toFixed(1)}m`
      })),
      'LIVE ORDER'
    );
    const next = this.player.lastSide === 'left' ? 'D' : 'A';
    const cadence = this.player.started ? clamp((this.player.speed - 4) / 8, 0, 1) : 0;
    this.hud({
      clock: fmtTime(this.raceTime),
      clockUnit: 's',
      clockLabel: 'RACE TIME',
      place: this.player.finished ? String(this.liveRank) : String(this.liveRank),
      meter: this.player.speed,
      meterMax: 13.2,
      meterUnit: 'M/S',
      meterLabel: 'VELOCITY',
      prompt: this.player.finished ? { visible: false } : {
        visible: true,
        key: next,
        title: this.player.started ? 'KEEP THE CADENCE' : 'EXPLODE FROM THE BLOCKS',
        sub: `Alternate ${this.player.lastSide === 'left' ? 'D' : 'A'} / ${next} — ${Math.round(this.player.speed * 10) / 10} m/s`,
        pulse: true
      },
      cadence,
      action: false
    });
  }

  spawnFootDust() {
    const p = this.player;
    if (!p.started || p.speed < 3.5) return;
    const crossed = Math.floor(p.phase / Math.PI);
    if (crossed !== this.lastPhase) {
      this.lastPhase = crossed;
      const x = this.world.sx(p.dist) - 12;
      const y = this.game.groundY(this.playerLane, 'sprint');
      for (let i = 0; i < 2; i++) {
        this.game.spawnParticle({
          x: x + rand(-12, 12), y: y - rand(0, 5),
          vx: rand(-50, -8), vy: rand(-34, -6), life: rand(0.28, 0.6),
          size: rand(1.4, 4.2), color: `rgba(255,214,154,${rand(0.12, 0.27)})`,
          gravity: 30, drag: 0.5
        });
      }
    }
  }

  render(ctx) {
    this.world.playerLane = this.playerLane;
    this.paint();
    const order = [...this.runners].sort((a, b) => a.lane - b.lane);
    for (const r of order) {
      const x = this.world.sx(r.dist);
      if (x < -100 || x > this.W + 130) continue;
      const y = this.game.groundY(r.lane, 'sprint');
      const scale = this.world.laneScale(r.lane, 'sprint') * (r.isPlayer ? 1.03 : 1);
      let pose = 'run';
      if (this.state === 'ready' || this.game.state === 'countdown') pose = 'set';
      if (this.game.state === 'false-start') pose = 'set';
      if (r.finished && r.speed < 1.5) pose = 'idle';
      drawAthlete(ctx, {
        x, y, scale,
        phase: r.phase,
        pose,
        speed: clamp(r.speed / 12, 0, 1),
        kit: r.athlete.kit,
        glow: r.isPlayer ? 0.18 : 0.04,
        shadow: r.isPlayer ? 1.15 : 0.9,
        number: r.isPlayer ? 7 : 7
      });
      if (r.isPlayer && this.state !== 'ready') {
        this.drawPlayerTag(ctx, x, y, scale, r);
      }
    }
    // Motion streaks for top speed.
    if (this.player.speed > 8.5) {
      const p = this.player;
      const x = this.world.sx(p.dist);
      const y = this.game.groundY(this.playerLane, 'sprint');
      ctx.save();
      ctx.globalCompositeOperation = 'screen';
      for (let i = 0; i < 7; i++) {
        const yy = y - 20 - i * 11 - rand(0, 8);
        const len = 28 + rand(0, 55) + p.speed * 2;
        const a = 0.018 + (p.speed - 8.5) * 0.013;
        const grad = ctx.createLinearGradient(x - len, yy, x + 12, yy);
        grad.addColorStop(0, 'rgba(255,236,185,0)');
        grad.addColorStop(0.7, `rgba(255,218,148,${a})`);
        grad.addColorStop(1, 'rgba(255,245,216,0)');
        ctx.strokeStyle = grad;
        ctx.lineWidth = 1 + rand(0, 1.7);
        ctx.beginPath(); ctx.moveTo(x - len, yy); ctx.lineTo(x + 20, yy); ctx.stroke();
      }
      ctx.restore();
    }
    this.drawFinishAtmosphere(ctx);
  }

  drawPlayerTag(ctx, x, y, scale, r) {
    const top = y - 132 * scale;
    ctx.save();
    ctx.globalAlpha = 0.92;
    ctx.fillStyle = 'rgba(4,10,20,.72)';
    ctx.strokeStyle = 'rgba(247,201,80,.38)';
    ctx.lineWidth = 1;
    const text = 'YOU';
    ctx.font = '700 8px "Barlow Condensed", sans-serif';
    const w = ctx.measureText(text).width + 14;
    ctx.beginPath();
    if (ctx.roundRect) ctx.roundRect(x - w / 2, top - 16, w, 13, 2); else ctx.rect(x - w / 2, top - 16, w, 13);
    ctx.fill(); ctx.stroke();
    ctx.fillStyle = '#f7c950';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillText(text, x, top - 9.5);
    ctx.restore();
  }

  drawFinishAtmosphere(ctx) {
    const x = this.world.sx(100);
    if (x < -60 || x > this.W + 60) return;
    const grad = ctx.createRadialGradient(x, this.H * 0.77, 0, x, this.H * 0.77, this.H * 0.27);
    grad.addColorStop(0, 'rgba(247,201,80,.07)');
    grad.addColorStop(1, 'rgba(247,201,80,0)');
    ctx.save();
    ctx.globalCompositeOperation = 'screen';
    ctx.fillStyle = grad;
    ctx.beginPath(); ctx.arc(x, this.H * 0.77, this.H * 0.27, 0, Math.PI * 2); ctx.fill();
    ctx.restore();
  }
}

/* ================================================================== */
/*  LONG JUMP                                                          */
/* ================================================================== */
export class LongJumpEvent extends BaseEvent {
  constructor(game, options = {}) {
    super(game, 'longjump', options);
    this.meter = clamp(this.W / 24, 16, 52);
    this.anchor = 0.37;
    this.camX = -(this.W * 0.37) / this.meter;
    this.x = 0;
    this.runTime = 0;
    this.speed = 0;
    this.phase = rand(0, 6);
    this.state = 'ready';
    this.quality = 0;
    this.baseDistance = 0;
    this.extension = 0;
    this.extended = false;
    this.flightT = 0;
    this.flightDur = 1;
    this.takeoffX = 0;
    this.landingX = 0;
    this.result = 0;
    this.peak = 0;
    this.landTimer = 0;
    this.jumbo = { top: 'OLYMPIA', big: 'JUMP', sub: 'FINAL', value: '0.00' };
    this.lastPhase = 0;
    this.liveRank = 8;
  }

  start() {
    this.state = 'run';
    this.runTime = 0;
    this.game.sound.setCrowd(0.024);
  }

  tap() {
    if (this.state === 'run') {
      this.jump();
    } else if (this.state === 'flight' && !this.extended) {
      const u = this.flightT / this.flightDur;
      if (u > 0.35 && u < 0.7) {
        this.extended = true;
        this.extension = 0.42;
        this.game.sound.tone(760, 0.12, 0.05, 'sine', 1040);
        this.game.toast('EXTENDED — +0.42 M', 'gold', 1100);
        const sx = this.world.sx(this.x);
        const sy = this.game.groundY(1, 'longjump') - this.peak * Math.sin(Math.PI * u);
        this.game.burst(sx, sy, 10, '#f7c950', 120, 0.5);
      } else {
        this.extended = true;
        this.game.toast(u <= 0.35 ? 'TOO EARLY TO EXTEND' : 'TOO LATE TO EXTEND', 'red', 900);
      }
    }
  }

  jump(auto = false) {
    if (this.state !== 'run') return;
    const x = this.x;
    let q;
    if (x >= 38.1 && x <= 39.9) {
      q = 1 - Math.abs(x - 39.0) / 1.3 * 0.12;
    } else if (x < 38.1) {
      q = clamp(0.22 + Math.max(0, x - 31) / 7.1 * 0.55, 0.22, 0.77);
    } else if (x <= 40.6) {
      q = 0.58;
    } else {
      q = 0.34;
    }
    if (auto) q = Math.min(q, 0.32);
    this.quality = q;
    this.takeoffX = x;
    this.baseDistance = 3.65 + this.speed * 0.337 + q * 1.18;
    this.result = this.baseDistance;
    const visual = Math.max(3.6, this.baseDistance);
    this.landingX = 40 + visual + 0.42;
    this.peak = this.H * (0.055 + clamp(this.speed / 12, 0, 1) * 0.04);
    this.flightDur = clamp(0.62 + this.baseDistance * 0.038, 0.86, 1.1);
    this.flightT = 0;
    this.state = 'flight';
    this.game.sound.jump();
    this.game.shake = Math.max(this.game.shake, 2.5);
    this.game.toast(x < 38.1 ? 'EARLY TAKEOFF' : x > 40.3 ? 'OVERSTEP' : 'CLEAN TAKEOFF', x < 38.1 || x > 40.3 ? 'red' : 'gold', 700);
  }

  update(dt) {
    this.phase += dt;
    if (this.state === 'ready') return;
    if (this.state === 'run') {
      this.runTime += dt;
      this.speed = 10.7 * smoothstep(0, 3.7, this.runTime);
      this.x += this.speed * dt;
      this.phase += this.speed * 0.96 * dt;
      if (this.x > 40.9) this.jump(true);
      this.updateCamera(dt, this.x, 3.2);
      this.spawnDust();
    } else if (this.state === 'flight') {
      this.flightT += dt;
      const u = clamp(this.flightT / this.flightDur, 0, 1);
      this.x = lerp(this.takeoffX, this.landingX, u);
      this.phase += 2.4 * dt;
      this.updateCamera(dt, this.x, 2.5);
      if (u >= 1) this.land();
    } else if (this.state === 'landed') {
      this.landTimer += dt;
      this.updateCamera(dt, this.landingX, 1.8);
      if (this.landTimer > 1.55) {
        this.state = 'done';
        this.done(this.result, { quality: this.quality, extended: this.extended });
      }
    }

    this.liveRank = 1 + this.game.fieldRank('longjump', this.state === 'landed' ? this.result : this.baseDistance);
    this.jumbo.value = this.state === 'landed' ? `${this.result.toFixed(2)}` : this.state === 'flight' ? 'AIR' : '0.00';
    this.hudState();
  }

  hudState() {
    const toBoard = Math.max(0, 40 - this.x);
    const clockValue = this.state === 'landed'
      ? fmtDist(this.result)
      : toBoard > 0 ? toBoard.toFixed(1) : 'BOARD';
    const clockUnit = this.state === 'landed' ? 'm' : toBoard > 0 ? 'm' : '';
    let prompt;
    if (this.state === 'run') {
      if (this.x < 30) prompt = { key: '↑', title: 'BUILD SPEED', sub: 'Stay relaxed — the board is coming', pulse: false };
      else if (this.x < 37.6) prompt = { key: '↑', title: 'FIND THE BOARD', sub: 'Tap as you enter the glowing zone', pulse: false };
      else prompt = { key: '↑', title: 'TAKE OFF NOW', sub: 'Hit the board cleanly', pulse: true };
    } else if (this.state === 'flight') {
      prompt = this.extended
        ? { key: '✓', title: 'EXTENSION LOCKED', sub: 'Ride the arc into the sand', pulse: false }
        : { key: '↑', title: 'TAP TO EXTEND', sub: 'Strike at the top of the flight', pulse: true };
    } else if (this.state === 'landed') {
      prompt = { key: '✓', title: 'MARK SET', sub: `${this.result.toFixed(2)} metres`, pulse: false };
    } else {
      prompt = { visible: false };
    }
    this.hud({
      clock: clockValue,
      clockUnit,
      clockLabel: this.state === 'landed' ? 'MEASURED' : 'TO BOARD',
      place: `${this.game.fieldRank('longjump', this.state === 'landed' ? this.result : this.baseDistance)}`,
      meter: this.speed,
      meterMax: 11.5,
      meterUnit: 'M/S',
      meterLabel: 'RUNWAY SPEED',
      prompt: { visible: true, ...prompt },
      action: true,
      actionLabel: this.state === 'flight' ? (this.extended ? 'LOCKED' : 'EXTEND') : 'JUMP',
      actionSub: this.state === 'flight' ? 'SPACE / TAP' : 'TAKE OFF',
      actionHot: this.state === 'run' ? (this.x > 37.5 && this.x < 40.1) : (this.state === 'flight' && !this.extended && this.flightT / this.flightDur > 0.3 && this.flightT / this.flightDur < 0.72),
      actionDisabled: this.state === 'landed' || (this.state === 'flight' && this.extended)
    });
    this.game.setMiniBoard(
      this.game.fieldBoard('longjump', this.state === 'landed' ? this.result : null),
      'FIELD ORDER'
    );
  }

  spawnDust() {
    if (this.speed < 3) return;
    const crossed = Math.floor(this.phase / Math.PI);
    if (crossed !== this.lastPhase) {
      this.lastPhase = crossed;
      const x = this.world.sx(this.x) - 10;
      const y = this.game.groundY(1, 'longjump');
      this.game.spawnParticle({
        x, y: y - 2, vx: rand(-45, -10), vy: rand(-25, -5), life: rand(0.3, 0.6),
        size: rand(1.2, 3.5), color: 'rgba(255,216,160,.26)', gravity: 30
      });
    }
  }

  land() {
    this.state = 'landed';
    this.result = this.baseDistance + this.extension;
    this.x = this.landingX;
    this.landTimer = 0;
    this.game.sound.sand(1);
    this.game.sound.cheer(0.8);
    this.game.shake = Math.max(this.game.shake, 4);
    const sx = this.world.sx(this.landingX);
    const gy = this.game.groundY(1, 'longjump');
    this.game.burst(sx, gy - 5, 26, '#cba465', 170, 0.8);
    this.game.burst(sx, gy - 5, 12, '#f7dfaa', 120, 0.55);
  }

  render(ctx) {
    this.paint();
    const ground = this.game.groundY(1, 'longjump');
    const scale = this.world.laneScale(1, 'longjump');
    const sx = this.world.sx(this.x);
    let y = ground;
    let pose = 'run';
    let height = 0;
    let alpha = 1;
    if (this.state === 'ready') { pose = 'idle'; }
    if (this.state === 'flight') {
      const u = clamp(this.flightT / this.flightDur, 0, 1);
      height = this.peak * Math.sin(Math.PI * u);
      y = ground - height;
      pose = 'jump';
    } else if (this.state === 'landed') {
      pose = 'land';
    }

    // shadow shrinks in the air
    if (height > 0) {
      ctx.save();
      ctx.globalAlpha = clamp(1 - height / (this.H * 0.25), 0.15, 0.6);
    }
    drawAthlete(ctx, {
      x: sx, y: y, scale, phase: this.phase, pose,
      speed: clamp(this.speed / 11, 0, 1), kit: this.game.playerKit,
      glow: 0.16, shadow: height > 0 ? 0.5 : 1
    });
    if (height > 0) ctx.restore();

    if (this.state === 'flight') {
      this.drawTrajectory(ctx, ground, scale);
    }
    if (this.state === 'landed') {
      this.drawMeasurement(ctx, ground, scale);
    }
    this.drawAthleteAura(ctx, sx, y, scale);
  }

  drawAthleteAura(ctx, x, y, scale) {
    const g = ctx.createRadialGradient(x, y - 60 * scale, 0, x, y - 60 * scale, 95 * scale);
    g.addColorStop(0, 'rgba(255,213,130,.045)');
    g.addColorStop(1, 'rgba(255,213,130,0)');
    ctx.save();
    ctx.globalCompositeOperation = 'screen';
    ctx.fillStyle = g;
    ctx.fillRect(x - 120 * scale, y - 190 * scale, 240 * scale, 200 * scale);
    ctx.restore();
  }

  drawTrajectory(ctx, ground, scale) {
    const start = this.world.sx(this.takeoffX);
    const end = this.world.sx(this.landingX);
    ctx.save();
    ctx.globalAlpha = 0.33;
    ctx.strokeStyle = 'rgba(247,201,80,.7)';
    ctx.lineWidth = 1;
    ctx.setLineDash([4, 7]);
    ctx.beginPath();
    for (let i = 0; i <= 20; i++) {
      const u = i / 20;
      const x = lerp(start, end, u);
      const y = ground - this.peak * Math.sin(Math.PI * u) - 50 * scale;
      i === 0 ? ctx.moveTo(x, y) : ctx.lineTo(x, y);
    }
    ctx.stroke();
    ctx.restore();
  }

  drawMeasurement(ctx, ground, scale) {
    const boardX = this.world.sx(40);
    const landX = this.world.sx(40 + this.result);
    const y = ground + 12;
    ctx.save();
    ctx.strokeStyle = 'rgba(247,201,80,.85)';
    ctx.lineWidth = 1.4;
    ctx.beginPath(); ctx.moveTo(boardX, y); ctx.lineTo(landX, y); ctx.stroke();
    ctx.fillStyle = 'rgba(247,201,80,.8)';
    for (let x = boardX; x <= landX; x += 12) ctx.fillRect(x, y - 3, 1, 6);
    ctx.fillStyle = 'rgba(5,11,22,.86)';
    ctx.strokeStyle = 'rgba(247,201,80,.55)';
    ctx.beginPath();
    if (ctx.roundRect) ctx.roundRect(landX - 25, y - 25, 50, 17, 2); else ctx.rect(landX - 25, y - 25, 50, 17);
    ctx.fill(); ctx.stroke();
    ctx.fillStyle = '#f7c950';
    ctx.font = '700 10px "Barlow Condensed", sans-serif';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillText(`${this.result.toFixed(2)}m`, landX, y - 16.5);
    ctx.restore();
  }
}

/* ================================================================== */
/*  JAVELIN                                                            */
/* ================================================================== */
export class JavelinEvent extends BaseEvent {
  constructor(game, options = {}) {
    super(game, 'javelin', options);
    this.meter = clamp(this.W / 24, 16, 52);
    this.anchor = 0.37;
    this.camX = -(this.W * 0.37) / this.meter;
    this.x = 0;
    this.runTime = 0;
    this.speed = 0;
    this.phase = rand(0, 6);
    this.angle = 36;
    this.angleTime = 0;
    this.state = 'ready';
    this.result = 0;
    this.flightT = 0;
    this.flightDur = 3.6;
    this.startX = 0;
    this.landX = 36;
    this.peak = 0;
    this.landTimer = 0;
    this.releaseScore = 1;
    this.angleScore = 1;

    this.angleScore = 1;
    this.jumbo = { top: 'OLYMPIA', big: 'JAVELIN', sub: 'FINAL', value: '0.00' };
    this.lastPhase = 0;
    this.trail = [];
    this.liveRank = 8;
  }

  start() {
    this.state = 'run';
    this.runTime = 0;
    this.game.sound.setCrowd(0.023);
  }

  tap() {
    if (this.state === 'run') this.throwSpear();
  }

  throwSpear(auto = false) {
    if (this.state !== 'run') return;
    const x = this.x;
    this.releaseScore = 1 - clamp((36 - x) / 13, 0, 1) * 0.6;
    this.angleScore = 1 - clamp(Math.abs(this.angle - 36) / 22, 0, 1) * 0.85;
    const precision = Math.max(0, 1 - Math.abs(this.angle - 36) / 4) * 0.8
      + Math.max(0, 1 - Math.abs(36 - x) / 1.6) * 0.5;
    const speedFactor = clamp(this.speed / 10.9, 0, 1);
    this.result = 54.5 + 34.5 * this.releaseScore * this.angleScore * (0.78 + 0.22 * speedFactor) + precision + rand(-0.45, 0.45);
    if (auto) this.result *= 0.88;
    this.result = clamp(this.result, 45, 93.4);
    this.startX = x + 1.2;
    this.landX = 36 + this.result;
    this.peak = this.H * (0.12 + this.result / 450);
    this.flightDur = 3.1 + this.result * 0.007;
    this.flightT = 0;
    this.state = 'flight';
    this.trail = [];
    this.game.sound.javelinThrow();
    this.game.shake = Math.max(this.game.shake, 6);
    this.game.flashScreen(0.22);
    this.game.toast(
      auto ? 'LATE RELEASE' : Math.abs(this.angle - 36) < 4 ? 'PERFECT ANGLE' : 'SPEAR AWAY',
      Math.abs(this.angle - 36) < 4 ? 'gold' : '', 850
    );
    // Camera expands to follow the whole throw.
    this.camX = (this.startX + this.landX) / 2 - (this.W * 0.5) / this.meter;
  }

  update(dt) {
    this.phase += dt;
    if (this.state === 'ready') return;
    if (this.state === 'run') {
      this.runTime += dt;
      this.angleTime += dt;
      this.angle = 36 + 21 * Math.sin(this.angleTime * 3.55 - 0.9);
      this.speed = 10.9 * smoothstep(0, 3.5, this.runTime);
      this.x += this.speed * dt;
      this.phase += this.speed * 0.92 * dt;
      if (this.x >= 36.35) {
        this.x = 36.2;
        this.throwSpear(true);
      }
      this.updateCamera(dt, this.x, 3.8);
      this.spawnDust();
    } else if (this.state === 'flight') {
      this.flightT += dt;
      const u = clamp(this.flightT / this.flightDur, 0, 1);
      this.x = lerp(this.startX, this.landX, u);
      const targetMeter = clamp(this.W / 102, 8.2, 18);
      this.meter = lerp(this.meter, targetMeter, 1 - Math.exp(-1.4 * dt));
      const targetCam = (this.startX + this.landX) / 2 - (this.W * 0.5) / this.meter;
      this.camX = lerp(this.camX, targetCam, 1 - Math.exp(-1.8 * dt));
      this.anchor = lerp(this.anchor, 0.5, 1 - Math.exp(-1.6 * dt));
      this.world.setCamera(this.camX, this.meter, this.anchor, 'javelin');
      if (u >= 1) this.land();
    } else if (this.state === 'landed') {
      this.landTimer += dt;
      const targetCam = (this.startX + this.landX) / 2 - (this.W * 0.5) / this.meter;
      this.camX = lerp(this.camX, targetCam, 1 - Math.exp(-1.2 * dt));
      this.world.setCamera(this.camX, this.meter, this.anchor, 'javelin');
      if (this.landTimer > 1.8) {
        this.state = 'done';
        this.done(this.result, { angle: this.angle, release: this.releaseScore });
        return;
      }
    }
    this.liveRank = 1 + this.game.fieldRank('javelin', this.state === 'landed' ? this.result : 0);
    this.jumbo.value = this.state === 'landed' ? this.result.toFixed(1) : this.state === 'flight' ? `${this.angle.toFixed(0)}°` : '0.00';
    this.hudState();
  }

  hudState() {
    const toLine = Math.max(0, 36 - this.x);
    const clockValue = this.state === 'landed' ? fmtDist(this.result, 1) : toLine.toFixed(1);
    const clockUnit = this.state === 'landed' ? 'm' : 'm';
    let prompt;
    if (this.state === 'run') {
      prompt = {
        key: '↑', title: 'RELEASE AT THE LINE',
        sub: `Arm angle ${this.angle.toFixed(0)}° — find the gold band`,
        pulse: Math.abs(this.angle - 36) < 5
      };
    } else if (this.state === 'flight') {
      prompt = { key: '✓', title: 'THE SPEAR IS FLYING', sub: 'The stadium is watching', pulse: false };
    } else if (this.state === 'landed') {
      prompt = { key: '✓', title: 'DISTANCE MEASURED', sub: `${this.result.toFixed(2)} metres`, pulse: false };
    } else {
      prompt = { visible: false };
    }
    this.hud({
      clock: clockValue,
      clockUnit,
      clockLabel: this.state === 'landed' ? 'MEASURED' : 'TO FOUL LINE',
      place: `${this.game.fieldRank('javelin', this.state === 'landed' ? this.result : 0)}`,
      meter: this.speed,
      meterMax: 11.5,
      meterUnit: 'M/S',
      meterLabel: 'APPROACH',
      prompt: { visible: true, ...prompt },
      action: true,
      actionLabel: this.state === 'flight' || this.state === 'landed' ? 'FLY' : 'THROW',
      actionSub: 'SPACE / TAP',
      actionHot: this.state === 'run' && this.x > 29,
      actionDisabled: this.state !== 'run',
      javelin: true,
      angle: this.angle,
      angleValue: this.angle
    });
    this.game.setMiniBoard(
      this.game.fieldBoard('javelin', this.state === 'landed' ? this.result : null),
      'FIELD ORDER'
    );
  }

  spawnDust() {
    if (this.speed < 3) return;
    const crossed = Math.floor(this.phase / Math.PI);
    if (crossed !== this.lastPhase) {
      this.lastPhase = crossed;
      const x = this.world.sx(this.x) - 10;
      const y = this.game.groundY(1, 'javelin');
      this.game.spawnParticle({
        x, y: y - 2, vx: rand(-40, -8), vy: rand(-24, -4), life: rand(0.3, 0.55),
        size: rand(1.2, 3.2), color: 'rgba(255,216,160,.23)', gravity: 28
      });
    }
  }

  land() {
    this.state = 'landed';
    this.x = this.landX;
    this.landTimer = 0;
    this.game.sound.javelinLand();
    this.game.sound.cheer(1.1);
    this.game.shake = Math.max(this.game.shake, 5);
    const sx = this.world.sx(this.landX);
    const gy = this.game.groundY(1, 'javelin');
