    } else if (this.state === 'flight') {
      const pose = this.flightT < 0.35 ? 'release' : 'idle';
      drawAthlete(ctx, {
        x: sx, y: ground, scale, phase: this.phase, pose,
        speed: 0.2, kit: this.game.playerKit, glow: 0.2, shadow: 1
      });
