      const ty = ground - shoulder * (1 - uu) - this.peak * Math.sin(Math.PI * uu);
      ctx.fillStyle = `rgba(255,231,164,${0.13 * (1 - i / 7)})`;
      ctx.beginPath(); ctx.arc(tx, ty, 1.6, 0, Math.PI * 2); ctx.fill();
