    ctx.fillStyle = '#f7c950';
    ctx.font = '700 11px "Barlow Condensed", sans-serif';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillText(`${this.result.toFixed(2)}m`, landX, y - 19);
    ctx.restore();
  }
}

