  // Back limbs
  const backLeg = sk.legs.find(l => l.back) || sk.legs[0];
  const frontLeg = sk.legs.find(l => !l.back) || sk.legs[1];
  const backArm = sk.arms.find(a => a.back) || sk.arms[0];
  const frontArm = sk.arms.find(a => !a.back) || sk.arms[1];

  if (backLeg) {
