    ctx.fillStyle = g;
    ctx.fillRect(x, yTop, panelW, h);
    ctx.strokeStyle = 'rgba(118,153,190,.22)';
    ctx.lineWidth = 0.7;
    ctx.strokeRect(x, yTop, panelW, h);
    ctx.fillStyle = idx % 3 === 0 ? 'rgba(247,201,80,.86)' : 'rgba(239,244,250,.72)';
